(window.GIM_TS=window.GIM_TS||{})["Berakhot.3"]={"from":72,"a":[["\u0003כעבין\u0004 (ככרות עבים הנראים כלחמים ממש) — \u0003חייבין\u0004 בחלה, ואם \u0003כלמודין\u0004 (כלונסאות) — \u0003פטורים,\u0004 שבוודאי ישמשו רק לצורך הכותח. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: האי כובא דארעא מאי מברכין עלויה\u0004 \u0005[אותו בצק דליל הנאפה בכירה מה מברכים עליו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003מי סברת נהמא\u0004 \u0005[האם סבור אתה\u0006 ש\u0005לחם]\u0006 \u0003הוא?! גובלא בעלמא\u0004 \u0005[גיבול\u0006 בצק \u0005בלבד]\u0006 \u0003הוא ומברכין עלויה\u0004 \u0005[ומברכים עליו]\u0006 כעל שאר תבשילי דגן \u0003\"בורא מיני מזונות\".\u0004","ומסופר ש\u0003מר זוטרא קבע סעודתיה עלויה\u0004 \u0005[סעודתו עליו],\u0006 על בליל זה, \u0003וברך עלויה\u0004 \u0005[עליו]\u0006 לפני אכילתו \u0003\"המוציא לחם מן הארץ\", ו\u0004לאחר אכילתו \u0003שלש ברכות,\u0004 שמאחר שקבע עליו את ארוחתו הריהו מחשיבו בכך כלחם ממש.","והוסיף ו\u0003אמר מר בר רב אשי: ואדם יוצא בהן\u0004 במיני לחם אלה \u0003ידי חובתו בפסח\u0004 כמצה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003\"לחם עוני\" קרינן ביה\u0004 \u0005[קוראים אנו בו,\u0006 לו\u0005],\u0006 ללחם זה, ובכלל מצה הוא.","\u0003ו\u0004בענין ברכות \u0003אמר מר בר רב אשי: האי דובשא דתמרי\u0004 \u0005[דבש תמרים זה]\u0006 \u0003מברכין עלויה\u0004 \u0005[עליו]\u0006 \u0003\"שהכל נהיה בדברו\".\u0004 ו\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אין מברכים עליו \"פרי העץ\" כעל פרי התמר עצמו? — כי אותו דבש אינו מעיקר הפרי אלא \u0003זיעה בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא,\u0004 הנוטף מן הפרי הבשל.","\u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 עשה במנהגו זה? — \u0003כי האי\u0004 \u0005[כ\u0006דעת זה\u0005]\u0006 ה\u0003תנא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 \u0003דבש תמרים, ויין תפוחים וחומץ ספוניות\u0004 (ענבים הצומחים בסוף העונה ואינם מתבשלים אלא עושים מהם חומץ), \u0003ו\u0004כן \u0003שאר\u0004 מיני \u0003מי פירות\u0004 שהיו כולם \u0003של תרומה,\u0004 אם אכל מהם זר, \u0003ר' אליעזר מחייב\u0004 לשלם בכגון זה \u0003קרן וחומש,\u0004 כלומר, את גוף הנזק ועוד תוספת חומש, כקנס שמשלם המועל בקדשים. \u0003ור' יהושע פוטר\u0004 בכגון זה, שלדעתו הדברים שהוזכרו הינם רק מוצרי לוואי ואינם עיקר הפרי, וכשיטת ר' יהושע בתרומה פסק מר בר רב אשי לענין ברכה.","\u0003אמר ליה ההוא מרבנן\u0004 \u0005[לו אחד החכמים]\u0006 \u0003לרבא: טרימא מהו\u0004 דינו לענין ברכה? \u0003לא הוה אדעתיה\u0004 \u0005[היה בדעתו]\u0006 של \u0003רבא,\u0004 לא הבין, \u0003מאי קאמר ליה\u0004 \u0005[מה הוא אומר לו],\u0006 ששכח מה הוא טרימא. \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רבינא קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא, אמר ליה\u0004 \u0005[לו]\u0006 רבינא לאותו תלמיד השואל: האם לטרימא \u0003דשומשמי קאמרת\u0004 \u0005של שומשומין אתה אומר,\u0006 מתכוין\u0005],\u0006 \u0003או דקורטמי קאמרת\u0004 \u0005[של כרכום אתה אומר],\u0006 \u0003או דפורצני קאמרת\u0004 \u0005[של חרצני ענבים אתה אומר]?\u0006 \u0003אדהכי\u0004","\u0003והכי אסקיה\u0004 \u0005[בין כה וכה העלה]\u0006 \u0003רבא לדעתיה\u0004 \u0005[בדעתו],\u0006 נזכר ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 לאותו תלמיד: \u0003חשילתא\u0004 \u0005[\u0006ל\u0005דברים מעוכים]\u0006 \u0003ודאי קא אמרת\u0004 \u0005[אתה אומר,\u0006 מתכוין\u0005],\u0006 \u0003ואדכרתן מלתא הא\u0004 \u0005[והזכרתני דבר\u0006 הלכה \u0005זה]\u0006 ש\u0003אמר רב אסי: האי תמרי\u0004 \u0005[אותם תמרים]\u0006 \u0003של תרומה מותר לעשות מהן טרימא, ו\u0004אולם \u0003אסור לעשות מהן שכר.\u0004 שכאשר עושה מהתמרים טרימא הריהם נשארים בעינם, ואולם כאשר הוא עושה מהם שיכר הריהם מתקלקלים, ואסור לקלקל מאכל תרומה. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא ש\u0003תמרי ועבדינהו\u0004 \u0005[תמרים ועשאם]\u0006 \u0003טרימא\u0004 — \u0003מברכין עלוייהו\u0004 \u0005[עליהם]\u0006 \u0003\"בורא פרי העץ\". מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — משום ש\u0003במלתייהו קיימי כדמעיקרא\u0004 \u0005[שבדברם\u0006 בטבעם, הם \u0005עומדים כמתחילה].\u0006","שאלה אחרת נשאלה לגבי \u0003שתיתא\u0004 (מאכל העשוי מקמח שבלים קלויות שהוסיפו עליהן דבש או חומץ וכדומה), מה היא הברכה שמברכים עליו. \u0003רב אמר\u0004 שמברכים \u0003\"שהכל נהיה בדברו\", ושמואל אמר\u0004 שמברכים עליו \u0003\"בורא מיני מזונות\".\u0004","על כך העיר ו\u0003אמר רב חסדא: ולא פליגי\u0004 \u0005[ואינם חלוקים],\u0006 כי כל אחד מהם התכון למקרה אחר, \u0003הא\u0004 \u0005[זה]\u0006 שאמר שמואל שברכתו \"בורא מיני מזונות\" הרי זה \u0003ב\u0004אופן שבלילתו \u0003עבה, הא\u0004 \u0005[זה]\u0006 שאמר רב שברכתו \"שהכל\" הרי זה \u0003ב\u0004אופן שבלילתו \u0003רכה.\u0004 שכן \u0003עבה ל\u0004צורך \u0003אכילה עבדי לה\u0004 \u0005[עושים אותה]\u0006 ולכן ברכתה כדין שאר מזון העשוי מחמשת מיני דגן, ואילו \u0003רכה ל\u0004צורך \u0003רפואה קא עבדי לה\u0004 \u0005[עושים אותה],\u0006 ולכך אין לברך עליה אלא \"שהכל\".","על ההנחה שהשתיתא היא בעיקרה לצורך רפואה \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף,\u0004 והרי שנינו בדיני שבת: \u0003ושוין,\u0004 כלומר, הכל מסכימים \u0003שבוחשין\u0004 לכתחילה \u0003את השתות\u0004 (שתיתא) \u0003בשבת ו\u0004כן \u0003שותין זיתום המצרי\u0004 (סוג של תבלין חריף בקמח). \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי באכילת השתיתא \u0003לרפואה קא מכוין\u0004 \u0005[הוא מתכוין],\u0006 \u0003רפואה בשבת מי שרי\u0004 \u0005[האם מותרת]?!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003ואת לא תסברא\u0004 \u0005[ואתה אינך סבור\u0006 כן\u0005]?\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל האוכלין\u0004 הנאכלים כרגיל \u0003אוכל אדם\u0004 המתכוין \u0003לרפואה בשבת, וכל המשקין\u0004 שאינם מיוחדים לרפואה \u0003שותה\u0004 אדם. \u0003אלא מה אית\u0004 \u0005[יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]\u0006 כדי להתיר אופן ריפוי זה בשבת — \u0003גברא\u0004 \u0005[האיש]\u0006 \u0003לאכילה קא מכוין\u0004 \u0005[הוא מתכוין],\u0006 \u0003הכי נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003לאכילה קא מכוין\u0004 \u0005[הוא מתכוין]\u0006 ובוחש את השתות לצורך זה.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת],\u0006 נוסחה אחרת של הדברים נאמרה כך: \u0003אלא מה אית\u0004 \u0005[יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]\u0006 בענין המאכלים המרפאים — כי \u0003גברא\u0004 \u0005[האיש]\u0006 \u0003לאכילה קא מכוין\u0004 \u0005[הוא מתכוין],\u0006 \u0003ורפואה ממילא קא הויא\u0004 \u0005[נהיית,\u0006 נעשית\u0005],\u0006 \u0003הכי נמי\u0004 \u0005[כאן גם כן]\u0006 האיש \u0003לאכילה קא מכוין\u0004 \u0005[הוא מתכוין],\u0006 \u0003ורפואה ממילא קא הויא\u0004 \u0005[נהיית,\u0006 נעשית\u0005],\u0006 לכאורה, לאחר שהוכחנו שמותר לשתות את השתות בשבת, הרי שהיא ודאי מין אוכל וצריך לברך עליו, ואם כן תמוה הדבר לשם מה הוצרכו רב ושמואל לצין שצריך לברך עליהם?","ולכן אומרים: \u0003וצריכא\u0004 \u0005[ונצרכת]\u0006 האמרה של \u0003רב ושמואל. דאי מהאי הוה אמינא\u0004 \u0005[שאם מכאן,\u0006 מההיתר לשתות שתיתא בשבת, \u0005הייתי אומר]:\u0006 שהמדובר דווקא באופן שהאוכלם \u0003לאכילה קא מכוין\u0004 \u0005[הוא מתכוין]\u0006 \u0003ו\u0004דעתו שה\u0003רפואה ממילא קא הויא\u0004 \u0005[תיעשה,\u0006 תבוא\u0005],\u0006 \u0003אבל הכא\u0004 \u0005[כאן],\u0006 \u0003כיון\u0004 ש\u0003לכתחילה לרפואה קא מכוין\u0004 \u0005[הוא מתכוין]\u0006 באכילתו את השתיתא ולא לאכילה, ואם כן \u0003לא לבריך עלויה\u0004 \u0005[יברך עליו]\u0006 \u0003כלל\u0004 כדרך שאין מברכים על רפואות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב שאף כאן \u0003כיון דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003הנאה מיניה\u0004 \u0005[ממנו,\u0006 מאכילתו\u0005]\u0006 על כן \u0003בעי ברוכי\u0004 \u0005[צריך\u0006 הוא \u0005לברך].\u0006","שנינו במשנה \u0003שעל הפת הוא אומר\u0004 ברכת \u0003\"המוציא\u0004 לחם מן הארץ \u0003\". תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מה הוא,\u0004 האוכל פת, \u0003אומר\u0004 לפני אכילתה? — \u0003\"המוציא לחם מן הארץ\". ר' נחמיה אומר,\u0004 נוסח הברכה הוא: \u0003\"מוציא לחם מן הארץ\". אמר רבא: ב\u0004לשון \u0003\"מוציא\" כולי עלמא לא פליגי דאפיק\u0004 \u0005[הכל אינם חלוקים שהוציא]\u0006 לשון עבר \u0003משמע, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"אל מוציאם ממצרים\u0004 כתועפות ראם לו\u0003\"\u0004 (במדבר כג, כב). \u0003כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חלוקים]\u0006 הרי זה \u0003ב\u0004לשון \u0003\"המוציא\",\u0004 ש\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 ש\u0003\"המוציא\"\u0004 לשון \u0003דאפיק\u0004 \u0005[שהוציא]\u0006 בעבר \u0003משמע, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"המוציא לך מים מצור החלמיש\"\u0004 (דברים ח, טו), שהוא תיאור מה שהיה בעבר. \u0003ו\u0004אילו \u0003ר' נחמיה סבר\u0004 \u0005[סבור]\u0006 כי לשון \u0003\"המוציא\" דמפיק\u0004 \u0005[המוציא]\u0006 עכשיו, לשון הווה \u0003משמע.\u0004 וכפי \u0003שנאמר\u0004 בנבואת משה לישראל במצרים \u0003\"\u0004וידעתם כי אני ה' אלהיכם \u0003המוציא אתכם מתחת סבלות מצרים\"\u0004 (שמות ו, ז), ומכיון ש\"המוציא\" שימושו בלשון הווה (או אפילו עתיד), אין ראוי להשתמש במלה זו כברכה על העבר.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה משיבים הם על משמעות זו? — לדעתם משמעות הכתוב \u0003ההוא\u0004 היא כי \u0003הכי קאמר להו קודשא בריך הוא\u0004 \u0005[כך אמר להם הקדוש ברוך הוא]\u0006 \u0003לישראל: כד מפיקנא לכו\u0004 \u0005[כאשר אוציא אתכם],\u0006 \u0003עבידנא לכו מלתא\u0004 \u0005[אעשה לכם דבר]\u0006 \u0003כי היכי דידעיתו דאנא\u0004 \u0005[כדי שתדעו שאני]\u0006 \u0003הוא דאפיקית יתכון\u0004 \u0005[שהוצאתי אתכם]\u0006 \u0003ממצרים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וידעתם כי אני ה' אלהיכם המוציא\",\u0004 ולכן גם בפסוק זה \"המוציא\" היא לשון עבר.","ומענין זה מסופר: היו \u0003משתבחין ליה רבנן\u0004 \u0005[בו חכמים]\u0006 בפני \u0003ר' זירא\u0004 את \u0003בר\u0004 \u0005[בן]\u0006 \u0003רב זביד אחוה\u0004 \u0005[אחיו]\u0006 של \u0003ר' שמעון בר\u0004 \u0005[בן]\u0006 \u0003רב זביד\u0004 ש\u0003אדם גדול הוא ובקי בברכות הוא. אמר להם\u0004 ר' זירא לחכמים: \u0003לכשיבא לידכם הביאוהו לידי,\u0004 כדי שאוכל להכירו. \u0003זמנא חדא איקלע לגביה אפיקו ליה ריפתא\u0004 \u0005[יום אחד נקלע אצלו הוציאו לו לחם]\u0006 לאורח, \u0003פתח ואמר \"מוציא\u0004 לחם מן הארץ \u0003\".\u0004 התרעם ר' זירא ו\u0003אמר: זה הוא שאומרים עליו\u0004 ש\u0003אדם גדול הוא ובקי בברכות הוא?! בשלמא אי אמר\u0004 \u0005[נניח אם היה אומר]\u0006 בלשון \u0003\"המוציא\"\u0004"],["הייתי מבין כי בכך \u0003אשמעינן טעמא\u0004 \u0005[השמיע לנו טעם]\u0006 הפסוק \"המוציא אתכם מתחת סבלות מצרים\", \u0003ואשמעינן דהלכתא כרבנן\u0004 \u0005[והשמיע לנו שהלכה כחכמים].\u0006 \u0003אלא\u0004 כש\u0003אמר\u0004 בלשון \u0003\"מוציא\"\u0004 אם כן \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך? שהרי הכל מודים שיוצא ידי חובה כשאומר \"מוציא\". ומסבירים: \u0003ואיהו דעבד\u0004 \u0005[והוא,\u0006 בר רב זביד, \u0005שעשה]\u0006 כן מפני שרצה \u0003לאפוקי נפשיה מפלוגתא\u0004 \u0005[להוציא עצמו מן המחלוקת],\u0006 והעדיף לברך בלשון הראויה לדעת הכל, ולא להשמיע חידוש שאינו מוסכם על הכל.","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא שיש לומר \u0003\"המוציא לחם מן הארץ\", דקיימא לן כרבנן\u0004 \u0005[ש\u0006כן \u0005מוחזק לנו כ\u0006שיטת \u0005חכמים],\u0006 \u0003דאמרי\u0004 \u0005[האומרים]\u0006 כי לשון זו לשון \u0003דאפיק\u0004 \u0005שהוציא]\u0006 \u0003משמע.\u0004","שנינו במשנה ש\u0003על הירקות אומר\u0004 ברכת \"בורא פרי האדמה\". ומעירים: \u0003קתני\u0004 \u0005[שנה]\u0006 \u0003ירקות דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003פת\u0004 לחם, ומהשוואה זו יש ללמוד: \u0003מה פת\u0004 היא דבר מאכל \u0003שנשתנה על ידי האור\u0004 (אש), כלומר, שהגיע למצבו הנוכחי על ידי אפיה באש, \u0003אף ירקות נמי\u0004 \u0005[גם כן]\u0006 ברכתם \"בורא פרי האדמה\" גם באופן \u0003שנשתנו על ידי האור,\u0004 ולא רק ירקות חיים. \u0003אמר רבנאי משמיה\u0004 \u0005[בשמו]\u0006 של \u0003אביי: זאת אומרת\u0004 כי \u0003שלקות\u0004 (ירקות שנתבשלו) \u0003מברכין עליהן \"בורא פרי האדמה\". ממאי\u0004 \u0005[ממה]\u0006 למד אתה כן? — \u0003מדקתני\u0004 \u0005[ממה ששנה]\u0006 \u0003ירקות דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003פת.\u0004","וכן \u0003דרש רב חסדא משום\u0004 (בשם) \u0003רבינו,\u0004 אשר בדרך אגב מעירים: \u0003ומנו\u0004 \u0005[ומיהו]\u0006 — \u0003רב, שלקות מברכין עליהן \"בורא פרי האדמה\". ו\u0004אילו \u0003רבותינו היורדין מארץ ישראל,\u0004 ששוב מעירים בדרך הסבר: \u0003ומנו\u0004 \u0005[ומיהו]\u0006 החכם שכך כינויו — \u0003עולא משמיה\u0004 \u0005[בשמו]\u0006 של \u0003ר' יוחנן אמר: שלקות מברכין עליהן \"שהכל נהיה בדברו\",\u0004 לפי שלאחר שליקתם פסקו להיות ירקות באותו טיב כמקודם. ורב חיסדא מדעת עצמו אמר, \u0003ואני אומר\u0004 שיש לקבוע שיטה ממוצעת: \u0003כל\u0004 ירק \u0003שתחלתו,\u0004 כלומר, בעודנו חי מברכים עליו \u0003\"בורא פרי האדמה\",\u0004 שהוא ראוי כבר לאכילה, אם \u0003שלקו\u0004 מברך עליו \u0003\"שהכל נהיה בדברו\",\u0004 כי שליקתו פוגמת בטיבו. \u0003וכל\u0004 וירק \u0003שתחלתו\u0004 היתה ראויה רק לברכה \u0003\"שהכל נהיה בדברו\",\u0004 שאין רגילים לאוכלו חי, וכשמבשלים אותו זו דרך אכילתו הרגילה, אם \u0003שלקו\u0004 צריך לברך עליו \u0003\"בורא פרי האדמה\".\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003כל שתחלתו\u0004 ברכתו \u0003\"שהכל נהיה בדברו\"\u0004 וכאשר \u0003שלקו\u0004 ברכתו \u0003\"בורא פרי האדמה\",\u0004 שיש ירק שנעשה טוב יותר על ידי הבישול ובעודו חי אי אפשר כמעט לאוכלו, \u0003משכחת לה בכרבא וסלקא וקרא\u0004 \u0005[מוצא אתה אותה\u0006 דוגמא \u0005בכרוב בסלקא ובדלעת],\u0006 \u0003אלא כל\u0004 ירק \u0003שתחלתו\u0004 ברכתו \u0003\"בורא פרי האדמה\",\u0004 וכאשר \u0003שלקו\u0004 ברכתו \u0003\"שהכל\",\u0004 משום שהירק מתקלקל על ידי הבישול \u0003היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותו]?\u0006 \u0003אמר רב נחמן בר יצחק: משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 דוגמא לכך \u0003בתומי וכרתי\u0004 \u0005[בשומים וכרישים].\u0006","\u0003דרש רב נחמן משום\u0004 (בשם) \u0003רבינו, ומנו\u0004 \u0005[ומיהו]\u0006 — \u0003שמואל: שלקות\u0004 (ירקות מבושלים) \u0003מברכין עליהם \"בורא פרי האדמה\". וחברינו היורדים מארץ ישראל, ומנו\u0004 \u0005[ומיהו]\u0006 — \u0003עולא משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן אמר: שלקות מברכין עליהן \"שהכל נהיה בדברו\".\u0004","ועל כך העיר רב נחמן: \u0003ואני אומר\u0004 כי כבר \u0003במחלוקת\u0004 תנאים היא \u0003שנויה,\u0004 ותלויה בה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 בענין דיני מצה בפסח: \u0003יוצאין\u0004 למצות מצה \u0003ברקיק השרוי\u0004 במים או \u0003ב\u0004רקיק ה\u0003מבושל\u0004 כל עוד \u0003לא נמוח\u0004 במים, אלו \u0003דברי ר' מאיר, ור' יוסי אומר שיוצאים\u0004 אמנם ידי חובת מצה \u0003ברקיק השרוי, אבל לא במבושל, אף על פי שלא נמוח.\u0004 ומסיק רב נחמן שמחלוקת זו ביחס למצה המבושלת משקפת מחלוקת בדבר בישול בכלל אם הוא מוריד מטעמו של הדבר המבושל או לא.","שיטה זו נדחית בגמרא: \u0003ולא היא,\u0004 דבר זה אינו נכון, אלא \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003שלקות מברכין עליהן \"בורא פרי האדמה\", ו\u0004אולם \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יוסי התם\u0004 \u0005[שם]\u0006 הלכה זו שיוצא ידי חובת מצה רק בשרוי ולא במבושל, \u0003אלא משום דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שיהיה ברקיק המבושל \u0003טעם מצה, וליכא\u0004 \u0005[ואין]\u0006 בו, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בירקות מבושלים \u0003אפילו ר' יוסי מודה\u0004 שהבישול אינו פוגמם.","מקודם נזכרו דברי עולא בשם ר' יוחנן ועתה מביאים את המקורות לדברי ר' יוחנן. והיו כאן שתי מסורות: \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: שלקות מברכין עליהם \"בורא פרי האדמה\", ו\u0004אילו \u0003ר' בנימין בר יפת אמר ר' יוחנן: שלקות מברכין עליהם \"שהכל נהיה בדברו\".\u0004 על כך \u0003אמר רב נחמן בר יצחק: קבע עולא לשבשתיה\u0004 \u0005[את שיבושו,\u0006 טעותו\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' בנימין בר יפת,\u0004 שהרי עולא מסר בבבל את דברי ר' יוחנן כגירסת ר' בנימין בר יפת, ובניגוד לדעת חכמי בבל.","ועל דרכו זו של עולא עוד \u0003תהי\u0004 \u0005[תהה]\u0006 \u0003בה ר' זירא: וכי מה ענין ר' בנימין בר יפת אצל ר' חייא בר אבא,\u0004 כלומר, כיצד אפשר היה בכלל להשוות בין ר' בנימין בר יפת לבין ר' חייא בר אבא? שהרי \u0003ר' חייא בר אבא דייק וגמיר שמעתא\u0004 \u0005[היה מדייק ולומד הלכה]\u0006 \u0003מר' יוחנן רביה\u0004 \u0005[רבו]\u0006 \u0003ור' בנימין בר יפת לא דייק\u0004 \u0005[היה מדייק].\u0006 \u0003ועוד, ר' חייא בר אבא כל תלתין יומין\u0004 \u0005[שלושים יום]\u0006 היה \u0003מהדר תלמודיה קמיה\u0004 \u0005[חוזר על תלמודו לפני]\u0006 \u0003ר' יוחנן רביה\u0004 \u0005[רבו]\u0006 \u0003ור' בנימין בר יפת לא מהדר\u0004 \u0005[היה חוזר].\u0006 \u0003ועוד, בר מן דין ובר מן דין\u0004 \u0005[חוץ מזה וחוץ מזה],\u0006 מלבד נימוקים אלה של ההבדל בין תלמיד חכם דייקן כר' חייא בר אבא לבין ר' בנימין בר יפת, אפשר להביא ראיה גם ממנהגיו של ר' יוחנן, שכן \u0003ההוא תורמסא דשלקי ליה\u0004 \u0005[אותו תורמוס שמבשלים אותו]\u0006 \u0003שבע זמנין\u0004 \u0005[פעמים]\u0006 \u0003בקדרה ואכלי ליה\u0004 \u0005[ואוכלים אותו]\u0006 \u0003בקנוח סעודה. אתו\u0004 \u0005[באו]\u0006 \u0003ושאלו לר' יוחנן\u0004 מהו ברכתו, \u0003ואמר להו\u0004 \u0005[להם]\u0006 ש\u0003מברכין עלויה\u0004 \u0005[עליו]\u0006 \u0003\"בורא פרי האדמה\",\u0004 הרי שעל ירקות שלוקים מברכים ברכה זו.","\u0003ועוד,\u0004 הרי \u0003אמר ר' חייא בר אבא: אני\u0004 עצמי \u0003ראיתי את ר' יוחנן שאכל זית מליח,\u0004 ולפי ההלכה מלוח הריהו כמבושל, \u0003ובריך\u0004 \u0005[וברך]\u0006 \u0003עליו תחלה וסוף,\u0004 לפניו ולאחריו. \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי \u0003שלקות במילתייהו קיימי\u0004 \u0005[בדברם,\u0006 במקומם הם \u0005עומדים]\u0006 ואין הבישול פוגם בטיבם, ודאי \u0003בתחלה\u0004 היה \u0003מברך עליו \"בורא פרי העץ\", ולבסוף מברך עליו ברכה אחת מעין שלש,\u0004 כדרך שמברכים על כל אחד משבעת המינים שנשתבחה בהם ארץ ישראל. \u0003אלא אי\u0004 \u0005[אם]\u0006 \u0003אמרת\u0004 כי ה\u0003שלקות לאו במילתייהו קיימי\u0004 \u0005[לא במקומם\u0006 הם \u0005עומדים],\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 כי \u0003בתחלה מברך עליו,\u0004 על הזית, \u0003\"שהכל נהיה בדברו\", אלא לבסוף מאי\u0004 \u0005[מה]\u0006 הוא \u0003מברך?\u0004 שלפי כמה שיטות דבר שמברכים עליו מתחילה \"שהכל\" — אין אחריו ברכה אחרונה!","ודוחים: מכאן אין ראיה, \u0003דילמא\u0004 \u0005[שמא]\u0006 סבור ר' יוחנן שדבר שמברכים עליו מתחילה \"שהכל\" יש לברך לאחריו \u0003\"בורא נפשות רבות וחסרונן על כל מה שברא\".\u0004","על שיטה זו שירקות שלוקים דינם כירקות חיים לענין ברכה \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' יצחק בר שמואל\u0004 ממה ששנינו בברייתא הדנה בהלכות אכילת מרור בפסח: \u0003ירקות שאדם יוצא בהן ידי חובתו\u0004 למצות מרור \u0003בפסח\u0004 — \u0003יוצא\u0004 גם \u0003בהן ו\u0004גם \u0003בקלח\u0004 (בענף) \u0003שלהן, אבל\u0004 אינו יוצא בהם \u0003לא\u0004 אם היו \u0003כבושין, ולא שלוקין ולא מבושלין. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך לומר]\u0006 כי \u0003במילתייהו קאי\u0004 \u0005[בדברם,\u0006 במקומם הם \u0005עומדים]\u0006 אם כן \u0003שלוקין אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יהיו כשרים לצורך מרור?","ומשיבים: \u0003שאני התם, דבעינן\u0004 \u0005[שונה שם, שאנו צריכים]\u0006 שיהיה בהם \u0003טעם מרור, וליכא\u0004 \u0005[ואין],\u0006 שבדין מרור איננו מתחשבים בטיבם של הירקות, אלא בטעם המרירות שבהם, והוא עובר כתוצאה מהבישול, ואולם אין מכך ראיה כללית שהבישול פוגם את הירקות.","כבר סופר שר' יוחנן ברך על זית מלוח, ועל כן \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא: ר' יוחנן היכי\u0004 \u0005[איך]\u0006 היה \u0003מברך על זית מליח?\u0004 והלא \u0003כיון דשקילא לגרעיניה\u0004 \u0005[שניטל גרעינו]\u0006"],["\u0003בצר ליה שיעורא\u0004 \u0005[פחת לו שיעורו],\u0006 כי שיעור קטן ביותר של אכילה הוא כזית לפחות, והזית בלא גרעינו הוא פחות משיעור זה.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי \u0003כזית גדול בעינן\u0004 \u0005[אנו צריכים]\u0006 לשיעור אכילה? \u0003כזית בינוני בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003והא איכא\u0004 \u0005[וזה\u0006 הלא \u0005ישנו],\u0006 שכן הזית \u0003ההוא דאייתו לקמיה\u0004 \u0005[שהביאו לפני]\u0006 \u0003ר' יוחנן, זית גדול הוה\u0004 \u0005[היה],\u0006 \u0003דאף על גב דשקלוה לגרעינותיה, פש ליה שיעורא\u0004 \u0005[שאף על פי שהוציאו את גרעינו, נשאר לו השיעור].\u0006","וראיה לכך ששיעור זית אינו כזית גדול ממה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003זית שאמרו\u0004 חכמים בדיני שיעורים אינו \u0003לא קטן ולא גדול, אלא בינוני. וזהו\u0004 הזית הנקרא \u0003אגורי. ואמר ר' אבהו:\u0004 זית זה \u0003לא \"אגורי\" שמו\u0004 האמיתי \u0003אלא \"אברוטי\" שמו. ואמרי ליה\u0004 \u0005[ויש שאומרים]\u0006 ש\u0003\"סמרוסי\" שמו. ולמה נקרא שמו \"אגורי\"\u0004 — מפני \u0003ששמנו אגור בתוכו,\u0004 והרי זה רק כינוי לזן הזיתים.","ומציעים עוד בענין ברכת השלקות שעסקו בה קודם לכן: \u0003נימא כתנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שבעיה זו היא \u0005כ\u0006אותה מחלוקת \u0005תנאים]\u0006 בנושא זה, כמסופר: \u0003דהנהו תרי תלמידי דהוו יתבי קמיה\u0004 \u0005[שאותם שני תלמידים שהיו יושבים לפני]\u0006 \u0003בר קפרא,\u0004 ו\u0003הביאו לפניו כרוב\u0004 מבושל \u0003ודורמסקין\u0004 מבושלים \u0003ופרגיות,\u0004 ו\u0003נתן בר קפרא רשות לאחד מהן לברך. קפץ\u0004 (הזדרז) \u0003וברך על הפרגיות. לגלג עליו חבירו\u0004 על שהקדים מתוך רעבתנות ברכה שהיה צריך לברך אחר כך. \u0003כעס בר קפרא\u0004 על שניהם וכך \u0003אמר: לא על המברך אני כועס, אלא על המלגלג אני כועס,\u0004 כי \u0003אם חבירך דומה כמי שלא טעם טעם בשר מעולם,\u0004 ובשל כך נעשה בשר הפרגיות כה חביב עליו ובשל כך מיהר לאוכלו, \u0003אתה על מה לגלגת עליו?\u0004 ו\u0003חזר ואמר\u0004 לשני: \u0003לא על המלגלג אני כועס, אלא על המברך אני כועס,\u0004 והוסיף \u0003ואמר: אם חכמה אין כאן, זקנה אין כאן?!\u0004 כלומר, אף אם אין בך דעת להחליט בעצמך על מה יש לברך קודם, הלא יכולת לשאול אותי, שאני זקן ממך.","והוסיפו על כך, \u0003תנא\u0004 \u0005[שנינו]:\u0006 \u0003ושניהם לא הוציאו שנתן,\u0004 שמשום כעסו של בר קפרא נענשו ומתו שניהם באותה שנה, ומכאן רוצים להסיק לענייננו:","\u0003מאי לאו בהא קא מיפלגי\u0004 \u0005[האם לא בזה הם חולקים],\u0006 שה\u0003מברך\u0004 שהקדים את הפרגיות \u0003סבר\u0004 \u0005[סבור היה]\u0006 שהברכה על \u0003שלקות ופרגיות\u0004 היא \u0003\"שהכל נהיה בדברו\", הלכך\u0004 \u0005[לכן]\u0006 מאכל שהוא \u0003חביב\u0004 יותר בעיני האוכל \u0003עדיף\u0004 ויש להקדימו בברכה, \u0003ו\u0004אילו ה\u0003מלגלג סבר\u0004 \u0005[סבור היה]\u0006 שעל ה\u0003שלקות\u0004 מברכים \u0003\"בורא פרי האדמה\",\u0004 ועל \u0003פרגיות\u0004 מברכים \u0003\"שהכל נהיה בדברו\", הלכך פירא\u0004 \u0005[לכן הפרי]\u0006 \u0003עדיף,\u0004 שברכתו מעולה יותר.","הסבר זה דוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 כי על \u0003שלקות ופרגיות\u0004 מברכים \u0003\"שהכל נהיה בדברו\",\u0004 אלא \u0003הכא בהאי סברא קמיפלגי\u0004 \u0005[וכאן בסברה זו הם חלוקים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 המברך \u0005סבור היה]\u0006 שהמין ה\u0003חביב עדיף\u0004 להקדימו בברכה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 המלגלג \u0005סבור היה]\u0006 שה\u0003כרוב עדיף, דזיין\u0004 \u0005[מפני שהוא מזין].\u0006","\u0003אמר ר' זירא: כי הוינן בי\u0004 \u0005[כאשר היינו בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב הונא אמר לן\u0004 \u0005[לנו]:\u0006 \u0003הני גרגלידי דלפתא\u0004 \u0005[ראשי לפתות אלה],\u0006 אם \u0003פרמינהו פרימא רבא\u0004 \u0005[חותכם חיתוך מרובה]\u0006 עד שנעשים חתיכות קטנות מאד — הרי בכך הוא משביח את טעמם ולכך מברכים עליהם \u0003\"בורא פרי האדמה\",\u0004 ואם חותכם \u0003פרימא זוטא\u0004 \u0005[חיתוך מועט],\u0006 שנעשים חתיכות גדולות מברך עליהם \u0003\"שהכל נהיה בדברו\". וכי אתאן לבי\u0004 \u0005[וכאשר באנו לבית\u0006 מדרשו\u0005]\u0006 של \u0003רב יהודה אמר לן\u0004 \u0005[לנו]:\u0006 \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 ברכתם \u0003\"בורא פרי האדמה\", והא דפרמינהו טפי\u0004 \u0005[וזה שחתכם יותר],\u0006 הרי זה היה \u0003כי היכי דנמתיק טעמיה\u0004 \u0005[כדי שימתיק טעמו].\u0006","מעין זה \u0003אמר רב אשי: כי הוינן בי\u0004 \u0005[כאשר היינו בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב כהנא, אמר לן\u0004 \u0005[לנו]:\u0006 \u0003תבשילא דסלקא, דלא מפשו בה קמחא\u0004 \u0005[תבשיל של תרדים, שאין מרבים בו קמח]\u0006 ברכתו \u0003\"בורא פרי האדמה\",\u0004 ותבשיל \u0003דלפתא, דמפשו בה קמחא טפי\u0004 \u0005[של לפת, שמרבים בו קמח יותר]\u0006 ברכתו \u0003\"בורא מיני מזונות\". והדר\u0004 \u0005[וחזר]\u0006 רב כהנא מדבריו הראשונים ו\u0003אמר: אידי ואידי\u0004 \u0005[\u0006על \u0005זה וזה]\u0006 מברכים \u0003\"בורא פרי האדמה\", והאי דשדו בה קמחא טפי\u0004 \u0005[וזה שמשלכים,\u0006 נותנים \u0005בה קמח יותר]\u0006 הרי \u0003לדבוקי בעלמא עבדי ליה\u0004 \u0005[להדבקה בלבד עושים לו\u0006 זאת\u0005],\u0006 והתבשיל העיקרי הוא הלפת שבקדרה ולא הקמח,","ומכיון שדובר בתבשיל תרדים, הוסיף ו\u0003אמר רב חסדא\u0004 דברים בשבחו: \u0003תבשיל של תרדין יפה ללב וטוב לעינים וכל שכן\u0004 שהוא מועיל \u0003לבני מעים.\u0004 על כך \u0003אמר אביי: והוא\u0004 דווקא באופן \u0003דיתיב אבי תפי, ועביד\u0004 \u0005[שיושב\u0006 התבשיל \u0005על הכירה, ועושה]\u0006 \u0003\"תוך תוך\",\u0004 כלומר, רותח.","\u0003אמר רב פפא: פשיטא\u0004 \u0005[פשוט,\u0006 מובן\u0005]\u0006 \u0003לי\u0004 כי \u0003מיא דסלקא\u0004 \u0005[מי סלק],\u0006 מים שנתבשל בהם הסלק — \u0003כסלקא\u0004 \u0005[כסלק]\u0006 נחשבים, \u0003ומיא דלפתא\u0004 \u0005[ומי הלפת]\u0006 — \u0003כלפתא\u0004 \u0005[כלפת],\u0006 \u0003ומיא דכולהו שלקי\u0004 \u0005[ומי כל השלקים]\u0006 — \u0003ככולהו שלקי\u0004 \u0005[ככל השלקים]\u0006 עצמם. ואולם \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: מיא דשיבתא מאי\u0004 \u0005[מי השבת,\u0006 תבלין הניתן בקערה, \u0005מה\u0006 הם\u0005]?\u0006 וצדדי הבעיה: האם \u0003למתוקי טעמא עבדי\u0004 \u0005[למתק\u0006 את \u0005הטעם\u0006 בקדרה \u0005עושים\u0006 אותו\u0005],\u0006 \u0003או\u0004 שמא \u0003לעבורי\u0004 \u0005[להעביר]\u0006 את ה\u0003זוהמא עבדי לה\u0004 \u0005[עושים אותו]?\u0006 שאם נתינת השבת במאכל היא כדי לתת בו טעם הרי המים שנתבשלה בהם דינם כמרק של שאר ירקות, ואולם אם שמים את השבת רק להסיר את הזוהמה מן המאכל — כדי שהשבת תספוג את הקצף ושאריות המרק, הרי שאין מעוניינים מלכתחילה בטעמה, ואין לברך על מרק ממנה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו במשנה במסכת עוקצין האומרת כי \u0003השבת מש\u0004 כבר \u0003נתנה טעם בקדירה אין בה משום תרומה,\u0004 שאם היתה השבת של תרומה, לאחר שנתנה טעם אינה עוד בעלת ערך ושוב אינה נחשבת כתרומה, \u0003ו\u0004כן \u0003אינה מטמאה טומאת אוכלים,\u0004 מפני שיצאה מכלל אוכל. \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי השבת \u0003למתוקי טעמא עבדי לה\u0004 \u0005[למתק\u0006 את \u0005הטעם עושים אותה].\u0006 ומסכמים אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","\u0003אמר רב חייא בר אשי: פת צנומה\u0004 (מיובשת) ששמו אותה להישרות \u0003בקערה מברכין עליה \"המוציא\"\u0004 אף אם היה לפניו ככר לחם אחר, שדינה כלחם שלם לכל דבר. \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 הלכה זו על דברי \u0003ר' חייא,\u0004 ש\u0003אמר ר' חייא: צריך שתכלה ברכה עם הפת,\u0004 כלומר, את ברכת \"המוציא\" יש לברך עם חתיכתה של הפרוסה מככר הלחם, והפת הצנומה הריהי כבר פרוסה ועומדת.","על הנחה זו \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רבא: מאי שנא\u0004 \u0005[במה שונה]\u0006 פת \u0003צנומה\u0004 ש\u0003לא\u0004 מברכים עליה \"המוציא\" — \u0003משום דכי כליא\u0004 \u0005[שכאשר מסתיימת]\u0006 ה\u0003ברכה\u0004 — על \u0003פרוסה קא כליא\u0004 \u0005[היא נגמרת],\u0006 והרי \u0003על הפת נמי\u0004 \u0005[גם כן],\u0006 \u0003כי קא גמרה\u0004 \u0005[כאשר מסתיימת]\u0006 הברכה הלא על \u0003פרוסה גמרה\u0004 \u0005[היא מסתיימת]\u0006 שהרי חותכים את הלחם לפני הברכה!"],["\u0003אלא אמר רבא:\u0004 אף בבציעת הלחם יש לנהוג ש\u0003מברך ואחר כך בוצע,\u0004 וכך תכלה הברכה על הפת השלמה.","מסופר: \u0003נהרדעי עבדי\u0004 \u0005[חכמי נהרדעא עשו]\u0006 \u0003כ\u0004שיטת \u0003ר' חייא\u0004 שעם בציעת הלחם היו מברכים עליו, ומסיימים את הברכה עם גמר חתיכתה של הפרוסה, \u0003ו\u0004אילו \u0003רבנן עבדי\u0004 \u0005[חכמים עשו]\u0006 \u0003כרבא\u0004 שקודם היה מברך ואחר כך חותך את הלחם. \u0003אמר רבינא: אמרה לי אם\u0004 (אמי): \u0003אבוך עביד\u0004 \u0005[אביך היה עושה]\u0006 \u0003כר' חייא, דאמר ר' חייא: צריך שתכלה ברכה עם הפת. ו\u0004אילו \u0003רבנן עבדי\u0004 \u0005[חכמים עשו]\u0006 \u0003כרבא\u0004. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא \u0003כרבא,\u0004 ש\u0003אמר\u0004 ש\u0003מברך\u0004 בתחילה על הלחם \u0003ואחר כך בוצע\u0004 ממנו.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בענין בעיות הברכה על פת שלמה או פרוסה: אם \u0003הביאו לפניהם,\u0004 לפני המסובין \u0003פתיתין ושלמין,\u0004 פרוסות לחם וככרות לחם שלמים, \u0003אמר רב הונא: מברך על הפתיתין ופוטר\u0004 בברכה זו אף \u0003את השלמין. ור' יוחנן אמר\u0004: לברך על ה\u0003שלמה\u0004 הרי זה \u0003מצוה מן המובחר. אבל\u0004 אם היתה פת \u0003פרוסה של חטין ושלמה מן השעורין, דברי הכל\u0004 ש\u0003מברך על הפרוסה של חטין,\u0004 שאף שהיא פרוסה, מכל מקום היא מעולה \u0003ו\u0004בכך הוא \u0003פוטר את השלמה של שעורין.\u0004","\u0003אמר ר' ירמיה בר אבא\u0004 מחלוקת זו בין רב הונא ור' יוחנן היא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 אחרת בדיני תרומה. ששנינו: \u0003תורמין בצל קטן שלם, אבל לא חצי בצל גדול,\u0004 אף על פי שהם שווים בכמותם. \u0003ר' יהודה אומר: לא כי, אלא חצי בצל גדול\u0004 עדיף. \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' יהודה \u0005סבור]\u0006 כי דבר \u0003חשוב עדיף,\u0004 ולכן לדעתו חצי בצל גדול שטיבו מעולה יותר — עדיף. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 תנא קמא \u0005סבור]\u0006 כי דבר \u0003שלם עדיף\u0004.","את ההשוואה הזו דוחים: \u0003היכא דאיכא\u0004 \u0005[היכן שיש]\u0006 \u0003כהן\u0004 היכול לקחת מיד את התרומה, \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003חשוב עדיף, כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חלוקים]\u0006 הרי זה באופן \u0003דליכא\u0004 \u0005[שאין]\u0006 שם \u0003כהן. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל מקום שיש כהן\u0004 — \u0003תורם מן היפה, וכל מקום שאין כהן\u0004 — \u0003תורם מן המתקיים,\u0004 דבר שיחזיק מעמד זמן רב יותר, כדי שיוכל הכהן ליהנות ממנו. \u0003ר' יהודה אומר:\u0004 לעולם \u0003אין תורם אלא מן היפה\u0004 אף שאינו מתקיים.","ולגבי עצם המחלוקת בין ר' יוחנן ורב הונא \u0003אמר רב נחמן בר יצחק: וירא שמים יוצא ידי שניהם, ומנו\u0004 \u0005[ומיהו]\u0006 ירא שמים זה? — \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא,\u0004 שכן מסופר ב\u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא\u0004 שמנהגו שהיה \u0003מניח פרוסה בתוך השלמה ובוצע\u0004 על שתיהן.","וכן מסופר ש\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב נחמן בר יצחק: מניח הפרוסה בתוך השלמה ובוצע ומברך. אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003מה שמך? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שלמן. אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן במשחק מילים: \u0003שלום אתה ושלמה משנתך, ששמת שלום בין התלמידים\u0004 שעל ידי ברייתא זו מתיישבות הדעות החולקות.","פתרון זה, מחוזק במקרה מיוחד, ש\u0003אמר רב פפא: הכל מודים בפסח,\u0004 באכילת מצה לשם מצוה, \u0003שמניח פרוסה בתוך שלמה ובוצע. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? ביחס למצה לשון — \u0003\"לחם עני\"\u0004 (דברים טז, ג) \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקרא, ודרכם של עניים לאכול לחמם בפרוסות ויש חשיבות, איפוא, אף במצה הפרוסה.","ואגב דיני בציעת הפת, ובפרט בחג, מביאים דבר הלכה ש\u0003אמר ר' אבא: ובשבת חייב אדם לבצוע\u0004 בסעודה \u0003על שתי ככרות. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — בפרשת המן בפסוק המדבר מענין הלקיטה ביום שישי לצורך שבת, לשון \u0003\"לחם משנה\" (שמות טז, כב) כתיב\u0004 \u0005[נאמר],\u0006 וכזכר לכך גם סעודות השבת הן על לחם משנה.","על דרך הבציעה \u0003אמר רב אשי: חזינא ליה\u0004 \u0005[ראיתי אותו]\u0006 את \u0003רב כהנא דנקיט תרתי ובצע חדא\u0004 \u0005[שהיה מחזיק שתי\u0006 ככרות \u0005ובוצע אחת].\u0006 \u0003ר' זירא הוה בצע\u0004 \u0005[היה בוצע]\u0006 בסעודת שבת \u0003אכולא שירותא\u0004 \u0005[לכל הסעודה],\u0006 שהיה חותך מתחילה פרוסה גדולה אחת וממנה היה אוכל כל הסעודה. על כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: והא קא מתחזי כרעבתנותא\u0004 \u0005[והרי זה נראה כרעבתנות]\u0006 כאשר אדם פורס פרוסה גדולה כל כך לאכול ממנה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003כיון\u0004 ש\u0003כל יומא\u0004 \u0005[יום]\u0006 הוא \u0003לא קעביד הכי\u0004 \u0005[עושה כן],\u0006 \u0003והאידנא קא עביד\u0004 \u0005[ועכשיו הוא עושה]\u0006 \u0003לא מתחזי כרעבתנותא\u0004 \u0005[נראה\u0006 זה \u0005כרעבתנות]\u0006 אלא כחיבוב מצות סעודת שבת.","ובענין אכילת שבת מסופר: \u0003רב אמי ורב אסי כי הוה מתרמי להו ריפתא דערובא\u0004 \u0005[כאשר היה מזדמן להם לחם,\u0006 שעשו בו \u0005עירוב]\u0006 היו \u0003מברכין עליה\u0004 \u0005[עליו]\u0006 \u0003\"המוציא לחם מן הארץ\"\u0004 בסעודת השבת. \u0003אמרי\u0004 \u0005[אמרו]\u0006 את טעמם: \u0003הואיל ואתעביד ביה\u0004 \u0005[ונעשתה בו]\u0006 \u0003מצוה חדא\u0004 \u0005[אחת],\u0006 \u0003נעביד ביה\u0004 \u0005[נעשה בו]\u0006 \u0003מצוה אחריתי\u0004 \u0005[אחרת].\u0006"],["ועוד בדיני בציעת הפת \u0003אמר רב:\u0004 מי שבצע פרוסת לחם ולפני שאכל ממנה הגיש פרוסה לאחר, ואמר לו \u0003\"טול ברוך, טול ברוך\"\u0004 \u0005[קח\u0006 ו\u0005ברך, קח\u0006 ו\u0005ברך]\u0006 — \u0003אינו צריך לברך\u0004 שנית, כי הפסקה זו נחשבת לחלק מצורך הברכה; ואולם אם אמר \u0003\"הבא מלח\"\u0004 או \u0003\"הבא לפתן\"\u0004 — \u0003צריך לברך.\u0004 שזו כבר נחשבת להפסקה בין הברכה לבציעה. \u0003ור' יוחנן אמר: אפילו\u0004 אמר \u0003\"הביאו מלח\"\u0004 או \u0003\"הביאו לפתן\" נמי\u0004 \u0005[גם כן]\u0006 אין זו הפסקה ו\u0003אינו צריך לברך.\u0004 ורק אם אמר \u0003\"גביל לתורי, גביל לתורי\"\u0004 \u0005[בלול\u0006 את האוכל \u0005עבור השוורים, בלול\u0006 את האוכל \u0005עבור השוורים]\u0006 הרי זו נחשבת כהפסקה ו\u0003צריך לברך. ורב ששת אמר: אפילו\u0004 אם אמר \u0003\"גביל לתורי\"\u0004 \u0005[בלול לשוורים]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אינו צריך לברך,\u0004 שאף דבר זה נחשב כצורך הברכה. ש\u0003אמר רב יהודה אמר רב: אסור לאדם שיאכל קודם שיתן מאכל לבהמתו, שנאמר\u0004 תחילה בכתוב: \u0003\"ונתתי עשב בשדך לבהמתך\" והדר\u0004 \u0005[וחזר]\u0006 והמשיך הכתוב \u0003\"ואכלת ושבעת\"\u0004 (דברים יא, טו), שקודם דובר במאכל הבהמה ורק אחר כך במאכל האדם, ולכן המכין את אכלם של השוורים הרי זה כחלק מההכנה לאכילה.","ובענין זה \u0003אמר רבא בר שמואל\u0004 הלכה \u0003משום\u0004 (בשם) \u0003ר' חייא: אין הבוצע\u0004 את הפת \u0003רשאי לבצוע עד שיביאו מלח או לפתן לפני כל אחד ואחד\u0004 מן המסובים לאותו שולחן. ואולם מסופר כי \u0003רבא בר שמואל עצמו אקלע לבי ריש גלותא\u0004 \u0005[הזדמן לבית ראש הגולה],\u0006 \u0003אפיקו ליה ריפתא\u0004 \u0005[הוציאו,\u0006 נתנו \u0005לו פת],\u0006 \u0003ובצע להדיא\u0004 \u0005[מיד]\u0006 בלי להמתין שיביאו מלח או ליפתן. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 וכי \u0003הדר מר משמעתיה\u0004 \u0005[חזר אדוני מדבריו]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לית דין צריך בשש\u0004 \u0005[אין זה זקוק להמתנה],\u0006 שיש צורך במלח כדי לתת טעם בלחם מסוג גרוע, אך הפת הנקיה של בית ראש הגולה עריבה כשלעצמה, ואין צורך להטעימה במלח.","\u0003ו\u0004עוד \u0003אמר רבא בר שמואל משום\u0004 (בשם) \u0003ר' חייא: אין מי רגלים כלים\u0004 מן הגוף \u0003אלא בישיבה,\u0004 שהעומד חושש שיזלו מים על בגדיו ואינו מסיים צרכיו כראוי. \u0003אמר רב כהנא: ובעפר תיחוח,\u0004 שהעפר סופג את המים ואינו חושש שמא ינתזו, \u0003אפילו בעמידה\u0004 כלים המים. \u0003ואי ליכא\u0004 \u0005[ואם אין]\u0006 \u0003עפר תיחוח,\u0004 יש דרך אחרת להיזהר מלכלוך בגדיו, ש\u0003יעמוד במקום גבוה וישתין למקום מדרון.\u0004","\u0003ו\u0004עוד \u0003אמר רבא בר שמואל משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' חייא\u0004 בדרך עצה טובה: \u0003אחר כל אכילתך אכול מלח, ואחר כל שתייתך שתה מים ו\u0004אם תעשה כן \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה נזוק. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אחר כל אכילתך אכול מלח, ואחר כל שתייתך שתה מים ואי\u0004 \u0005[ואין]\u0006 \u0003אתה נזוק. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 בסגנון קצת שונה: \u0003אכל כל מאכל ולא אכל\u0004 אחריו \u0003מלח, שתה כל משקין ולא שתה\u0004 אחריהם \u0003מים,\u0004 אם היה זה \u0003ביום\u0004 — \u0003ידאג מן ריח\u0004 רע ב\u0003פה, ובלילה ידאג מפני\u0004 מחלת ה\u0003אסכרה.\u0004","ובנושא בריאות הגוף הביאו את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003המקפה אכילתו במים,\u0004 כלומר, ששותה מים רבים ו\"מציף\" בתוכם את אכילתו, \u0003אינו בא לידי חולי מעים.\u0004 ושואלים: \u0003וכמה\u0004 שיעור המים? \u0003אמר רב חסדא: קיתון לפת.\u0004","\u0003אמר רב מרי אמר ר' יוחנן: הרגיל ב\u0004אכילת \u0003עדשים אחת לשלשים יום מונע אסכרה מתוך ביתו.\u0004 ומעירים על כך: \u0003אבל\u0004 ב\u0003כל יומא\u0004 \u0005[יום]\u0006 — \u0003לא\u0004 יאכל עדשים. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003משום\u0004 שהדבר \u0003קשה\u0004 (יכול לגרום) \u0003לריח הפה.\u0004","\u0003ו\u0004כן \u0003אמר רב מרי אמר ר' יוחנן: הרגיל ב\u0004אכילת \u0003חרדל אחת לשלשים יום\u0004 — \u0003מונע חלאים מתוך ביתו.\u0004 ומעירים: \u0003אבל\u0004 ב\u0003כל יומא\u0004 \u0005[יום]\u0006 — \u0003לא\u0004 יאכל חרדל, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003משום\u0004 שהדבר \u0003קשה לחולשא דלבא\u0004 \u0005[לחולשת הלב].\u0006","ועוד עצה בענין בריאות, \u0003אמר ר' חייא בר אשי אמר רב: הרגיל בדגים קטנים\u0004 — \u0003אינו בא לידי חולי מעים. ולא עוד, אלא שדגים קטנים מפרין ומרבין ומברין\u0004 (מבריאים) את \u0003כל גופו של אדם\u0004 האוכלם.","ו\u0003אמר ר' חמא בר' חנינא: הרגיל ב\u0004אכילת \u0003קצח\u0004 — \u0003אינו בא לידי כאב לב,\u0004 שהקצח משמש מרפא ללב. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: והרי שנינו ש\u0003רבן שמעון בן גמליאל אומר:\u0004 ה\u0003קצח\u0004 — \u0003אחד מששים סמני\u0004 (סמי) \u0003המות הוא, ו\u0004לכן \u0003הישן למזרח גרנו,\u0004 כלומר, שעושה גורן, ערמה של קצח וישן למזרח הגורן כך שהרוח המערבית מביאה את ריח הקצח אליו — הרי זה \u0003דמו בראשו.\u0004 על כך משיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שהקצח מזיק הרי זה \u0003בריחו,\u0004 ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שהוא יפה ללב הרי זה \u0003בטעמו\u0004 בלבד. ומסופר: \u0003אימיה\u0004 \u0005[אמו]\u0006 של \u0003ר' ירמיה אפיא ליה ריפתא, ומדבקא ליה ומקלפא ליה\u0004 \u0005[היתה אופה לו לחם, ומדביקה בו\u0006 קצח להוסיף טעם, \u0005ומקלפת אותו]\u0006 כדי שלא יזיק ריחו.","שנינו במשנה ש\u0003ר' יהודה אומר\u0004 שעל ירקות מברכים \u0003\"בורא מיני דשאים\". אמר ר' זירא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חיננא בר פפא: אין הלכה כר' יהודה.\u0004 והוסיף \u0003ואמר ר' זירא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חיננא בר פפא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 — לפי ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ברוך ה' יום יום\"\u0004 (תהלים סה, כ), ויש לתמוה: \u0003וכי ביום מברכין אותו,\u0004 את ה', \u0003ובלילה אין מברכין אותו? אלא\u0004 בא הכתוב \u0003לומר לך: כל יום ויום תן לו מעין ברכותיו,\u0004 שכל יום יש ליחד ברכה לעצמו, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בברכות על המזון \u0003כל מין ומין תן לו מעין ברכותיו,\u0004 ברך עליו ברכה מיוחדת לו.","\u0003ו\u0004עוד \u0003אמר ר' זירא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חיננא בר פפא: בוא וראה שלא כמדת הקדוש ברוך הוא מדת בשר ודם.\u0004 שכן \u0003מדת בשר ודם\u0004 — \u0003כלי ריקן מחזיק\u0004 את שמניחים בתוכו, ואילו \u0003כלי\u0004 מלא \u0003אינו מחזיק, אבל\u0004 מידת \u0003הקדוש ברוך הוא אינו כן,\u0004 אלא להיפך, שאצלו אדם שהוא בבחינת כלי \u0003מלא\u0004 בדעת או במידות טובות \u0003מחזיק\u0004 אם מוסיפים בו, ולעומת זאת כלי \u0003ריקן אינו מחזיק.\u0004 ורמז לדבר ממה \u0003שנאמר: \"ויאמר אם שמוע תשמע\u0004 לקול ה' אלהיך והישר בעיניו תעשה\u0003\"\u0004 (שמות טו, כו), ודורשו: \u0003אם שמוע\u0004 — \u0003תשמע\u0004 גם בעתיד, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003לא תשמע. דבר אחר: אם שמוע,\u0004 כלומר, שמעת \u0003בישן,\u0004 במה שלמדת כבר — \u0003תשמע בחדש. ו\u0004אולם \u0003אם יפנה לבבך\u0004 — \u0003שוב לא תשמע.\u0004","משנה זו עיקרה בקביעה כי ברכות כלליות יותר מוציאות ידי חובה בדיעבד ברכות מפורטות יותר. שאם \u0003בירך על פירות האילן \"בורא פרי האדמה\"\u0004 — \u0003יצא\u0004 ידי חובה. אם בירך \u0003על פירות הארץ \"בורא פרי העץ\"\u0004 — \u0003לא יצא\u0004 ידי חובתו. \u0003ועל כולם,\u0004 על כל דבר מאכל \u0003אם אמר \"שהכל נהיה בדברו\"\u0004 — \u0003יצא\u0004 ידי חובה.","בתחילה מבררים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כי \u0003עיקר אילן ארעא היא\u0004 \u0005[הוא הארץ],\u0006 שמפני זה אפשר לברך על פירות האילן \"בורא פרי האדמה\"?! \u0003אמר רב נחמן בר יצחק:\u0004 זו שיטת \u0003ר' יהודה היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 במשנה העוסקת בדיני ביכורים: אם לאחר שקטף אדם את פירות הביכורים מאדמתו, \u0003יבש המעין\u0004 או \u0003נקצץ האילן\u0004 שהצמיח פירות אלו — \u0003מביא\u0004 ביכורים, \u0003ו\u0004אולם \u0003אינו קורא\u0004 את דברי השבח שנאמרים על הביכורים, משום שהאילן או המעין שהם היו עיקר הפראתה של האדמה, אינם מצויים עוד, ואינו יכול להודות \"על הארץ הטובה\". \u0003ר' יהודה אומר: מביא וקורא,\u0004 כי הארץ היא העיקר, והאילן אינו אלא חלק ממנה, וגם כאשר נקצץ האילן — הארץ שהיא עיקרו לא נשתנתה כלל. וכעין זה ההלכה גם בדיני ברכות שפירות העץ נחשבים כפרי האדמה.","שנינו במשנה אם ברך \u0003על פירות הארץ\u0004 \"בורא פרי העץ\" — לא יצא ידי חובתו. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא, שהרי אין פירות האדמה בכלל עצים! \u0003אמר רב נחמן בר יצחק: לא נצרכה\u0004 פיסקה זו במשנה \u0003אלא ל\u0004שיטת \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 במקום אחר ש\u0003חטה מין\u0004 ממיני ה\u0003אילן היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 ה\u0003אילן שאכל ממנו אדם הראשון, ר' מאיר אומר\u0004 ש\u0003גפן היה, שאין לך דבר שמביא יללה\u0004 וצרות \u0003על האדם\u0004 אף כעת \u0003אלא יין,\u0004 כפי \u0003שנאמר\u0004 בנח: \u0003\"וישת מן היין וישכר\",\u0004 \u0005(בראשית ט, כא)\u0006, ששתה והשתכר. ואילו \u0003ר' נחמיה אומר\u0004 ש\u0003תאנה היתה, שבדבר שנתקלקלו\u0004 וחטאו \u0003בו נתקנו, שנאמר: \"ויתפרו עלה תאנה\u0004 ויעשו להם חגורות\u0003\"\u0004 (בראשית ג, ז), ובוודאי לקחו מן האילן הקרוב ביותר הוא עץ הדעת. ואילו \u0003ר' יהודה אומר\u0004 שעץ זה \u0003חטה היתה,\u0004 שגם עכשו מוסיפה החיטה דעת, \u0003שאין התינוק יודע לקרות \"אבא\" ו\"אמא\" עד שיטעום טעם דגן,\u0004 והרי שיש בחיטה מן המוסיף דעת.","ומדברים אלה \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003הואיל ואמר ר' יהודה\u0004 ש\u0003חטה מין אילן היא,\u0004 אם כן \u0003ליברך\u0004 \u0005[יברך]\u0006 \u0003עליה \"בורא פרי העץ\",\u0004 על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שלענין ברכה הכלל שונה ו\u0003היכא מברכינן\u0004 \u0005[היכן מברכים אנו]\u0006 \u0003\"בורא פרי העץ\"\u0004 — \u0003היכא דכי שקלת ליה לפירי איתיה לגווזא, והדר מפיק\u0004 \u0005[במקום שכאשר נוטל אתה את הפרי נשאר הענף, וחוזר ומוציא\u0006 פירות\u0005],\u0006"],["\u0003אבל היכא דכי שקלת ליה לפירי ליתיה לגווזא דהדר מפיק\u0004 \u0005[היכן שכאשר אתה נוטל את הפרי אין הענף חוזר ומוציא\u0006 פירות\u0005],\u0006 בכגון זה \u0003לא מברכינן עליה\u0004 \u0005[מברכים אנו עליו]\u0006 \u0003\"בורא פרי העץ\" אלא \"בורא פרי האדמה\".\u0004","\u0003ו\u0004עוד שנינו במשנה ש\u0003על כולן אם אמר \"שהכל\u0004 נהיה בדברו \u0003\"\u0004— יצא. בפירושה המדוייק של המשנה \u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים. \u0003רב הונא אמר\u0004 שדין זה הוא \u0003חוץ מן הפת ומן היין,\u0004 שמכיון שיש להם ברכה מיוחדת אין יוצאים ידי חובה אם מברכים עליהם את הברכה הכללית \"שהכל\". \u0003ור' יוחנן אמר\u0004 ש\u0003אפילו\u0004 ב\u0003פת ויין\u0004 יוצא ידי חובתו בברכת \"שהכל\".","ומעירים: \u0003נימא כתנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שמחלוקת זו היא \u0005כ\u0006מחלוקת \u0005תנאים]\u0006 אחרת בנושא זה. ששנינו בתוספתא: מי ש\u0003ראה פת ואמר: \"כמה נאה פת זו, ברוך המקום שבראה\"\u0004 — \u0003יצא\u0004 ידי חובת ברכה. \u0003ראה תאנה ואמר \"כמה נאה תאנה זו ברוך המקום שבראה\"\u0004 — \u0003יצא\u0004 ידי חובתו, אלו \u0003דברי ר' מאיר. ר' יוסי אומר: כל המשנה ממטבע שטבעו חכמים בברכות\u0004 — \u0003לא יצא ידי חובתו.\u0004 ואם כן \u0003נימא\u0004 \u0005[נאמר]\u0006 ש\u0003רב הונא\u0004 ש\u0003אמר\u0004 שהמברך על הפת או על היין \"שהכל\" לא יצא, הוא הולך בשיטת \u0003ר' יוסי, ור' יוחנן\u0004 ש\u0003אמר\u0004 שאפשר לברך אף על הפת והיין \"שהכל\", הוא הולך בשיטת \u0003ר' מאיר?!\u0004","ודוחים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב הונא: אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 דברי \u0003אפילו ל\u0004שיטת \u0003ר' מאיר\u0004 אמרתי כן, שכן \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' מאיר\u0004 כך, \u0003התם\u0004 \u0005[שם]\u0006 להתיר את שינוי נוסח הברכה הקבוע, \u0003אלא היכא דקא מדכר\u0004 \u0005[היכן שהוא,\u0006 המברך, \u0005מזכיר]\u0006 את \u0003שמיה\u0004 של ה\u0003פת\u0004 במפורש בברכתו, \u0003אבל היכא דלא קא מדכר\u0004 \u0005[שאינו מזכיר]\u0006 את \u0003שמיה\u0004 של ה\u0003פת אפילו ר' מאיר מודה,\u0004 שאינו יוצא ידי חובתו,","\u0003ור' יוחנן אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: אנא דאמרי\u0004 \u0005[אני שאמרתי],\u0006 דברי מכוונים, \u0003אפילו ל\u0004שיטת \u0003ר' יוסי,\u0004 שכן \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יוסי התם\u0004 \u0005[שם]\u0006 שאינו יוצא ידי חובתו כאשר משנה מנוסח הברכה הקבוע \u0003אלא משום דקאמר\u0004 \u0005[שהוא אומר]\u0006 \u0003ברכה\u0004 ש\u0003לא תקינו רבנן\u0004 \u0005[תקנו חכמים],\u0006 \u0003אבל\u0004 אם \u0003אמר\u0004 ברכת \u0003\"שהכל נהיה בדברו\" דתקינו רבנן\u0004 \u0005[שתקנו חכמים],\u0006 בכגון זה \u0003אפילו ר' יוסי מודה\u0004 שיוצא בדיעבד ידי חובת ברכה.","בענין ברכות שלא כמטבע שטבעו חכמים, מסופר כי \u0003בנימין רעיא\u0004 \u0005[הרועה]\u0006 \u0003כרך ריפתא, ואמר\u0004 \u0005[היה אוכל לחם, ואומר]\u0006 אחר כך: \u0003\"בריך מריה דהאי פיתא\"\u0004 \u0005[\"ברוך אדונו של לחם זה\"].\u0006 ועל כך \u0003אמר רב\u0004 ש\u0003יצא\u0004 בכך ידי חובת ברכה. ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב\u0004 עצמו ש\u0003כל ברכה שאין בה הזכרת השם אינה\u0004 נחשבת כ\u0003ברכה!\u0004 ומתקנים ש\u0003אמר\u0004 בלשון זו: \u0003\"בריך רחמנא מריה דהאי פיתא\"\u0004 \u0005[\"ברוך ה' אדונו של הלחם הזה\"].\u0006","ושוב שואלים: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 שיברך האוכל \u0003שלש ברכות\u0004 בברכת המזון, וכיצד יצא ידי חובה במשפט אחד זה? ומסבירים \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"יצא\" דקאמר\u0004 \u0005[שאמר]\u0006 \u0003רב\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 ש\u0003יצא ידי\u0004 חובת \u0003ברכה ראשונה\u0004 משלוש ברכות המזון, אבל צריך לברך עוד שתי ברכוה אחרות.","על כך שואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך? ומשיבים: \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אמרה\u0004 לברכה זו \u0003בלשון חול\u0004 ולא בלשון הקודש (עברית), יצא ידי חובתו.","ואולם גם דבר זה קשה שכן כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה במשנה במסכת סוטה: \u0003ואלו\u0004 הדברים ה\u0003נאמרים בכל לשון\u0004 שהאדם האומרם יוכל להבינם: \u0003פרשת\u0004 השבעתה של ה\u0003סוטה,\u0004 ה\u0003וידוי\u0004 על ה\u0003מעשר\u0004 כאשר אומר בעל הבית שנתן את כל התרומות והמעשרות כראוי, \u0003קריאת שמע, ותפלה, וברכת המזון.\u0004 ומאחר שמפורש שברכת המזון יכולה להיאמר בכל שפה, מה חידש איפוא רב? ומשיבים: \u0003אצטריך\u0004 \u0005[צריך]\u0006 שיאמר רב את פסקו לגבי בנימין הרועה, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלו],\u0006 ההיתר לברך בכל שפה, הוא דווקא כאשר המברך \u0003אמרה\u0004 לברכה זו \u0003בלשון חול, כי היכי דתקינו רבנן\u0004 \u0005[כמו,\u0006 באותו נוסח \u0005שתקנו חכמים]\u0006 \u0003בלשון קדש, אבל\u0004 כאשר \u0003לא אמרה\u0004 לברכה זו \u0003בלשון חול כי היכי דתקינו רבנן\u0004 \u0005[כמו שתקנו חכמים]\u0006 \u0003בלשון קדש, אימא\u0004 \u0005[הייתי אומר]\u0006 ש\u0003לא\u0004 יצא ידי חובתו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב שבדיעבד לא רק השפה אינה מעכבת, אלא אף לא הנוסח.","עתה דנים \u0003גופא\u0004 \u0005[לגופם]\u0006 של הדברים שאמר רב שבכל ברכה צריכה להיות הזכרת שם ה', ולצורך זה מביאים את המחלוקת היסודית בענין זה. \u0003אמר רב: כל ברכה שאין בה הזכרת השם\u0004 — \u0003אינה\u0004 נחשבת ל\u0003ברכה. ור' יוחנן אמר: כל ברכה שאין\u0004 מוזכרת \u0003בה מלכות\u0004 ה' \u0003אינה ברכה. אמר אביי: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב מסתברא\u0004 \u0005[מסתבר]\u0006 לומר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 כאשר אומר אדם בוידוי המעשר \u0003\"לא עברתי ממצותיך ולא שכחתי\"\u0004 (דברים כו, יג) כוונת הדברים: \u0003\"לא עברתי\"\u0004 משמעו — לא נמנעתי \u0003מלברכך, \"ולא שכחתי\"\u0004 — \u0003מלהזכיר שמך\u0004 ה' \u0003עליו. ואילו מלכות לא קתני\u0004 \u0005[שנה],\u0006 שלא הזכירה הברייתא שיש גם להזכיר את מלכות ה'.","\u0003ור' יוחנן תני\u0004 \u0005[היה שונה]\u0006 את התוספתא בלשון אחרת: \u0003\"ולא שכחתי\"\u0004 — \u0003מלהזכיר שמך ומלכותך עליו,\u0004 ומלשון זו משמע שיש להזכיר בנוסח זה גם את מלכות ה'.","\u0003ועל\u0004 כל \u0003דבר שאין גדולו מן הארץ אומר\u0004 האוכלו \u0003\"שהכל נהיה בדברו\".\u0004 ו\u0003על החומץ\u0004 (יין שהחמיץ והתקלקל) \u0003ועל הנובלות\u0004 (תמרים שהתקלקלו), \u0003ועל הגובאי\u0004 (חגבים, ארבה) \u0003אומר \"שהכל נהיה בדברו\". ר' יהודה\u0004 חולק ו\u0003אומר: כל שהוא מין קללה אין מברכין עליו\u0004 כלל אם אוכלו, וכל אלה אינם באים כשהשנים והזמנים כתיקנם, והריהם בכלל מין קללה.","בעיה אחרת היא מה לברך אם \u0003היו לפניו מינין הרבה\u0004 לאכול, איזה מהם יש להקדים בברכה, \u0003ר' יהודה אומר: אם יש ביניהן מין שבעה,\u0004 שהוא משבעת המינים שנשתבחה בהם ארץ ישראל — \u0003עליו הוא\u0004 מקדים ו\u0003מברך. וחכמים אומרים: מברך על איזה מהן שירצה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003על דבר שאין גדולו מן הארץ, כגון בשר בהמות חיות ועופות ודגים אומר \"שהכל נהיה בדברו\",\u0004 וכן \u0003על החלב ועל הביצים ועל הגבינה אומר \"שהכל\".\u0004 וכן לא רק על דברים שמקורם בבעלי חיים, אלא אף \u0003על הפת שעפשה\u0004 (התעפשה), \u0003ועל היין שהקרים\u0004 (החמיץ קצת), \u0003ועל התבשיל שעבר צורתו\u0004 (התקלקל טעמו) \u0003אומר \"שהכל\".\u0004 שמאחר שנתקלקלו במקצת, אין לברך עוד עליהם את ברכתם המיוחדת. וכן \u0003על המלח ועל הזמית ועל כמהין ופטריות אומר \"שהכל\".\u0004 על כך שואלים: \u0003למימרא\u0004 \u0005[האם נאמר]\u0006 שה\u0003כמהין ופטריות לאו\u0004 \u0005[לא]\u0006 \u0003גדולי קרקע נינהו\u0004 \u0005[הם]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003הנודר\u0004 שלא לאכול \u0003מפירות הארץ\u0004 — \u0003אסור\u0004 לו לאכול את כל ה\u0003פירות הארץ, ו\u0004אולם הוא \u0003מותר בכמהין ופטריות.\u0004 אך \u0003אם אמר \"כל גדולי קרקע\u0004 אסורים \u0003עלי\"\u0004 — \u0003אסור אף בכמהין ופטריות.\u0004 הרי שהפטריות נחשבים כגידולי קרקע!","\u0003אמר אביי: מירבא רבו מארעא, מינקי לא ינקי מארעא\u0004 \u0005[לגדול,\u0006 הם \u0005גדלים מן הארץ,\u0006 ואולם \u0005לינוק\u0006 הם לא\u0005 יונקים מן הארץ]\u0006","על כך מקשים: וכי משום מה יהיה הבדל זה חשוב, \u0003והא\u0004 \u0005[והרי]\u0006 רק \u0003\"על דבר שאין גדולו מן הארץ\" קתני\u0004 \u0005[שנינו]\u0006 במפורש שברכתו \"שהכל\", ואף לדעת אביי פטריות גידולן מן הארץ! ומתרצים: \u0003תני\u0004 \u0005[שנה]\u0006 וגרוס בלשון זו: על דבר \u0003שאינו יונק מן הארץ\u0004 אומר \"שהכל\", ולכן מברכים אף על הפטריות \"שהכל\".","שנינו במשנה ש\u0003על הנובלות\u0004 מברכים \"שהכל\". ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הן\u0005]\u0006 \u0003נובלות?\u0004 ומשיבים שנחלקו בכך האמוראים \u0003ר' זירא ור' אילעא. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהכוונה היא \u0003בושלי כמרא\u0004 \u0005[שרופי החמה],\u0006 תמרים שנתבשלו לפני זמנם בשל השרב. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהם \u0003תמרי דזיקא\u0004 \u0005[תמרים של רוח],\u0006 שנפלו ברוח מן העץ.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 בהמשך הדברים ש\u0003ר' יהודה\u0004 חולק ו\u0003אומר\u0004 ש\u0003כל\u0004 דבר \u0003שהוא מין קללה אין מברכין עליו\u0004 אם אוכלו. ומעתה \u0003בשלמא למאן דאמר בושלי כמרא\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר\u0006 שהם \u0005שרופי חמה],\u0006 \u0003היינו דקרי ליה\u0004 \u0005[זהו\u0006 הטעם \u0005ש\u0006הוא \u0005קורא להם]\u0006 \u0003\"מין קללה\", אלא למאן דאמר תמרי דזיקא\u0004 \u0005[ל\u0006דעת \u0005מי שאומר\u0006 כי הם \u0005תמרים שהרוח משירה]\u0006 \u0003מאי\u0004 \u0005[מהו]\u0006 הטעם שדבר זה נקרא \u0003מין קללה?\u0004 שהרי תמרים אלה שנפלו מן העץ בעצמם, אינם גרועים מתמרים אחרים!","ומתרצים: דברי ר' יהודה היו \u0003אשארא\u0004 \u0005[על השאר],\u0006 על החומץ והגובאי, אך לא על הנובלות.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 קושיא מעין זו באופן אחר: \u0003בשלמא למאן דאמר בושלי כמרא\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר\u0006 שהם \u0005שרופי חמה],\u0006 \u0003היינו דמברכינן עלייהו\u0004 \u0005[זהו\u0006 הטעם \u0005שמברכים אנו עליהם]\u0006 \u0003\"שהכל\",\u0004 לפי שטיבם פחות. \u0003אלא למאן דאמר תמרי דזיקא\u0004 \u0005[ל\u0006דעת \u0005מי שאומר\u0006 כי הם \u0005תמרים שהרוח משירה]\u0006 האם \u0003\"שהכל\"\u0004 צריכים לברך עליהם? הלא \u0003\"בורא פרי העץ\" מבעי ליה לברוכי\u0004 \u0005[יש לו\u0006 לאוכל \u0005לברך]\u0006 עליהם!","\u0003אלא\u0004 יש להסיק כי \u0003ב\u0004פירוש \u0003נובלות סתמא\u0004 \u0005[סתם]\u0006 \u0003כולי עלמא לא פליגי דבושלי כמרא נינהו\u0004 \u0005[הכל אינם חלוקים ששרופי חמה הם],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חולקים]\u0006 הרי זה \u0003ב\u0004פירוש \u0003נובלות תמרה. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בדיני דמאי: אף על פי שסתם פירות הבאים לידו של אדם מידי עם הארץ (דמאי) צריך לעשר אותם מחשש שמא לא עישר אותם עם הארץ, מכל מקום פירות מסויימים שהם פחותים בטיבם הריהם \u0003הקלין שבדמאי\u0004 ואין צורך לעשרם. ואלו הם: \u0003השיתין, והרימין, והעוזרדין, בנות שוח, ובנות שקמה, וגופנין, ונצפה, ונובלות תמרה.\u0004 בראשונה מפרשים מה הם האילנות שהוזכרו כאן.","ה\u0003שיתין אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן\u0004 שהם \u0003מין\u0004 ממיני ה\u0003תאנים. רימין\u0004 — הם הפירות הנקראים \u0003כנדי. העוזרדין\u0004 — הם הפירות הנקראים \u0003טולשי. בנות שוח, אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן\u0004 שהם \u0003תאיני חיורתא\u0004 \u0005[תאנים לבנות].\u0006 \u0003בנות שקמה. אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן\u0004 שהם \u0003דובלי,\u0004 פירות עץ השקמה. \u0003גופנין\u0004 — הם \u0003שילהי גופני\u0004 \u0005[סוף ענבי הגפן],\u0006 הענבים האחרונים הנשארים בדרך כלל בוסר. \u0003נצפה\u0004 — הוא \u0003פרחה,\u0004 פרי הצלף. ובפירוש \u0003נובלות תמרה\u0004 נחלקו \u0003ר' אילעא ור' זירא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהכוונה היא \u0003בושלי כמרא\u0004 \u0005[שרופי החמה],\u0006 \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהם \u0003תמרי דזיקא\u0004 \u0005[תמרים של רוח].\u0006","אף כאן מקשים: \u0003בשלמא למאן דאמר בושלי כמרא\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר\u0006 שהם \u0005שרופי החמה]\u0006 \u0003היינו דקתני\u0004 \u0005[זהו\u0006 הטעם \u0005ששנינו]\u0006 שהם \u0003הקלין שבדמאי,\u0004 כלומר, שרק \u0003ספיקן\u0004 (אם לא היה ברור לו שנתעשרו) \u0003הוא\u0004 ש\u0003פטור\u0004 מלעשר שנית, \u0003הא\u0004 \u0005[הרי]\u0006 את \u0003ודאן,\u0004 כשיודע הוא בוודאי שלא נתעשרו — \u0003חייב\u0004 להפריש מהם מעשר. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003תמרי דזיקא\u0004 \u0005[תמרים שהשירה אותם הרוח]\u0006 קשה: האם \u0003ודאן\u0004 צריך להיות \u0003חייב,\u0004 והרי \u0003הפקרא נינהו\u0004 \u0005[הפקר הם]\u0006 ואין מפרישים מעשר מדבר שהופקר!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — במקרה המיוחד כשאסף אדם את התמרים הללו שהשירה הרוח ו\u0003עשאן\u0004 ערמה אחת כעין \u0003גורן.\u0004 ש\u0003אמר ר' יצחק\u0004 שכך \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' אליעזר בן יעקב:\u0004 אף מתנות העניים כגון \u0003הלקט והשכחה והפאה\u0004 שהם פטורים מן המעשר, אם \u0003עשאן\u0004 העני \u0003גורן\u0004 — \u0003הוקבעו\u0004 מדברי חכמים שתחול עליהם חובת \u0003מעשר.\u0004 ובמקרה כזה רק הדמאי פטור מלעשרו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שהדיון היה בנושא זה:"],["\u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 שנובלות תמרה הם \u0003תמרי דזיקא\u0004 \u0005[תמרים של\u0006 השרת הרוח], \u0003היינו דהכא\u0004 \u0005[זהו\u0006 הטעם \u0005שכאן]\u0006 במשנה שלנו כשהמדובר בתמרים מקולקלים \u0003קרי לה\u0004 \u0005[\u0006הוא \u0005קורא להם]\u0006 \u0003\"נובלות\" סתמא\u0004 \u0005[סתם],\u0006 \u0003והתם\u0004 \u0005[ושם]\u0006 שהמדובר באלה שנשרו ברוח \u0003קרי לה\u0004 \u0005[קורא להם]\u0006 \u0003\"\u0004נובלות תמרה\", \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שגם נובלות תמרה הם \u0003בושלי כמרא\u0004 \u0005[\u0006תמרים \u0005שרופי שרב],\u0006 \u0003ניתני אידי ואידי\u0004 \u0005[ישנה\u0006 אם כן \u0005בזה ובזה]\u0006 \u0003\"נובלות תמרה\", או אידי ואידי\u0004 \u0005[בזה ובזה]\u0006 \u0003\"נובלות\" סתמא\u0004 \u0005[סתם],\u0006 ומאחר ונשתנה הלשון נראה שהם דברים נבדלים. לשאלה זו לא נמצאה תשובה, ומעירים כי אכן לדעה זו \u0003קשיא\u0004 \u0005[קשה].\u0006","במשנה הובאה מחלוקת כיצד מברכים כש\u0003היו לפניו מינין הרבה\u0004 העומדים לאכילה, שלדעת ר' יהודה אם יש ביניהם אחד משבעת המינים שנשתבחה בהם ארץ ישראל — מברך עליו. ולדעת חכמים מברך על איזה מהם שירצה. \u0003אמר עולא: מחלוקת\u0004 זו דווקא \u0003בשברכותיהן\u0004 של כל מיני המאכל הנמצאים לפניו \u0003שוות,\u0004 שבכגון זה \u0003ר' יהודה סבר\u0004 \u0005[סבור]\u0006 שעל פרי שהוא מ\u0003מין שבעה עדיף\u0004 ולכך ראוי להקדימו בברכה, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 כי על \u0003מין\u0004 ה\u0003חביב\u0004 עליו \u0003עדיף\u0004 להקדים ולברך. \u0003אבל \u0004כאשר \u0003אין ברכותיהן שוות\u0004 — \u0003דברי הכל מברך על זה,\u0004 על אחד מהם, \u0003וחוזר\u0004 אחר כך \u0003ומברך על זה,\u0004 שמברך על כל מין לחוד בברכתו.","על כך \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: מי ש\u0003היו לפניו צנון וזית\u0004 — \u0003מברך על הצנון ופוטר\u0004 בברכה זו אף \u0003את הזית,\u0004 ואף שאין ברכותיהם שוות! ומתרצים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כשהצנון עקר\u0004 עבור אותו אדם בסעודה זו, והזית בא רק כדי להפיג את טעם הצנון, ולכן מברך על הצנון.","ומוסיפים לשאול: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כן, אמור\u0006 את \u0005סוף\u0006 הברייתא\u0005]\u0006 ששנינו שם ש\u0003ר' יהודה אומר: מברך על הזית,\u0004 מפני \u0003שהזית ממין שבעה.\u0004 וכי \u0003לית ליה\u0004 \u0005[אין לו\u0006 \u0003לר' יהודה\u0004, אינו מסכים\u0005]\u0006 \u0003הא דתנן\u0004 \u0005[\u0006כלל \u0005זה ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כל שהוא עיקר\u0004 המזון באותה סעודה \u0003ועמו\u0004 באה \u0003טפלה,\u0004 מין מאכל הנחשב כטפל באותה סעודה — \u0003מברך על העיקר ופוטר\u0004 בברכה זו אף \u0003את הטפלה. וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי דלית ליה\u0004 \u0005[כך\u0006 הוא \u0005גם כן שאין לו,\u0006 אינו סבור\u0005]\u0006 שהעיקר פוטר את הטפלה, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 ברייתא\u0005]\u0006 מפורשת: \u0003ר' יהודה אומר: אם מחמת\u0004 (בגלל) \u0003הצנון בא הזית\u0004 — \u0003מברך על הצנון ופוטר את הזית.\u0004 ואם כן ודאי שהמחלוקת אם לברך על הצנון או על הזית הריהי כשהצנון איננו עיקר, והיא לכאורה סתירה לדברי עולא.","ומשיבים: \u0003לעולם ב\u0004שה\u0003צנון עיקר\u0004 באותה סעודה \u0003עסקינן\u0004 \u0005[אנו עוסקים],\u0006 \u0003וכי פליגי\u0004 \u0005[וכאשר נחלקו]\u0006 \u0003ר' יהודה ורבנן\u0004 \u0005[וחכמים]\u0006 — \u0003במילתא אחריתי פליגי\u0004 \u0005[בדבר אחר\u0006 הם \u0005חולקים],\u0006 \u0003וחסורי מחסרא, והכי קתני\u0004 \u0005[וחסור חסרה\u0006 ברייתא זו, \u0005וכך\u0006 צריכה היא להיות \u0005שנויה]:\u0006 \u0003היו לפניו צנון וזית\u0004 — \u0003מברך על הצנון ופוטר את הזית. במה דברים אמורים\u0004 — דווקא \u0003כשהצנון עיקר, אבל\u0004 כאשר \u0003אין הצנון עיקר\u0004 — \u0003דברי הכל מברך על זה וחוזר ומברך על זה.\u0004 אבל אם אינו עיקר — מברך על כל אחד לחוד. \u0003ושני מינין בעלמא\u0004 \u0005[סתם]\u0006 \u0003שברכותיהן שוות\u0004 — \u0003מברך על איזה מהן שירצה. ר' יהודה אומר: מברך על הזית,\u0004 מפני \u0003שהזית ממין שבעה.\u0004","בענין זה עצמו \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה ר' אמי ור' יצחק נפחא. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שה\u0003מחלוקת\u0004 היא \u0003בשברכותיהן שוות,\u0004 ש\u0003ר' יהודה סבר\u0004 \u0005[סבור]\u0006 ש\u0003מין שבעה עדיף\u0004 ולכך ראוי להקדימו בברכה. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 כי \u0003מין חביב עדיף\u0004 ולפיכך אותו ראוי להקדים בברכה. \u0003אבל בשאין ברכותיהן שוות\u0004 — \u0003דברי הכל מברך על זה וחוזר ומברך על זה. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 ש\u0003אף בשאין ברכותיהן שוות נמי\u0004 \u0005[גם כן]\u0006 היא \u0003מחלוקת.\u0004","על כך דנים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003בשברכותיהן שוות מחלוקת\u0004 — \u0003שפיר\u0004 \u0005[יפה],\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003בשאין ברכותיהן שוות מחלוקת,\u0004 אם כן \u0003במאי פליגי\u0004 \u0005[במה\u0006 הם \u0005חולקים],\u0006 והרי בכל אופן יש לברך שתי ברכות! \u0003אמר ר' ירמיה:\u0004 מחלוקת זו היא לענין איזו מהן \u0003להקדים.\u0004","וכעין מה ש\u0003אמר רב יוסף ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יצחק: כל המוקדם בפסוק זה\u0004 המדבר בשבח ארץ ישראל וייאמר להלן, \u0003מוקדם לברכה, שנאמר: \"ארץ חטה ושערה וגפן ותאנה ורמון ארץ זית שמן ודבש\"\u0004 (דברים ח, ח), שכיון שהקדימו הכתוב ודאי הדבר מוכיח על חשיבותו היתירה, ולכך יש להקדימו בברכה.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה],\u0006 שמועה זו על שיטת \u0003ר' חנן.\u0004 ש\u0003אמר ר' חנן: כל הפסוק כולו ל\u0004ענין שיעורין להלכות רבות בתורה \u0003נאמר.\u0004","\u0003\"חטה\"\u0004 נאמרה כשיעור לענין שיעור הזמן בו חלה טומאת בית על אדם. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנכנס לבית המנוגע\u0004 בצרעת הבית (עיין ויקרא יד, לג–נג) \u0003וכליו\u0004 (בגדיו) מונחים \u0003על כתפיו, וסנדליו וטבעותיו בידיו\u0004 — \u0003הוא והן,\u0004 החפצים והבגדים \u0003טמאין מיד.\u0004 אך כאשר \u0003היה לבוש כליו, וסנדליו ברגליו, וטבעותיו באצבעותיו\u0004 — \u0003הוא טמא מיד\u0004 עם כניסתו לבית, \u0003ו\u0004אולם \u0003הן,\u0004 הכלים \u0003טהורין עד שישהה\u0004 בבית \u0003בכדי\u0004 שיעור זמן \u0003אכילת פרס\u0004 (חצי ככר), ודווקא חצי ככר העשויה מ\u0003פת חטין ולא פת שעורין.\u0004 ולגבי מהירות האכילה, הרי החשבון הוא באדם ה\u0003מיסב ואוכלן\u0004 לאותו לחם \u0003בלפתן.\u0004 הרי שיעור הנקבע על פי מאכל חיטה.","\u0003\"שערה\"\u0004 נאמרה אף היא לענין שיעור, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003עצם\u0004 שגודלה \u0003כשעורה\u0004 מן המת \u0003מטמא במגע\u0004 (של הנוגע בה) או \u0003במשא\u0004 (של הנושא אותה) כנוגע במת עצמו, \u0003ו\u0004אולם \u0003אינו מטמא באהל.\u0004 שבית שהיא מצויה בו, אינו נטמא בגללה.","שיעור הלכתי הנקבע על פי הנאמר בכתוב \u0003\"גפן\"\u0004 הוא \u0003כדי\u0004 שיעור \u0003רביעית יין,\u0004 שזהו השיעור שעליו מתחייב ה\u0003נזיר\u0004 כאשר הוא שותה יין. אבל לא יין בכמות של רביעית מים, השונה קצת בשיעורה. \u0003\"תאנה\"\u0004 בא להשמיענו בסיס השיעור של \u0003כגרוגרת\u0004 (תאנה מיובשת) אשר היא כרגיל היחידה הקטנה ביותר של דברי אוכל \u0003ל\u0004ענין \u0003הוצאת שבת,\u0004 שאסור להוציא מרשות לרשות ביום השבת. \u0003\"רמון\"\u0004 אף הוא בא להשמיענו שיעור, \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כל כלי בעלי בתים\u0004 (של אנשים סתם), אם ניקבו, הריהם יוצאים מכלל שימוש ככלים, ולכן אין טומאה חלה עליהם עוד,"],["ו\u0003שיעורן,\u0004 כלומר, שיעור נקיבתם של כלים אלה הריהו \u0003כרמונים,\u0004 שכל עוד שיעור הנקב קטן מזה עדיין משתמשים בהם, ונחשבים הם ככלים.","ועל הכתוב \u0003\"ארץ זית שמן\" אמר ר' יוסי בר' חנינא,\u0004 יש לדרוש פסוק זה כך: \u0003ארץ שכל שיעוריה כזיתים.\u0004 על כך תוהים: \u0003כל שיעוריה סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר?! \u0003והא איכא הנך דאמרן\u0004 \u0005[והרי יש אותם שאמרנו]\u0006 שאין שיעורם כזית! אלא יש לתקן: \u0003ארץ שרוב שיעוריה כזיתים,\u0004 שהשיעור כזית הוא שיעור מפתח בהלכות רבות.","וה\u0003\"דבש\"\u0004 שבכתוב שהוא דבש תמרים, אף הוא מרמז לשיעור, ששיעור \u0003ככותבת\u0004 (תמר) \u0003הגסה\u0004 (גדולה), הוא שיעור איסור אכילה \u0003ביום הכפורים\u0004 מדברי תורה. ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 שדרש את הפסוק שלמד מן הפסוק דיני קדימה בברכות, מה יאמר על מדרש זה? ומשיבים: \u0003הני\u0004 \u0005[אלו]\u0006 ה\u0003שיעורין בהדיא מי כתיבי\u0004 \u0005[האם\u0006 הם \u0005כתובים במפורש]?\u0006 \u0003אלא\u0004 שיעורים אלו נקבעו \u0003מדרבנן, וקרא אסמכתא בעלמא\u0004 \u0005[מדברי סופרים, והפסוק\u0006 הוא \u0005סמך,\u0006 רמז \u0005בלבד].\u0006","ובדיני קדימה בברכות מסופר: \u0003רב חסדא ורב המנונא הוו יתבי בסעודתא\u0004 \u0005[היו יושבים בסעודה].\u0006 \u0003אייתו לקמייהו תמרי ורמוני\u0004 \u0005[הביאו לפניהם תמרים ורימונים],\u0006 \u0003שקל\u0004 \u0005[נטל]\u0006 \u0003רב המנונא, בריך אתמרי ברישא\u0004 \u0005[\u0006ו\u0005ברך על התמרים בראש].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא:\u0004 וכי \u0003לא סבירא ליה מר להא\u0004 \u0005[סבור הוא אדוני ל\u0006הלכה \u0005זו]\u0006 ש\u0003אמר רב יוסף, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יצחק\u0004 ש\u0003כל המוקדם בפסוק זה קודם לברכה?\u0004 והרי הרימון מוזכר קודם לתמר!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב המנונא: \u0003זה\u0004 (התמר) \u0003שני ל\u0004מלה \u0003\"ארץ\"\u0004 (שהוא מופיע בפסוק \"ארץ זית שמן ודבש\") מיד אחרי הזית, \u0003וזה,\u0004 הרימון, הוא רק \u0003חמישי\u0004 אחר הזכרת \u0003\"ארץ\". אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לרב המנונא בהתפעלות: \u0003מאן יהיב לן נגרי דפרזלא ונשמעינך\u0004 \u0005[מי יתן לנו רגלי ברזל ונשמש אותך],\u0006 ונוכל לשמוע מפיך דברים חדשים בכל עת.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 אם \u0003הביאו לפניהם,\u0004 לפני היושבים בסעודה, \u0003תאנים וענבים בתוך הסעודה\u0004 מה דינם לענין ברכה? \u0003אמר רב הונא: טעונים\u0004 הם \u0003ברכה לפניהם ו\u0004אולם \u0003אין טעונים ברכה לאחריהם,\u0004 מפני שברכת המזון פוטרת אף אותם. \u0003וכן אמר\u0004 גם \u0003רב נחמן\u0004 ש\u0003טעונים ברכה לפניהם ואין טעונים ברכה לאחריהם. ו\u0004אילו \u0003רב ששת אמר:\u0004 אותם פירות \u0003טעונין ברכה בין לפניהם בין לאחריהם\u0004 אף בתוך הסעודה. \u0003ש\u0004לדעתו \u0003אין לך דבר שטעון ברכה לפניו ואין\u0004 הוא \u0003טעון ברכה לאחריו,\u0004 שברכת המזון שעל הלחם פוטרת דברים שבתוך הסעודה \u0003אלא פת הבאה בכסנין\u0004 (מאפה ממותק ומתובל) \u0003בלבד,\u0004 שאף הוא בכלל לחם. \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 גם דעת רב הונא וגם דעת רב ששת מדברי \u0003ר' חייא.\u0004 ש\u0003אמר ר' חייא:\u0004 ה\u0003פת פוטרת כל מיני מאכל\u0004 שהוא אוכל אחריה, \u0003ויין פוטר כל מיני משקים\u0004 שהוא שותה אחריו, ואין צריך לברך עליהם לא לפניהם ולא לאחריהם.","כדי לסכם את הדברים \u0003אמר רב פפא: הלכתא\u0004 \u0005[הלכה]\u0006 היא ש\u0003דברים הבאים מחמת הסעודה, בתוך הסעודה,\u0004 כלומר, שהם חלק מן הארוחה עצמה וצמודים ללחם הנאכל בארוחה זו — \u0003אין טעונים ברכה לא לפניהם ולא לאחריהם,\u0004 לפי שהם נחשבים טפלים ללחם. \u0003ו\u0004דברים הבאים \u0003שלא מחמת הסעודה,\u0004 אם הובאו לו \u0003בתוך הסעודה,\u0004 כגון מיני פירות — הריהם \u0003טעונים ברכה לפניהם ואין טעונים ברכה לאחריהם.\u0004 הביאם \u0003לאחר הסעודה\u0004 — \u0003טעונים ברכה, בין לפניהם בין לאחריהם.\u0004","ומסופר כי \u0003שאלו את בן זומא: מפני מה אמרו\u0004 חכמים כי \u0003דברים הבאים מחמת הסעודה בתוך הסעודה אינם טעונים ברכה לא לפניהם ולא לאחריהם? אמר להם: הואיל ופת\u0004 הלחם \u0003פוטרתן.\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 ה\u0003יין נמי נפטריה\u0004 \u0005[גם כן תפטור אותו]\u0006 ה\u0003פת!\u0004 ואנו יודעים שעל היין יש לברך לחוד. ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 ה\u0003יין\u0004"],["שהוא \u0003גורם ברכה לעצמו\u0004 הואיל והוא חשוב כל כך שמצרפים אליו ברכות אחרות, כגון בקידוש, הבדלה וכדומה, לכן אינו בטל לגבי הפת.","מתוך שהוזכר אחד ממיני העוגות (פת הבאה בכיסנין) מסופר כי \u0003רב הונא אכל תליסר ריפתי\u0004 \u0005[שלושה עשר לחמים,\u0006 עוגות\u0005]\u0006 \u0003בני תלתא תלתא בקבא\u0004 \u0005[שלושה שלושה בקב]\u0006 \u0003ולא בריך\u0004 \u0005[ברך]\u0006 ברכת המזון, משום שאין זה לחם ממש. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: עדי כפנא\u0004 \u0005[זהו רעב]!\u0006 כלומר, אין אדם כרגיל אוכל כמות כזו של עוגות כקינוח סעודה בלבד. \u0003אלא כל שאחרים קובעים עליו סעודה\u0004 מפני שהוא מרובה בכמותו עד כדי להשביע, \u0003צריך לברך\u0004 עליו ברכת המזון.","ועוד מסופר: \u0003רב יהודה הוה עסיק ליה לבריה\u0004 \u0005[היה עוסק לו לבנו]\u0006 לסייע בהכנות לחתונתו, עם \u0003בי\u0004 \u0005[\u0006בני \u0005בית,\u0006 משפחת\u0005]\u0006 \u0003רב יהודה בר חביבא. אייתו לקמייהו\u0004 \u0005[הביאו לפניהם]\u0006 \u0003פת הבאה בכסנין. כי אתא, שמעינהו דקא מברכי\u0004 \u0005[כאשר בא, שמע אותם שהם מברכים]\u0006 \u0003\"המוציא\". אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי\u0004 \u0005[מהו]\u0006 קול \u0003\"צי\" \"צי\" דקא שמענא\u0004 \u0005[שאני שומע]?\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003\"המוציא לחם מן הארץ\" קא מברכיתו\u0004 \u0005[אתם מברכים]?\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 כך אכן עשינו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' מונא אמר משום\u0004 (בשם) \u0003ר' יהודה: פת הבאה בכסנין מברכין עליה \"המוציא\". ואמר שמואל: הלכה כר' מונא.\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 רב יהודה: טעות היתה בידכם, \u0003אין הלכה כר' מונא אתמר\u0004 \u0005[נאמר]\u0006 בשמו של שמואל. \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003והא מר\u0004 \u0005[והרי אדוני]\u0006 \u0003הוא\u0004 ש\u0003אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003שמואל\u0004 ש\u0003לחמניות מערבין בהן\u0004 עירוב חצרות ועירוב תבשילין כמו בלחם, \u0003ו\u0004אף \u0003מברכין עליהן \"המוציא\",\u0004 ובמה עדיפות אותן לחמניות שאף הן מין עוגות מפת הבאה בכיסנין? ענה להם: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003קבע סעודתיה עלייהו\u0004 \u0005[סעודתו עליהם],\u0006 \u0003אבל היכא\u0004 \u0005[היכן]\u0006 ש\u0003לא קבע סעודתיה עלייהו\u0004 \u0005[סעודתו עליהם]\u0006 — \u0003לא\u0004 מברך עליהם \"המוציא\".","מסופר: \u0003רב פפא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן. בתר דגמר סעודתייהו אייתו לקמייהו מידי למיכל\u0004 \u0005[לאחר שגמרו סעודתם הביאו לפניהם דבר לאכול]\u0006 \u0003שקל\u0004 \u0005[לקח]\u0006 \u0003רב פפא וקא אכיל\u0004 \u0005[ואכל]\u0006 ולא ברך לפני תוספת זו. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 וכי \u0003לא סבר לה מר\u0004 \u0005[אין אדוני סבור]\u0006 כי אם \u0003גמר\u0004 סעודתו \u0003אסור\u0004 שוב \u0003מלאכול\u0004 עוד עד שיברך שנית? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003\"סלק\" אתמר\u0004 \u0005[נאמר],\u0006 וכך יש לגרוס. ומשמעות גירסה זו, שאם סילק את המזון הנותר לאחר האכילה מעל שולחנו — רק אז אסור לו להמשיך בארוחה.","ומעין זה מסופר: \u0003רבא ור' זירא איקלעו לבי ריש גלותא\u0004 \u0005[הזדמנו לבית ראש הגולה].\u0006 \u0003לבתר דסליקו תכא מקמייהו שדרו להו ריסתנא מבי ריש גלותא\u0004 \u0005[לאחר שסלקו את השולחן מלפניהם,\u0006 בגמר סעודתם, \u0005שלחו להם מנה מבית ראש הגולה].\u0006 \u0003רבא אכיל\u0004 \u0005[אכל]\u0006 \u0003ור' זירא לא אכיל\u0004 \u0005[אכל].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא לרבא: וכי \u0003לא סבר לה מר\u0004 \u0005[אין אדוני סבור]\u0006 כפי ששנינו שאם כבר \u0003סלק\u0004 שולחנו \u0003אסור מלאכול\u0004 עד שיברך בשנית? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003אנן אתכא דריש גלותא סמכינן\u0004 \u0005[אנחנו על שולחנו של ראש הגולה אנו סמוכים],\u0006 וכל עוד לא גמר הוא את סעודתו, הרי אף אורחיו נחשבים כממשיכים עוד בסעודתם.","\u0003אמר רב: הרגיל בשמן\u0004 מבושם למשוח ידיו בו לאחר סעודה — \u0003שמן מעכבו,\u0004 וכל עוד לא משח ידיו בשמן אין זה נחשב כגמר סעודתו. וכן מסופר ש\u0003אמר רב אשי: כי הוינן בי\u0004 \u0005[כאשר היינו בבית]\u0006 \u0003רב כהנא, אמר לן\u0004 \u0005[לנו]:\u0006 \u0003כגון אנן דרגילינן במשחא\u0004 \u0005[אנו שאנו רגילים בשמן]\u0006 — \u0003משחא מעכבא לן\u0004 \u0005[שמן מעכב עבורנו].\u0006 ואולם מסכמים: \u0003ולית הלכתא\u0004 \u0005[ואין הלכה]\u0006 \u0003ככל הני שמעתתא\u0004 \u0005[האמרות הללו],\u0006 ואין גמר הסעודה תלוי באותם דברים, \u0003אלא כי הא\u0004 \u0005[כמו\u0006 הלכה \u0005זו]\u0006 שקבע \u0003ר' חייא בר אשי\u0004 ש\u0003אמר\u0004 בשם \u0003רב: שלש תכיפות הן,\u0004 כלומר, שלושה דברים הבאים תכופים זה אחרי זה מיד: \u0003תכף לסמיכה\u0004 של הידים על הקרבן צריכה להיות ה\u0003שחיטה, תכף ל\u0004ברכת \u0003גאולה\u0004 שאחר קריאת שמע צריכה להיות ה\u0003תפלה,\u0004 ו\u0003תכף לנטילת ידים\u0004 במים אחרונים צריכה להיות \u0003ברכה\u0004 (ברכת המזון)","\u0003אמר אביי:\u0004 באותו סגנון \u0003אף אנו נאמר: תכף לתלמידי חכמים ברכה.\u0004 שמיד כשתלמיד חכם נמצא בבית — שורה בו הברכה. וראיה לדבר ממה \u0003שנאמר\u0004 בדברי לבן ליעקב: \u0003\"ויברכני ה' בגללך\"\u0004 (בראשית ל, כז). \u0003איבעית אימא, מהכא\u0004 \u0005[אם תרצה אמור\u0006 ראיה אחרת, \u0005מכאן]\u0006 \u0003שנאמר \"\u0004ויהי מאז הפקיד אותו בביתו ועל כל אשר יש לו \u0003ויברך ה' את בית המצרי בגלל יוסף\"\u0004 (בראשית לט, ה).","במשנה זו מבואר באלו מקרים ובאלו נסיבות פוטרות ברכות על מאכלים מסויימים את שאר המאכלים באותה סעודה. \u0003ברך על היין שלפני המזון\u0004 (הסעודה) — \u0003פטר\u0004 בברכה זו \u0003את היין שלאחר המזון.\u0004 וכן אם \u0003ברך על הפרפרת\u0004 (מיני לחם מתובלים וכדומה) \u0003שלפני המזון\u0004 — \u0003פטר\u0004 בברכה זו \u0003את הפרפרת שלאחר המזון. ברך על הפת\u0004 (לחם) — \u0003פטר\u0004 בברכה זו \u0003את הפרפרת\u0004 לפי שהיא נחשבת כטפלה לו. ולעומת זאת אם בירך \u0003על הפרפרת\u0004 — \u0003לא פטר\u0004 בכך \u0003את הפת. בית שמאי אומרים: אף לא\u0004 פוטר בכך \u0003מעשה קדרה,\u0004 התבשילים שבתוך הסעודה.","ודין נוסף הנדון במשנה: \u0003היו יושבין\u0004 כמה אנשים לאכול בלי לקבוע סעודה משותפת — \u0003כל אחד\u0004 מהם \u0003מברך לעצמו. הסבו\u0004 לאכול על גבי מיטות, שאז נחשבת זו לסעודת קבע משותפת — \u0003אחד מברך לכולן,\u0004 עבור כולם."],["ודין נוסף: \u0003בא להם יין בתוך המזון\u0004 — \u0003כל אחד ואחד\u0004 מן המסובים \u0003מברך\u0004 עליו \u0003לעצמו.\u0004 ואם בא להם היין \u0003אחר המזון\u0004 — \u0003אחד מברך לכולם. והוא,\u0004 המברך על היין שלאחר המזון — הוא ה\u0003אומר\u0004 ברכה גם \u0003על המוגמר\u0004 (מיני בשמים וקטורת שהיו מביאים למקום הסעודה), \u0003ואף על פי שאין מביאין את המוגמר אלא לאחר סעודה.\u0004","על דברי המשנה שיין שלפני המזון פוטר את היין שלאחר המזון \u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: לא שנו\u0004 הלכה זו \u0003אלא בשבתות וימים טובים, הואיל ו\u0004יש פנאי להמשיך ולשתות יין \u0003אדם קובע סעודתו על היין. אבל בשאר ימות השנה,\u0004 אדם השותה יין בסעודתו \u0003מברך על כל כוס וכוס\u0004 משום שאינו מתכוון מתחילה לשתות הרבה.","ואכן \u0003אתמר נמי\u0004 \u0005[נאמר גם כן]:\u0006 ש\u0003אמר רבה בר מרי\u0004 שכך \u0003אמר ר' יהושע בן לוי: לא שנו\u0004 כן במשנה \u0003אלא בשבתות וימים טובים, ובשעה שאדם יוצא\u0004 עייף \u0003מבית המרחץ,\u0004 ורצונו לאכול ולנוח, \u0003ובשעת הקזת דם,\u0004 כלומר, לאחר הקזת דם \u0003הואיל ואדם קובע סעודתו על היין\u0004 שרגילים לשתות אז יין רב. \u0003אבל בשאר ימות השנה\u0004 — \u0003מברך על כל כוס וכוס\u0004 לעצמה.","ומסופר ש\u0003רבה בר מרי איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רבא ב\u0004יום \u0003חול, חזייה דבריך\u0004 \u0005[ראהו שבירך]\u0006 על היין \u0003לפני המזון, והדר בריך\u0004 \u0005[וחזר ובירך]\u0006 על היין ש\u0003לאחר המזון. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יישר\u0004 (יפה עשית). \u0003וכן אמר ר' יהושע בן לוי\u0004 במקרה דומה שכך יש לנהוג.","ומסופר עוד: \u0003רב יצחק בר יוסף איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003אביי ביום טוב. חזייה דבריך אכל כסא וכסא\u0004 \u0005[ראהו ש\u0006הוא \u0005מברך על כל כוס וכוס]\u0006 של יין. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יצחק: וכי \u0003לא סבר לה מר להא\u0004 \u0005[אין אדוני סבור\u0006 כהלכה \u0005זו]\u0006 שאמר \u0003ר' יהושע בן לוי\u0004 שדי בברכה אחת?! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003נמלך אנא\u0004 \u0005[אני],\u0006 כלומר, אני לא התכוונתי להאריך בסעודה על היין. ולכן על כל כוס וכוס שאני שותה אני מחליט לחוד אם רצוני לשתותה, ולכן בכגון זה אף לשיטת ר' יהושע בן לוי יש לברך על כל אחת לעצמה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לתלמידי הישיבה שאלה זו: אם \u0003בא להם\u0004 לסועדים \u0003יין בתוך המזון\u0004 (הסעודה) \u0003מהו\u0004 הדין לענין \u0003שיפטור את היין שלאחר המזון\u0004 מברכה. וצדדי הבעיה: \u0003אם תימצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 ולהעלות את האפשרות כי כאשר \u0003ברך על היין שלפני המזון\u0004 הריהו \u0003פוטר\u0004 בכך \u0003את היין שלאחר המזון,\u0004 טעמו \u0003משום\u0004 ש\u0003זה לשתות וזה לשתות,\u0004 כלומר, שתיית יין זו היא להנאת השתיה עצמה, \u0003אבל הכא\u0004 \u0005[כאן],\u0006 שזה, היין שלאחר המזון נועד \u0003לשתות, וזה,\u0004 היין שבתוך המזון נועד \u0003לשרות\u0004 את המזון ולסייע באכילה — \u0003לא\u0004 ייחשבו שתי שתיות אלה כדבר אחד? \u0003או דילמא לא שנא\u0004 \u0005[שמא אינו שונה],\u0006 וכל שתיית יין אחת היא.","ובכך נחלקו הדעות, \u0003רב אמר: פוטר, ורב כהנא אמר: אינו פוטר. רב נחמן אמר: פוטר, ורב ששת אמר: אינו פוטר. רב הונא ורב יהודה וכל תלמידי\u0004 הישיבה של \u0003רב אמרי\u0004 \u0005[אמרו]:\u0006 \u0003אינו פוטר. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו במשנתנו: \u0003בא להם יין בתוך המזון\u0004 — \u0003כל אחד ואחד מברך לעצמו.\u0004 בא להם יין \u0003לאחר המזון\u0004 — \u0003אחד מברך לכולם.\u0004 ומכאן אפשר להסיק שאף על פי שבא להם יין בתוך המזון וברכו עליו — יש לחזור ולברך גם לאחר המזון! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך היא משמעות הדברים: המשנה אינה דנה במקרה אחד רצוף, אלא בשני מקרים שאינם קשורים זה בזה, והדין השני מדבר באופן אחר, ש\u0003אם לא בא להם יין בתוך המזון אלא לאחר המזון,\u0004 בכגון זה \u0003אחד מברך לכולם.\u0004","שנינו במשנה שאם \u0003ברך על הפת, פטר\u0004 בכך אף \u0003את הפרפרת\u0004 ואינו צריך לברך עליה בנפרד. אך אם ברך \u0003על הפרפרת, לא פטר\u0004 בכך \u0003את הפת.\u0004 ו\u0003בית שמאי אומרים\u0004 שבכך אינו פוטר \u0003אף לא מעשה קדרה,\u0004 התבשילים הבאים בסעודה.","על כך \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לבני הישיבה שאלה זו: האם \u0003בית שמאי ארישא פליגי\u0004 \u0005[על ההתחלה\u0006 הם \u0005חולקים],\u0006 \u0003או דילמא אסיפא פליגי\u0004 \u0005[שמא על הסוף\u0006 הם \u0005חולקים]?\u0006 שאפשר לפרש בשתי הצורות: אפשר להבין \u0003דקאמר\u0004 \u0005[שאומר],\u0006 כך דעתו של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 במשנה שאם \u0003ברך על הפת\u0004 — \u0003פטר\u0004 בכך \u0003את הפרפרת, וכל שכן\u0004 שפוטר \u0003מעשה קדרה. ואתי\u0004 \u0005[ובאים]\u0006 \u0003בית שמאי למימר\u0004 \u0005[לומר]\u0006 כי \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לגבי \u0003פרפרת\u0004 ש\u0003לא פטרה להו\u0004 \u0005[פוטרת אותה]\u0006 הברכה על ה\u0003פת, אלא אפילו\u0004 את \u0003מעשה קדרה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא פטרה\u0004 \u0005[פוטרת]\u0006 ברכת הפת. \u0003או דילמא אסיפא פליגי\u0004 \u0005[שמא על הסוף\u0006 הם \u0005חולקים],\u0006 \u0003דקתני\u0004 \u0005[ששנינו]:\u0006 אם \u0003ברך על הפרפרת\u0004 — \u0003לא פטר\u0004 בברכה זו \u0003את הפת.\u0004 וכך יש להבין: דווקא את ה\u0003פת הוא שלא פטר\u0004 הפרפרת, \u0003אבל מעשה קדרה\u0004 — \u0003פטר. ואתו\u0004 \u0005[ובאו]\u0006 \u0003בית שמאי למימר\u0004 \u0005[לומר]\u0006 ש\u0003אפילו מעשה קדרה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא פטר\u0004 בכך מברכה.","בעיה זו לא נפתרה, ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנה שאם \u0003היו יושבין\u0004 הסועדים בלי לקבוע סעודה משותפת — \u0003כל אחד ואחד\u0004 מברך לעצמו, ואם הסבו מראש לסעודה משותפת — אחד מברך לכולם. ומדייקים: דווקא כאשר \u0003הסבו\u0004 כאחד — \u0003אין\u0004 \u0005[כן],\u0006 נחשב הדבר לסעודת קבע, אבל כאשר \u0003לא הסבו\u0004 — \u0003לא. ורמינהו\u0004 \u0005[ומשליכים],\u0006 מראים סתירה לדבר ממה ששנינו במקור אחר: \u0003עשרה שהיו הולכים בדרך אף על פי שכולם אוכלים מככר אחד\u0004 — \u0003כל אחד ואחד מברך לעצמו. ישבו לאכול, אף על פי שכל אחד ואחד אוכל מככרו\u0004 שלו — \u0003אחד מברך לכולם,\u0004 שכן זו נחשבת כסעודה משותפת. מכל מקום \u0003קתני\u0004 \u0005[שנינו]\u0006 לשון \u0003\"ישבו\u0004 לאכול \u0003\"\u0004ומשמע: \u0003אף על פי שלא הסבו,\u0004 ומכאן שעצם הישיבה לאכול הריהי כקביעת סעודה בלי קשר להיות מסובים!","\u0003אמר רב נחמן בר יצחק:\u0004 מה שאמרו בענין ההולכים בדרך היה \u0003כגון דאמרי\u0004 \u0005[שאמרו]:\u0006 \u0003\"ניזיל וניכול לחמא בדוך פלן\"\u0004 \u0005[\"נלך ונאכל לחם במקום פלוני\"],\u0006 ומכיון שהסכימו מראש על אכילה במקום מסויים — הרי זו קביעות סעודה.","ובנושא זה מסופר: \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 מת\u0005]\u0006 \u0003רב, אזלו\u0004 \u0005[הלכו]\u0006 \u0003תלמידיו בתריה\u0004 \u0005[אחריו]\u0006 ללוות את ארונו אל העיר בה נקבר. \u0003כי הדרי, אמרי\u0004 \u0005[כאשר חזרו, אמרו]:\u0006 \u0003ניזיל וניכול לחמא\u0004 \u0005[נלך ונאכל לחם]\u0006 על \u0003נהר דנק. בתר דכרכי, יתבי, וקא מיבעיא להו\u0004 \u0005[אחרי שאכלו, ישבו, ונשאלה להם]\u0006 שאלה זו: האם \u0003\"הסבו\" דוקא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 \u0003אבל\u0004 אם רק \u0003ישבו\u0004 בלא הסבה \u0003לא\u0004 נחשב להם הדבר לסעודת קבע, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כיון דאמרי\u0004 \u0005[שאמרו]\u0006 \u0003\"ניזיל וניכול ריפתא בדוכתא פלניתא\"\u0004 \u0005[\"נלך ונאכל לחם במקום פלוני\"]\u0006 — \u0003כי\u0004 \u0005[כמו]\u0006 \u0003הסבו דמי\u0004 \u0005[נחשב\u0006 הדבר\u0005]?\u0006 \u0003לא הוה בידייהו\u0004 \u0005[היה בידם],\u0006 לא מצאו מענה לשאלה.","\u0003קם\u0004 \u0005[עמד]\u0006 \u0003רב אדא בר אהבה\u0004"],["\u0003אהדר קרעיה\u0004 \u0005[החזיר\u0006 את \u0005קרעו],\u0006 את המעיל שבו היה הקרע שקרע לאבלו של רב, \u0003לאחוריה\u0004 \u0005[לאחוריו]\u0006 \u0003וקרע קריעה אחרינא\u0004 \u0005[אחרת]\u0006 של אבל, ו\u0003אמר: נח נפשיה\u0004 \u0005[נחה נפשו]\u0006 של \u0003רב, וברכת מזונא\u0004 \u0005[המזון]\u0006 על דיניה השונים עדיין \u0003לא גמרינן\u0004 \u0005[למדנו].\u0006 \u0003עד דאתא ההוא סבא\u0004 \u0005[שבא זקן אחד],\u0006 \u0003רמא להו מתניתין\u0004 \u0005[השליך,\u0006 הראה \u0005להם\u0006 סתירה מן \u0005המשנה]\u0006 על \u0003ברייתא,\u0004 כדרך שהובא קודם, \u0003ושני להו\u0004 \u0005[ותירץ להם]\u0006 ש\u0003כיון דאמרי \"ניזיל וניכול לחמא בדוך פלן\"\u0004 \u0005[שאמרו \"נלך ונאכל לחם במקום פלוני\"]\u0006 — \u0003כהסבו דמי\u0004 \u0005[נחשב\u0006 הדבר\u0005].\u0006","שנינו במשנה שכאשר \u0003הסבו, אחד מברך\u0004 עבור כולם. \u0003אמר רב: לא שנו\u0004 במשנה דין זה \u0003אלא\u0004 לגבי \u0003פת\u0004 לחם \u0003דבעי\u0004 \u0005[ש\u0006היא \u0005צריכה]\u0006 \u0003הסבה\u0004 כדי שיוכל אחד לברך עבור כולם, \u0003אבל יין לא בעי\u0004 \u0005[אינו צריך]\u0006 לענין זה \u0003הסבה. ור' יוחנן אמר: אפילו יין נמי\u0004 \u0005[גם כן]\u0006 \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003הסבה,\u0004 ובלא הסבה כל אחד מברך לעצמו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך \u0003אמר רב: לא שנו\u0004 דין זה במשנה \u0003אלא\u0004 לגבי \u0003פת\u0004 — \u0003דמהניא ליה\u0004 \u0005[שמועילה לו]\u0006 \u0003הסבה,\u0004 שאם אוכלים בצוותא אחד יכול לברך עבור כולם. \u0003אבל יין\u0004 — \u0003לא מהניא ליה\u0004 \u0005[מועילה לו]\u0006 \u0003הסבה\u0004 לצירוף וכל אחד מברך עליו לעצמו. \u0003ור' יוחנן אמר: אפילו יין נמי מהניא ליה\u0004 \u0005[גם כן מועילה לו]\u0006 \u0003הסבה.\u0004","על דברים אלה \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בתוספתא: \u0003כיצד סדר הסבה?\u0004 — ה\u0003אורחין נכנסין ויושבין על גבי ספסלין ועל גבי קתדראות\u0004 (כסאות) \u0003עד שיכנסו כולם.\u0004 לאחר שכולם נכנסו, \u0003הביאו להם מים\u0004 ו\u0003כל אחד ואחד נוטל\u0004 את \u0003ידו אחת,\u0004 כדי להחזיק בה את כוס היין. ולפני הסעודה כאשר \u0003בא להם יין\u0004 — \u0003כל אחד ואחד מברך\u0004 עליו \u0003לעצמו.\u0004 לאחר מכן כאשר \u0003עלו\u0004 על המטות \u0003והסבו\u0004 לסעודה עצמה \u0003ובא להם מים\u0004 ראשונים לנטילת ידים לסעוד, \u0003אף על פי שכל אחד ואחד\u0004 כבר \u0003נטל\u0004 את \u0003ידו\u0004 ה\u0003אחת,\u0004 מכל מקום \u0003חוזר ונוטל שתי ידיו\u0004 כדי שיוכל לאחוז את המזון בשתי ידיו. ואם \u0003בא להם יין\u0004 בתוך הסעודה — \u0003אף על פי שכל אחד ואחד\u0004 כבר \u0003ברך לעצמו,\u0004 מכל מקום עכשיו \u0003אחד מברך\u0004 עליו \u0003לכולם.\u0004","ואם כן, \u0003להאיך לישנא\u0004 \u0005[לאותה לשון,\u0006 גירסה\u0005]\u0006 ש\u0003אמר רב\u0004 ש\u0003לא שנו\u0004 במשנה \u0003אלא\u0004 לגבי \u0003פת דבעי\u0004 \u0005[שצריך]\u0006 שתהיה \u0003הסבה,\u0004 שרק אם הסבו ביחד אחד מברך לכולם, \u0003אבל יין לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003הסבה\u0004 כדי שיוכל אחד לברך עבור כולם, \u0003קשיא רישא\u0004 \u0005[קשה ההתחלה]\u0006 ששנינו בה שהאורחים מברכים על היין כל אחד לעצמו!","ומתרצים: \u0003שאני אורחין דדעתייהו למיעקר\u0004 \u0005[שונים\u0006 הם ה\u0005אורחים שדעתם לעקור],\u0006 שלפי שעה יושבים הם באולם שלפני חדר הסעודה, ודעתם לצאת ממנו מיד ולהיכנס לחדר האוכל, ולכן אין ישיבתם יחד נחשבת כישיבה של סעודה.","\u0003ולהאיך לישנא\u0004 \u0005[ולאותה לשון]\u0006 ש\u0003אמר רב\u0004 ש\u0003לא שנו\u0004 במשנה שאם הסבו אחד מברך לכולם \u0003אלא\u0004 לגבי \u0003פת,\u0004 מכיון \u0003דמהניא ליה\u0004 \u0005[שמועילה לו]\u0006 \u0003הסבה\u0004 לענין זה, \u0003אבל יין לא מהניא ליה\u0004 \u0005[מועילה לו]\u0006 \u0003הסבה\u0004 לענין זה, אם כן \u0003קשיא סיפא\u0004 \u0005[קשה הסוף]\u0006 שהרי נאמר שעל היין שבזמן ההסבה אחד מברך לכולם!","על כך משיבים: \u0003שאני התם, דמגו דקא מהניא ליה\u0004 \u0005[שונה שם, שמתוך שמועילה לו]\u0006 ה\u0003הסבה לפת\u0004 — \u0003מהניא ליה\u0004 \u0005[מועילה לו]\u0006 ה\u0003הסבה ליין,\u0004 שמאחר ונחשבת ההסבה כצירוף לענין אכילת הלחם נחשבת גם כצירוף לשתיית היין.","שנינו במשנה שאם \u0003בא להם יין בתוך המזון\u0004 כל אחד מברך לעצמו. ומסופר בתוספתא: ש\u0003שאלו את בן זומא:\u0004 מה טעמה של הלכה זו, \u0003מפני מה אמרו\u0004 חכמים שאם \u0003בא להם יין בתוך המזון\u0004 — \u0003כל אחד ואחד מברך לעצמו,\u0004 ואם בא להם \u0003לאחר המזון\u0004 — \u0003אחד מברך לכולם? אמר להם: טעם הדבר, הואיל ו\u0004בשעת האכילה \u0003אין בית הבליעה פנוי,\u0004 ואם ירצה אחד לברך עבור כולם יצטרך להמתין עד שיפסיקו כולם לאכול ויוכלו לפנות עצמם לשתיית כוס היין יחד (תוספות), וכדי למנוע טירחה פסקו שאין צורך לברך יחד.","שנינו במשנה ש\u0003הוא,\u0004 המברך, \u0003אומר\u0004 ברכה \u0003על המוגמר\u0004 (מיני בשמים וקטורת שהיו מביאים למקום הסעודה). ושואלים: \u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנינו]\u0006 \u0003\"והוא אומר על המוגמר\", מכלל\u0004 הדבר אתה למד \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003עדיף מיניה\u0004 \u0005[ממנו],\u0006 ומכל מקום הוא המברך על המוגמר, \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 מברך הוא, יברך זה שעדיף ממנו!","ומשיבים: \u0003הואיל והוא נטל ידיו תחלה באחרונה,\u0004 במים אחרונים לפני ברכת המזון, לכן הוא המברך על המוגמר.","ומעירים: דברי זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לרב,\u0004 ש\u0003אמר רב חייא בר אשי אמר רב: הנוטל ידיו תחלה באחרונה\u0004 — \u0003הוא מזומן לברכה,\u0004 שהוא זה שמברך. ומסופר: \u0003רב ור' חייא הוו יתבי קמיה\u0004 \u0005[היו יושבים לפני]\u0006 \u0003רבי בסעודתא\u0004 \u0005[בסעודה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי לרב: קום משי ידך\u0004 \u0005[רחץ את ידיך].\u0006 \u0003חזייה דהוה\u0004 \u0005[ראהו\u0006 ר' חייא לרב \u0005שהיה]\u0006 \u0003מרתת,\u0004 רועד. שרב חשב שרבי רומז לו בזה שהוא מרבה לאכול יותר מדי, או שידיו אינן נקיות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא\u0004 לרב: \u0003בר פחתי\u0004 \u0005[בן אצילים],\u0006 \u0003עיין בברכת מזונא קאמר\u0004 \u0005[המזון אמר]\u0006 \u0003לך,\u0004 שכוונתו היתה שתרחץ ידיך ראשון ותוכל להתכונן לברך.","ואגב הזכרת הברכה על המוגמר מביאים הלכות אחדות בברכות הריח. \u0003אמר ר' זירא אמר רבא בר ירמיה: מאימתי מברכין על הריח\u0004 של המוגמר? — \u0003משתעלה תמרתו,\u0004 כאשר עולה תימרת עשן מן הקטורת כשמניחים אותה על גבי הגחלים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לרבא בר ירמיה: והא\u0004 \u0005[והרי]\u0006 \u0003לא קא ארח\u0004 \u0005[הריח]?\u0006 שאמנם עשן הקטורת עולה, אך עדיין לא הריח בו המברך. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא בר ירמיה: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 ברכת \u0003\"המוציא לחם מן הארץ\"\u0004 ש\u0003מברך\u0004 אדם לפני אכילת לחם, \u0003והא\u0004 \u0005[והרי]\u0006 עדיין \u0003לא אכל\u0004 ממנה! \u0003אלא\u0004 ודאי אומרים שהוא מברך כיון ש\u0003דעתיה למיכל\u0004 \u0005[דעתו לאכול],\u0006 \u0003הכא נמי דעתיה לארוחי\u0004 \u0005[כאן גם כן דעתו להריח].\u0006","\u0003אמר ר' חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003אבא בר נחמני\u0004 שכך \u0003אמר רב חסדא\u0004 שכך \u0003אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב חסדא\u0004 שכך \u0003אמר זעירי: כל המוגמרות\u0004 (הקטורת) \u0003מברכין עליהן \"בורא עצי בשמים\" חוץ ממושק,\u0004 לפי \u0003שמן חיה הוא,\u0004 שכן הוא מופק מהפרשתה של חיה, \u0003שמברכין עליו \"בורא מיני בשמים\".\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003אין מברכין \"בורא עצי בשמים\" אלא על\u0004 מיני \u0003אפרסמון של בית רבי, ועל אפרסמון של בית\u0004 ה\u0003קיסר, ועל ההדס שבכל מקום,\u0004 ולדבריהם מברכים כן על כל המוגמרות!","ומעירים: אכן זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על מה שנאמר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרב יצחק: האי משחא\u0004 \u0005[שמן זה]\u0006 של \u0003אפרסמון מאי\u0004 \u0005[מה]\u0006 \u0003מברכין עלויה\u0004 \u0005[עליו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יצחק, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב יהודה:\u0004 ברכתו היא \u0003\"בורא שמן ארצנו\",\u0004 כי האפרסמון צמח למעשה רק בארץ ישראל, בבקעת הירדן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003בר מיניה\u0004 \u0005[חוץ ממנו]\u0006 מ\u0003ר' יהודה דחביבא ליה\u0004 \u0005[שחביבה עליו]\u0006 \u0003ארץ ישראל\u0004 ביותר ולכן מזכיר הוא אותה בנוסח הברכה, ואולם \u0003לכולי עלמא מאי\u0004 \u0005[ל\u0006דעת \u0005כולם,\u0006 כל שאר החכמים, \u0005מה]\u0006 יש לברך על שמן אפרסמון?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן:\u0004 ברכתו היא \u0003\"בורא שמן ערב\".\u0004","\u0003אמר רב אדא בר אהבה: האי כשרתא\u0004 \u0005[אותו\u0006 מין \u0005בושם]\u0006 \u0003מברכין עלויה\u0004 \u0005[עליו]\u0006 \u0003\"בורא עצי בשמים\", אבל\u0004 על \u0003משחא כבישא\u0004 \u0005[שמן כבוש],\u0006 שהוא שמן זית שכבשוהו עם בשמים כדי שיקלוט את ריחם — \u0003לא. ורב כהנא אמר: אפילו משחא כבישא\u0004 ברכתו \"בורא עצי בשמים\", \u0003אבל משחא טחינא,\u0004 שמן שטחנו בשמים והניחום בתוכו — \u0003לא.\u0004 ואילו \u0003נהרדעי\u0004 \u0005[חכמי נהרדעא]\u0006 \u0003אמרי\u0004 \u0005[אומרים]\u0006 ש\u0003אפילו\u0004 על \u0003משחא טחינא\u0004 \u0005[שמן טחון]\u0006 הפחות עוד בטיבו יש לברך כן."],["\u0003אמר רב גידל אמר רב: האי סמלק\u0004 שהוא עשב ריחני \u0003מברכין עלויה\u0004 \u0005[עליו]\u0006 \u0003\"בורא עצי בשמים\". אמר רב חננאל אמר רב: הני חלפי דימא\u0004 שהוא עשב בושם הגדל ליד הים \u0003מברכין עלייהו\u0004 \u0005[עליהם]\u0006 \u0003\"בורא עצי בשמים\". אמר מר זוטרא: מאי קראה\u0004 \u0005[מה הכתוב]\u0006 ממנו הוכחה לכך שקוראים \"עץ\" לדבר שיש בו רק גבעולים רכים למדי — \u0003\"והיא העלתם הגגה ותטמנם בפשתי העץ\"\u0004 (יהושע ב, ו), הרי שאף גבעולי הפשתן נקראים \"עץ\".","\u0003רב משרשיא אמר: האי נרקום דגינוניתא\u0004 \u0005[זה נרקיס הגינה]\u0006 \u0003מברכין עלויה\u0004 \u0005[עליו]\u0006 \u0003\"בורא עצי בשמים\".\u0004 ועל \u0003דדברא\u0004 \u0005[\u0006הגדל \u0005בשדה]\u0006 ואינו דומה למין התרבותי מברכים \u0003\"בורא עשבי בשמים\". אמר רב ששת: הני סיגלי\u0004 \u0005[אלה הסיגלים]\u0006 שהם עשבי ריח, \u0003מברכין עלייהו\u0004 \u0005[עליהם]\u0006 \u0003\"בורא עשבי בשמים\". אמר מר זוטרא: האי מאן דמורח באתרוגא או בחבושא\u0004 \u0005[מי שמריח באתרוג או בחבוש]\u0006 \u0003אומר: \"ברוך שנתן ריח טוב בפירות\".\u0004","ואגב ברכת הריח הובאה הלכה ש\u0003אמר רב יהודה: האי מאן דנפיק ביומי\u0004 \u0005[מי שיוצא בימי,\u0006 בתקופת\u0005]\u0006 \u0003ניסן וחזי אילני דקא מלבלבי\u0004 \u0005[ורואה אילנות שהם מלבלבים],\u0006 \u0003אומר: \"ברוך שלא חיסר בעולמו כלום וברא בו בריות טובות ואילנות טובות להתנאות בהן בני אדם\". אמר רב זוטרא בר טוביה אמר רב: מנין\u0004 בכתוב ראיה לכך \u0003שמברכין על הריח?\u0004 — \u0003שנאמר: \"כל הנשמה תהלל יה\"\u0004 (תהלים קנ,ו), שהוא מפרשו: \u0003איזהו דבר שהנשמה נהנית ממנו ואין הגוף נהנה ממנו?\u0004 — \u0003הוי אומר: זה הריח.\u0004 וראיה היא שאף על הדברים שרק הנשמה נהנית מהם מברך (\"תהלל\") את ה'.","\u0003ו\u0004עוד \u0003אמר רב זוטרא בר טוביה אמר רב: עתידים בחורי ישראל שיתנו ריח טוב כלבנון.\u0004 וראיה לדבר ממה \u0003שנאמר: \"ילכו יונקותיו, ויהי כזית הודו וריח לו כלבנון\"\u0004 (הושע יד, ז).","\u0003ו\u0004עוד \u0003אמר רב זוטרא בר טוביה אמר רב: מאי דכתיב\u0004 \u0005[מהי\u0006 משמעות זה \u0005שנאמר]\u0006 \u0003\"את הכל עשה יפה בעתו\u0004 גם את העולם נתן בלבם מבלי אשר לא ימצא האדם את המעשה אשר עשה האלהים מראש ועד סוף\u0003\"\u0004 (קהלת ג, יא) — \u0003מלמד שכל אחד ואחד יפה לו הקדוש ברוך הוא\u0004 את \u0003אומנתו בפניו,\u0004 שכל אדם יהיה מרוצה באומנותו, ובכך יתנהל העולם כסדרו.","\u0003אמר רב פפא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 כפתגם עממי: \u0003\"תלה ליה קורא\u0004 \u0005[לו קור]\u0006 דקל \u0003לדבר אחר\u0004 (חזיר), \u0003ואיהו דידיה עביד\u0004 \u0005[והוא\u0006 את \u0005שלו יעשה]\u0006 \u0003\".\u0004 שאף שקור הדקל הוא מאכל ערב, יגלגל החזיר אותו באשפה כדי להנות ממנו על פי דרכו שלו; שטעמו של כל יצור שונה ואין להשוות בין אנשים שונים.","\u0003ו\u0004עוד \u0003אמר רב זוטרא בר טוביה אמר רב: אבוקה כשנים,\u0004 שההולך בדרך חשוכה ואבוקה בידו, הרי זה כאילו הלכו שנים, \u0003ו\u0004אור ה\u0003ירח\u0004 הריהו \u0003כשלשה. איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לבני הישיבה שאלה זו: האם \u0003אבוקה\u0004 נחשבת \u0003כשנים בהדי דידיה\u0004 \u0005[ביחד אתו],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003אבוקה כשנים לבר מדידיה\u0004 \u0005[חוץ ממנו]?\u0006 \u0003תא שמע\u0004 \u0005[בואר\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו שם \u0003וירח כשלשה, אי אמרת בשלמא בהדי דידיה\u0004 \u0005[נניח אם אומר אתה\u0006 כי הכוונה \u0005ביחד אתו]\u0006 — \u0003שפיר\u0004 \u0005[יפה,\u0006 מוטב\u0005],\u0006 \u0003אלא אי אמרת לבר מדידיה\u0004 \u0005[אם אומר אתה\u0006 כי לאור הירח הריהם כשלושה \u0005חוץ ממנו],\u0006 אם כן ביחד הריהם ארבעה, ו\u0003ארבעה למה לי?\u0004 מה הצורך בארבעה? \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003ל\u0004אדם \u0003אחד\u0004 ההולך בלילה \u0003נראה\u0004 השד \u0003ומזיק, לשנים נראה ואינו מזיק,\u0004 ואילו \u0003לשלשה אינו נראה כל עיקר.\u0004 ואין אם כן כל צורך בארבעה! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא למד ממנה]\u0006 כי מה ששנינו \u0003\"אבוקה כשנים\"\u0004 משמעו — \u0003בהדי דידיה\u0004 \u0005[ביחד אתו].\u0006 ומעירים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003ו\u0004עוד \u0003אמר רב זוטרא בר טוביה אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב חנא בר ביזנא אמר ר' שמעון חסידא\u0004 \u0005[החסיד],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: נוח לו לאדם\u0004 מצד הערך המוסרי \u0003שיפיל עצמו לתוך כבשן האש ואל ילבין פני חברו ברבים. מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? — \u0003מתמר\u0004 כלת יהודה, \u0003ש\u0004כאשר הוציאוה להישרף \u0003נאמר: \"היא מוצאת\u0004 והיא שלחה אל חמיה לאמר לאיש אשר אלה לו אנוכי הרה ותאמר הכר נא למי החותמת והפתילים והמטה האלה\u0003\"\u0004 (בראשית לח, כה). שאף בזמן שהוציאוה להשרף לא גילתה שהיא הרה ליהודה, אלא הניחה לו להבין בעצמו, כדי שלא לביישו ברבים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם \u0003הביאו לפניו שמן\u0004 ריחני \u0003והדס\u0004 יחד, \u0003בית שמאי אומרים מברך על השמן\u0004 תחילה \u0003ואחר כך מברך על ההדס. ובית הלל אומרים: מברך על ההדס\u0004 תחילה \u0003ואחר כך מברך על השמן. אמר רבן גמליאל: אני אכריע\u0004 במחלוקת זו כדעת בית שמאי שראוי להקדים את הברכה על השמן, שכן הוא עדיף. שהרי \u0003שמן זכינו לריחו וזכינו לסיכתו\u0004 ואילו \u0003הדס\u0004 רק \u0003לריחו זכינו\u0004 ואולם \u0003לסיכתו לא זכינו. אמר ר' יוחנן: הלכה כדברי המכריע,\u0004 רבן גמליאל.","ומסופר: \u0003רב פפא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא. אייתו לקמייהו\u0004 \u0005[הביאו לפניהם]\u0006 \u0003שמן\u0004 ריחני \u0003והדס, שקל\u0004 \u0005[לקח]\u0006 \u0003רב פפא, בריך\u0004 \u0005[בירך]\u0006 על ה\u0003הדס ברישא\u0004 \u0005[בתחילה],\u0006 \u0003והדר בריך\u0004 \u0005[ואחר כך]\u0006 בירך על ה\u0003שמן. אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: וכי \u0003לא סבר לה מר\u0004 \u0005[אין אדוני סבור]\u0006 כי \u0003הלכה כדברי המכריע?\u0004 ואם כן במקרה זה היה צריך לנהוג להיפך! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רבא: הלכה כבית הלל.\u0004 ומעירים: \u0003ולא היא\u0004 (ואינו כן), שלא אמר רבא הלכה זו, \u0003אלא לאשתמוטי נפשיה\u0004 \u0005[להשמיט עצמו]\u0006 \u0003הוא דעבד\u0004 \u0005[שעשה,\u0006 אמר\u0005]\u0006 כך, שעל ידי כך הצדיק לכאורה את מה שעשה בטעות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 בברייתא: אם \u0003הביאו לפניהם שמן\u0004 ריחני \u0003ויין, בית שמאי אומרים: אוחז\u0004 את \u0003השמן בימינו,\u0004 מאחר שקודם יש לברך בתחילה על השמן, \u0003ואת היין בשמאלו,\u0004 ואחר כך \u0003מברך על השמן וחוזר\u0004 אחר כך \u0003ומברך על היין.\u0004 ו\u0003בית הלל אומרים\u0004 היפך הדברים: \u0003אוחז את היין בימינו ואת השמן בשמאלו,\u0004 ואחר כך \u0003מברך על היין וחוזר ומברך על השמן. ו\u0004לאחר שמברך על השמן וסכו על ידיו הריהו \u0003טחו\u0004 \u0005[מורחו]\u0006 את השמן \u0003בראש השמש,\u0004 כדי שלא ישארו ידיו מבושמות. \u0003ואם\u0004 ה\u0003שמש תלמיד חכם הוא\u0004 — \u0003טחו\u0004 לשמן \u0003בכותל, מפני שגנאי לתלמיד חכם לצאת לשוק כשהוא מבושם.\u0004","ובהקשר לכך מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003ששה דברים\u0004 הם \u0003גנאי לו לתלמיד חכם: אל יצא כשהוא מבושם לשוק, ואל יצא\u0004 מביתו כשהוא \u0003יחידי בלילה, ואל יצא במנעלים המטולאים, ואל יספר עם אשה בשוק, ואל יסב בחבורה של עמי הארץ, ואל יכנס באחרונה לבית המדרש. ויש אומרים\u0004 כי \u0003אף לא יפסיע פסיעה גסה. ו\u0004כן \u0003לא יהלך בקומה זקופה.\u0004","את הדברים המובאים בברייתא האלה מבארים בגמרא. על מה ששנינו ש\u0003אל יצא\u0004 תלמיד חכם \u0003כשהוא מבושם לשוק, אמר ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא אמר ר' יוחנן:\u0004 איסור זה הוא רק \u0003במקום שחשודים\u0004 בו אנשיו \u0003על משכב זכור\u0004 (זכר). שגבר היוצא מבושם במקום כזה לשוק יבואו לחושדו בכך. \u0003אמר רב ששת: לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה אלא כשהיה מבושם \u0003בבגדו, אבל\u0004 אם היה מבושם \u0003בגופו\u0004 — מותר, כי ודאי ה\u0003זיעה מעברא ליה.\u0004 \u0005[מעבירה אותו].\u0006 \u0003אמר רב פפא: שערו\u0004 לענין זה הריהו \u0003כבגדו. ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003שערו\u0004 דינו \u0003כגופו.\u0004","ומה ששנינו בברייתא ש\u0003אל יצא יחידי בלילה,\u0004 הריהו \u0003משום חשדא\u0004 \u0005[חשד]\u0006 זנות. \u0003ו\u0004לכן \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שאסור \u0003אלא\u0004 באופן ש\u0003לא קביע ליה עידנא\u0004 \u0005[קבוע לו\u0006 בלילה \u0005זמן]\u0006 מיוחד ללימוד אצל רבו, \u0003אבל\u0004 אם \u0003קביע ליה עידנא\u0004 \u0005[קבוע לו זמן]\u0006 כזה — \u0003מידע ידיע דלעידניה קאזיל\u0004 \u0005[ידוע\u0006 לכל \u0005של\u0006 צורך אותו \u0005זמן,\u0006 אותו שיעור, \u0005הוא הולך]\u0006 ושוב אין חושדים בו.","ומה ששנינו ש\u0003אל יצא\u0004 תלמיד חכם \u0003במנעלים המטולאים,\u0004 הרי זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003ל\u0004דברי \u0003ר' חייא בר אבא.\u0004 ש\u0003אמר ר' חייא בר אבא: גנאי הוא לתלמיד חכם שיצא במנעלים המטולאים. ומקשים: איני\u0004 \u0005[וכך הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' חייא בר אבא\u0004 עצמו \u0003נפיק\u0004 \u0005[יצא]\u0006 במנעלים מטולאים! \u0003אמר מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן:\u0004 הדבר אסור רק \u0003בטלאי על גבי טלאי. ו\u0004עוד: \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא בפנתא\u0004 \u0005[ב\u0006יחס ל\u0005עור החופה את הנעל מלמעלה],\u0006 \u0003אבל בגילדא\u0004 \u0005[בסוליה]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור. \u0003ובפנתא\u0004 \u0005[ובעור החופה את הנעל]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 כשהוא \u0003באורחא\u0004 \u0005[בדרך],\u0006 \u0003אבל\u0004 כשהוא \u0003בביתא\u0004 \u0005[בבית]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא בימות החמה,\u0004 שהכל רואים את הטלאי, \u0003אבל בימות הגשמים,\u0004 שהבוץ מכסה את הנעלים והטלאי אינו נראה — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה.\u0004","ועל מה ששנינו בברייתא ש\u0003אל יספר\u0004 תלמיד חכם \u0003עם אשה בשוק, אמר רב חסדא:\u0004 אשה זו שאמרו — \u0003ואפילו היא אשתו. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 שאל ישוחח אדם עם אשה בשוק \u0003אפילו היא אשתו, ואפילו היא בתו ואפילו היא אחותו,\u0004 כי \u0003אין הכל בקיאין\u0004 לדעת מה הן \u0003קרובותיו\u0004 ויבואו לרנן אחריו.","ועל מה ששנינו בברייתא ש\u0003אל יסב\u0004 תלמיד חכם \u0003בחבורה של עמי הארץ,\u0004 מסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003דילמא אתי לאמשוכי בתרייהו\u0004 \u0005[שמא יבוא להמשך אחריהם].\u0006","ואת מה ששנינו ש\u0003אל יכנס\u0004 תלמיד חכם \u0003אחרונה לבית המדרש,\u0004 מסבירים: \u0003משום דקרו ליה\u0004 \u0005[שקוראים לו]\u0006 \u0003\"פושע\",\u0004 כלומר, רשלן ועצלן.","\u0003ויש אומרים,\u0004 ש\u0003אף לא יפסיע\u0004 תלמיד חכם \u0003פסיעה גסה,\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003פסיעה גסה נוטלת אחד מחמש מאות ממאור עיניו של אדם.\u0004 ושואלים: \u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]\u0006 של המפסיע פסיעה גסה? ומשיבים: \u0003להדריה בקדושא דבי שמשי\u0004 \u0005[שיחזיר אותו בקידוש של ליל שבת],\u0006 שהוא סגולה לכך.","עוד שנינו בברייתא ש\u0003אל יהלך\u0004 תלמיד חכם \u0003בקומה זקופה,\u0004 אלא כפוף קצת. וזהו כפי ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003המהלך בקומה זקופה\u0004 בדרך גאווה \u0003אפילו ארבע אמות,\u0004 הריהו \u0003כאילו דוחק את רגלי השכינה,\u0004 וכמו \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מלוא כל הארץ כבודו\"\u0004 (ישעיהו ו, ג), והמהלך בקומה זקופה מראה שאיננו חושש לכבוד ה' הנמצא גם במקום זה, ועל ידי כך כאילו גרש את ה' מאותו מקום."],["מי ש\u0003הביאו לפניו מליח\u0004 \u0005[\u0006דבר \u0005מלוח]\u0006 \u0003תחלה ופת\u0004 לחם לאכול \u0003עמו\u0004 — \u0003מברך על המליח ופוטר\u0004 בברכה זו \u0003את הפת.\u0004 וטעמו: לפי \u0003ש\u0004המליח עיקר ו\u0003הפת טפלה לו. זה הכלל: כל שהוא עיקר ועמו\u0004 באה \u0003טפלה\u0004 — \u0003מברך על העיקר ופוטר\u0004 בברכה זו \u0003את הטפלה.\u0004 מאחר שהמליח עיקר והפת טפלה.","שואלים: \u0003ומי איכא מידי דהוה\u0004 \u0005[והאם יש דבר שיהיה]\u0006 ה\u0003מליח עיקר ו\u0004ה\u0003פת טפלה\u0004 לו? שלכאורה אין סעודה שהמליח יהיה המאכל המרכזי בה! \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב עוירא אמר רב אשי: באוכלי פירות גנוסר שנו\u0004 כאן דין זה. שפירות אלה היו מתוקים ביותר, וכדי להפיג את מתיקותם היתירה היו אוכלים מאכלים מלוחים. וכדי שיוכלו לאכול אותם הצטרכו לאכול גם לחם עם המליח.","ואגב כך מפליגים בשבחם של פירות גינוסר, ש\u0003אמר רבה בר בר חנה: כי הוה אזלינן בתריה\u0004 \u0005[כאשר היינו הולכים אחרי]\u0006 \u0003ר' יוחנן למיכל\u0004 \u0005[לאכול]\u0006 \u0003פירות גנוסר, כי הוינן בי\u0004 \u0005[כאשר היינו יחד כדי]\u0006 \u0003מאה\u0004 — \u0003מנקטינן ליה לכל חד וחד\u0004 \u0005[היינו מביאים לו כל אחד ואחד]\u0006 \u0003עשרה עשרה, וכי הוינן בי\u0004 \u0005[וכאשר היינו יחד כדי]\u0006 \u0003עשרה, מנקטינן ליה כל חד וחד\u0004 \u0005[היינו מביאים לו כל אחד ואחד]\u0006 \u0003מאה מאה. וכל מאה מינייהו\u0004 \u0005[מהם]\u0006 \u0003הוה מחזיק להו צנא בר תלתא סאוי\u0004 \u0005[היה מחזיק אותם סל בן שלושת סאים]\u0006 \u0003ואכיל להו, ומשתבע דלא טעים זיונא\u0004 \u0005[ו\u0006היה \u0005אוכל אותם\u0006 כולם, \u0005ו\u0006מוכן \u0005להשבע שלא טעם מאכל]\u0006 על כך תוהים: שהוא אמר שלא טעם \u0003זיונא\u0004 \u0005[מאכל]\u0006 \u0003סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר?! \u0003אלא אימא \"מזונא\"\u0004 \u0005[אמור\u0006 שלא טעם \u0005\"מזון\"],\u0006 כלומר, שעדיין איננו שבע, מתוך טעמם הטוב של פירות גינוסר.","ועוד ספרו בהפלגה: \u0003ר' אבהו אכיל\u0004 \u0005[אכל]\u0006 פירות גינוסר \u0003עד דהוה שריק ליה דודבא מאפותיה\u0004 \u0005[שהיה הזבוב מחליק ממצחו],\u0006 כי האכילה המרובה של פירות שמנים ומתוקים גרמה להחליק את בשרו עד כדי כך. \u0003ו\u0004מסופר עוד כי \u0003רב אמי ורב אסי הוו אכלי\u0004 \u0005[היו אוכלים]\u0006 מהם \u0003עד דנתור מזייהו\u0004 \u0005[שנשרו שערותיהם].\u0006 \u0003ר' שמעון בן לקיש הוה אכיל\u0004 \u0005[היה אוכל]\u0006 \u0003עד דמריד\u0004 \u0005[שנתבלבלה דעתו].\u0006 \u0003ו\u0004אז \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' יוחנן לדבי נשיאה\u0004 \u0005[לבני בית הנשיא]\u0006 \u0003והוה משדר ליה\u0004 \u0005[והיה משלח לו]\u0006 \u0003ר' יהודה נשיאה באלושי אבתריה\u0004 \u0005[שוטרים אחריו],\u0006 \u0003ומייתי ליה לביתיה\u0004 \u0005[והיו מביאים אותו לביתו].\u0006","ובדומה לכך נמסר \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: עיר אחת היתה לו לינאי המלך בהר המלך, שהיו מוציאים ממנה ששים רבוא ספלי טרית\u0004 (סרדינים) \u0003לקוצצי תאנים מערב שבת לערב שבת,\u0004 שכה רבים היו הפועלים, וכה מתוקים היו הפירות שהוצרכו לכמות כזו של דגים מלוחים כדי לאפשר להם להמשיך בעבודתם.","ואגב סיפורים מפליגים אלה על הר המלך ועל ארץ ישראל, מספרים: \u0003כי אתא רבין אמר, אילן אחד היה לו לינאי המלך בהר המלך, שהיו מורידים ממנו ארבעים סאה גוזלות\u0004 יונים \u0003משלוש בריכות\u0004 (מחזורי לידה) \u0003ב\u0004כל \u0003חדש. כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003ר' יצחק\u0004 מארץ ישראל לבבל \u0003אמר: עיר אחת היתה בארץ ישראל וגופנית שמה, שהיו בה שמנים זוגות אחים כהנים נשואים לשמנים זוגות אחיות כהנות. ו\u0004כדי להעריך מספר האנשים שבהם יכול שיקרה דבר מעין זה, מספרים: \u0003בדקו רבנן\u0004 \u0005[חכמים]\u0006 \u0003מסורא ועד נהרדעא ולא אשכחו בר מבנתיה\u0004 \u0005[מצאו חוץ מבנותיו]\u0006 של \u0003רב חסדא, דהוו נסיבן\u0004 \u0005[שהיו נשואות]\u0006 \u0003לרמי בר חמא ול\u0004אחיו \u0003מר עוקבא בר חמא. ואף על גב דאינהו הוו כהנתא, אינהו לא הוו כהני\u0004 \u0005[ואף על פי שהן היו כהנות, הם לא היו כהנים]\u0006 שכמעט בכל שטחה של בבל לא נמצא מקרה אחד כזה.","ומכיון שהוזכר ענין המליחים, מביאים את מה ש\u0003אמר רב: כל סעודה שאין בה מלח, אינה\u0004 נחשבת ל\u0003סעודה. אמר ר' חייא בר אבא אמר ר' יוחנן: כל סעודה שאין בה שריף\u0004 \u0005[תבשיל, מרק],\u0006 \u0003אינה\u0004 נחשבת ל\u0003סעודה.\u0004","\u0003אכל\u0004 מן הפירות שנשתבחה בהם ארץ ישראל, וכגון \u0003ענבים\u0004 או \u0003תאנים\u0004 או \u0003רמונים\u0004 — \u0003מברך אחריהם שלש ברכות,\u0004 כדרך שמברך על הלחם \u0003דברי רבן גמליאל. וחכמים אומרים:\u0004 אינו מברך אלא \u0003ברכה אחת מעין שלש. ר' עקיבא אומר:\u0004 שלוש ברכות של ברכת המזון אינן מיוחדות ללחם דווקא, אלא \u0003אפילו אכל שלק\u0004 \u0005[ירקות מבושלים]\u0006 \u0003והוא\u0004 עיקר \u0003מזונו\u0004 — \u0003מברך עליו שלש ברכות.\u0004 וענין נוסף: \u0003השותה מים לצמאו\u0004 — \u0003מברך \"שהכל נהיה בדברו\". ר' טרפון אומר:\u0004 מברך \u0003\"בורא נפשות רבות וחסרונן\".\u0004 (וכל מה שחסר להן).","שואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבן גמליאל?\u0004 ומשיבים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בכתוב העוסק בשבח הארץ: \u0003\"ארץ חטה ושערה\u0004 וגפן ותאנה ורימון ארץ זית שמן ודבש\u0003\"\u0004 (דברים ח, ח), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 אחר כך: \u0003\"ארץ אשר לא במסכנת תאכל בה לחם\"\u0004 (שם שם, ט), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 אחר כך: \u0003\"ואכלת ושבעת וברכת את ה' אלהיך\u0004 על הארץ הטובה אשר נתן לך\u0003\"\u0004(שם שם, י), והוא מסיק מכאן כי הפירות שבהם נשתבחה הארץ נכללים במצוות ברכה אחר האוכל, ומאחר ובאותה פרשה נרמזו שלש ברכות, גם ברכתם היא בת שלש ברכות.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 אומרים שהכתוב \u0003\"ארץ\u0004 אשר לא במסכנות תאכל בה לחם \u0003\"הפסיק הענין,\u0004 ומצוות \"ואכלת ושבעת וברכת\" היא רק בלחם. אם כן \u0003ורבן גמליאל נמי\u0004 \u0005[גם כן]\u0006 הלא הפסוק של \u0003\"ארץ\" הפסיק הענין!\u0004 אלא הפסוק \u0003ההוא מבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003למעוטי\u0004 \u0005[למעט]\u0006 בכך את \u0003הכוסס את החטה\u0004 כשהיא חיה, שאינו צריך לברך עליה ברכת המזון אף לדעת רבן גמליאל מאחר שאינה בכלל לחם.","\u0003אמר ר' יעקב בר אידי אמר ר' חנינא: כל שהוא מחמשת המינין\u0004 של דגן הנכללים בכלל חיטה ושעורה, \u0003בתחלה,\u0004 לפני האכילה, \u0003מברך עליו \"בורא מיני מזונות\", ולבסוף,\u0004 אחר אכילתו, מברך \u0003ברכה אחת מעין שלש.\u0004","כלל אחר \u0003אמר רבא בר מרי אמר ר' יהושע בן לוי: כל שהוא משבעת המינין\u0004 של פירות שנשתבחה בהם ארץ ישראל, \u0003בתחלה\u0004 — \u0003מברך\u0004 עליו \u0003\"בורא פרי העץ\", ולבסוף\u0004 — \u0003ברכה אחת מעין שלש.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב דימי: מאי ניהו\u0004 \u0005[מה היא]\u0006 \u0003\"ברכה אחת מעין שלש\",\u0004 מהו נוסחה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אפירי\u0004 \u0005[על פירות]\u0006 ה\u0003עץ\u0004 מברכים \u0003\"על העץ ועל פרי העץ, ועל תנובת השדה, ועל ארץ חמדה טובה ורחבה שהנחלת לאבותינו לאכול מפריה ולשבוע מטובה. רחם ה' אלהינו על ישראל עמך, ועל ירושלים עירך, ועל מקדשך, ועל מזבחך. ותבנה ירושלים עיר קדשך במהרה בימינו, והעלנו לתוכה, ושמחנו בה. כי אתה ה' טוב ומטיב לכל\".\u0004","לאחר אכילת מיני מאפה העשויים מאחד מ\u0003חמשת המינין\u0004 של דגן, אומר: \u0003\"על המחיה ועל הכלכלה ועל תנובת השדה\"\u0004 וכו'. \u0003וחותם\u0004 (מסיים) את הברכה במילים \u0003\"על הארץ ועל המחיה\".\u0004","ואולם נשאלה השאלה: \u0003מיחתם במאי חתים\u0004 \u0005[לחתום במה\u0006 הוא \u0005חותם],\u0006 מהו נוסח חתימתה של ברכה זו? שכן השאלה היא באיזה פרט יש לחתום, שאין חותמים אלא בנושא אחד של ברכה! \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר:\u0004 כי \u0003רב חתים\u0004 \u0005[\u0006היה נוהג \u0005לחתום]\u0006 \u0003בראש חדש \"ברוך מקדש ישראל וראשי חדשים\",\u0004 הרי שיש בכל זאת אפשרות לחתום בשני עניינים הצמודים זה לזה בנוסחם, ואם כן \u0003הכא מאי\u0004 \u0005[כאן מה],\u0006 יברך?","ובכך נחלקו הדעות: \u0003רב חסדא אמר\u0004 שיש לחתום \u0003\"על הארץ ועל פירותיה\". ור' יוחנן אמר: \"על הארץ ועל הפירות\". אמר רב עמרם: ולא פליגי\u0004 \u0005[ואינם חלוקים],\u0006 אלא \u0003הא\u0004 \u0005[זו]\u0006 ששנינו שמברך \"על הארץ ועל פירותיה\" הרי זה \u0003לן\u0004 \u0005[לנו],\u0006 לבני בבל, \u0003והא\u0004 \u0005[וזו]\u0006 ששנינו שמברך \"על הארץ ועל הפירות\", הרי זה \u0003להו\u0004 \u0005[להם]\u0006 לבני ארץ ישראל.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב נחמן בר יצחק: אינהו אכלי, ואנן מברכין\u0004 \u0005[הם,\u0006 בני ארץ ישראל, \u0005אוכלים, ואנחנו\u0006 בני בבל \u0005מברכים]?!\u0006 כלומר, כיצד יכולים אנו, בני בבל, לברך על פירותיה של ארץ ישראל כשאנו אוכלים פירות בבל? \u0003אלא איפוך\u0004 \u0005[הפוך],\u0006 ואמור כך: \u0003רב חסדא אמר\u0004 שמברך \u0003\"על הארץ ועל הפירות\",\u0004 ו\u0003ר' יוחנן אמר\u0004 שמברך \u0003\"על הארץ ועל פירותיה\".\u0004"],["\u0003אמר רב יצחק בר אבדימי משום\u0004 (בשם) \u0003רבינו\u0004 (רב): \u0003על הביעא\u0004 \u0005[ביצה]\u0006 \u0003ועל מיני קופרא\u0004 \u0005[בשר]\u0006 \u0003בתחלה מברך \"שהכל\" ולבסוף \"בורא נפשות רבות\" וכו'. אבל\u0004 אחר אכילת \u0003ירקא\u0004 \u0005[ירק]\u0006 \u0003לא\u0004 יברך כלל. \u0003ו\u0004אילו \u0003ר' יצחק אמר: אפילו\u0004 אחר אכילת \u0003ירקא\u0004 \u0005[ירק]\u0006 יש לברך, \u0003אבל\u0004 אחר שתיית \u0003מיא\u0004 \u0005[מים]\u0006 — \u0003לא\u0004 יברך. \u0003ורב פפא אמר: אפילו\u0004 אחר שתיית \u0003מיא\u0004 \u0005[מים]\u0006 יש לברך.","ומסופר, כי \u0003מר זוטרא עביד\u0004 \u0005[עשה]\u0006 בענין זה \u0003כרב יצחק בר אבדימי\u0004 ולא ברך לאחר אכילת ירק, \u0003ו\u0004אילו \u0003רב שימי בר אשי עביד\u0004 \u0005[עשה]\u0006 בענין זה \u0003כר' יצחק\u0004 וכן ברך אחר אכילת ירק. \u0003וסימנך\u0004 לזכור איזה חכם נהג כאיזה חכם, הוא: \u0003חד כתרי, ותרי כחד\u0004 \u0005[אחד כשנים, ושנים כאחד],\u0006 כלומר, מר זוטרא (שמזכירים רק ביחס אליו רק שם אחד, שלו ולא של אביו) נהג כר' יצחק בר אבדימי (שמזכירים ביחס אליו שני שמות, שלו ושל אביו), ורב שימי בר אשי, הנזכר בשני שמות, נהג כר' יצחק, הנזכר בשם אחד.","ובענין זה \u0003אמר רב אשי: אנא, זמנא דכי מדכרנא, עבידנא ככולהו\u0004 \u0005[אני, בזמן שאני זוכר, אני עושה ככולם]\u0006 ומברך ברכה אחרונה אף על המים.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל\u0004 דבר \u0003שטעון ברכה לאחריו\u0004 — \u0003טעון ברכה לפניו, ו\u0004אולם \u0003יש שטעון ברכה לפניו, ואין טעון ברכה לאחריו.\u0004 ואם כן, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003רב יצחק בר אבדימי,\u0004 הרי מה שאמרו שיש דבר הטעון ברכה לפניו ולא לאחריו, הרי זה ללמד שיש \u0003לאפוקי ירקא\u0004 \u0005[להוציא\u0006 את \u0005הירק]\u0006 מכלל ברכה לאחריו, שהרי לדעתו אין מברכים אחרי אכילת ירק. וכמו כן אף \u0003ל\u0004דעת \u0003ר' יצחק\u0004 נוחה המשנה, שכן יש לומר שבאה \u0003לאפוקי מיא\u0004 \u0005[להוציא מים]\u0006 מכלל ברכה לאחרי שתייתם, \u0003אלא לרב פפא, לאפוקי מאי\u0004 \u0005[להוציא מה]\u0006 באה ההלכה, שיש דבר שמברכים לפניו ואין מברכים לאחריו?","ועונים: \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מצות,\u0004 שהרי מברכים על עשיית המצוות לפני עשייתן ולא אחר כך.","על כך מקשים: \u0003ולבני מערבא, דבתר דמסלקי תפילייהו מברכי\u0004 \u0005[ולבני ארץ ישראל, שלאחר שחולצים תפיליהם מברכים]\u0006 \u0003\"אשר קדשנו במצותיו וצונו לשמור חקיו\", לאפוקי מאי\u0004 \u0005[להוציא\u0006 את \u0005מה]\u0006 באה ההלכה שבמשנה?","ומשיבים: \u0003לאפוקי ריחני\u0004 \u0005[להוציא\u0006 מיני \u0005ריח],\u0006 שלדעת הכל אין מברכים לאחריהם.","ומאחר שהוזכרה כאן ברכת הביצה מביאים את מה ש\u0003אמר ר' ינאי אמר רבי: כל שהוא כ\u0004שיעור \u0003ביצה\u0004 — \u0003ביצה טובה ממנו,\u0004 כלומר, הביצה היא הטובה במאכלים. ומעין זה \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003ר' ינאי\u0004 מארץ ישראל לבבל \u0003אמר: טבא ביעתא מגולגלתא משיתא קייסי סולתא\u0004 \u0005[טובה ביצה מגולגלת,\u0006 ביצה מבושלת מעט, \u0005מששה לוגים של סולת].\u0006 ומעין זה \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: טבא ביעתא מגולגלתא משיתא\u0004 \u0005[טובה ביצה מגולגלת משש]\u0006 מידות סולת, \u0003מטויתא\u0004 \u0005[צלויה]\u0006 טובה \u0003מארבע,\u0004 ועל \u0003מבושלתא\u0004 \u0005[מבושלת]\u0006 אמרו ש\u0003כל שהוא כביצה, ביצה טובה הימנו, לבר מבשרא\u0004 \u0005[חוץ מבשר].\u0006","שנינו במשנה ש\u0003ר' עקיבא אומר\u0004 ש\u0003אפילו\u0004 אם \u0003אכל שלק\u0004 \u0005[ירקות מבושלים]\u0006 והוא מזונו — מברך עליו ברכת המזון כעל לחם. ושואלים: \u0003ומי איכא מידי דהוה שלק מזוני\u0004 \u0005[והאם יש דבר שהשלק\u0006 שלו \u0005הוא מזון]?\u0006 \u0003אמר רב אשי: בקלח של כרוב שנו\u0004 כאן, שהוא מזין.","ומעין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא העוסקת במיני מזונות: בשר ה\u0003טחול יפה\u0004 ומועיל לשיניים, \u0003ו\u0004אולם הוא \u0003קשה\u0004 ומזיק \u0003לבני\u0004 ה\u0003מעים.\u0004 ואילו ה\u0003כרישין קשין לשינים ו\u0004אולם \u0003יפין לבני מעים.\u0004 ועוד אמרו ש\u0003כל ירק חי מוריק\u0004 את הפנים. \u0003ו\u0004בכלל: \u0003כל\u0004 ירק \u0003קטן\u0004 (שעדיין לא הגיע למלוא גידולו) \u0003מקטין\u0004 ומזיק, \u0003וכל נפש,\u0004 יצור שלם, כמו דג שלם במלוא גידולו \u0003משיב את הנפש. וכל קרוב לנפש משיב את הנפש.\u0004 ולענייננו: \u0003כרוב\u0004 יכול לשמש \u0003למזון, ותרדין לרפואה.\u0004 ולענין הלפת — \u0003אוי לו לבית שהלפת עוברת בתוכו,\u0004 לפי שהיא מזיקה ביותר.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003טחול יפה לשינים וקשה לבני מעים.\u0004 ושואלים: \u0003מאי תקנתיה?\u0004 \u0005[מה תקנתו],\u0006 מה יעשה בו? ומשיבים: \u0003נלעסיה ונשדייה\u0004 \u0005[ילעסנו ויזרקנו].\u0006","ועל מה ששנינו בברייתא שה\u0003כרישין קשין לשינים ויפין לבני מעים\u0004 שואלים: \u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]?\u0006 ומשיבים: \u0003לשלקינהו ונבלעינהו\u0004 \u0005[ישלקם ויבלעם],\u0006 בלי ללעוס.","ועל מה ששנינו ש\u0003כל ירק חי מוריק, אמר ר' יצחק:\u0004 מדובר כאן \u0003בסעודה ראשונה של אחר הקזה (הקזת דם), שאז זקוק האדם למאכל משביע יותר.\u0004","\u0003ו\u0004עוד \u0003אמר ר' יצחק: כל האוכל ירק קודם ארבע שעות\u0004 ביום \u0003אסור לספר הימנו\u0004 (לדבר אתו). ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ומפרשים: \u0003משום ריחא\u0004 \u0005[הריח],\u0006 שריח הירק שמפיו מפריע לאחרים, שעדיין לא אכלו. \u0003ו\u0004בכלל \u0003אמר ר' יצחק: אסור לאדם שיאכל ירק חי קודם ארבע שעות.\u0004","ומסופר כי \u0003אמימר ומר זוטרא ורב אשי הוו יתבי\u0004 \u0005[היו יושבים],\u0006 \u0003אייתו קמייהו\u0004 \u0005[הביאו לפניהם]\u0006 \u0003ירק חי קודם ארבע שעות. אמימר ורב אשי אכול\u0004 \u0005[אכלו]\u0006 \u0003ו\u0004אילו \u0003מר זוטרא לא אכל. אמרו ליה:\u0004 \u0005[לו]\u0006 \u0003מאי דעתיך\u0004 \u0005[מהי דעתך]\u0006 בענין זה, משום מה אינך אוכל? שאם אתה חושש למה ש\u0003אמר ר' יצחק\u0004 ש\u0003כל האוכל ירק קודם ארבע שעות אסור לספר הימנו משום ריחא\u0004 \u0005[הריח]?\u0006 \u0003והא אנן דקא אכילנא וקא משתעית בהדן\u0004 \u0005[והרי אנחנו אוכלים ואתה משוחח אתנו]!\u0006","השיב להם: \u0003אנא כאידך\u0004 \u0005[אני\u0006 כאימרה \u0005אחרת]\u0006 של \u0003ר' יצחק סבירא לי\u0004 \u0005[סבור אני]\u0006 \u0003אמר ר' יצחק: אסור לאדם שיאכל ירק קודם ארבע שעות\u0004 ולא עוד.","על מה שאמרו \u0003כל קטן מקטין, אמר רב חסדא:\u0004 הדבר שייך \u0003אפילו גדיא בר זוזא\u0004 \u0005[גדי בן,\u0006 השווה \u0005זוז],\u0006 שאף שהגדי הזה כבר גדל עד שערכו זוז עדיין קטן הוא. \u0003ו\u0004אולם \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 באופן \u0003דלית ביה ריבעא\u0004 \u0005[שאין בו רבע]\u0006 גידולו, \u0003אבל\u0004 אם \u0003אית ביה ריבעא\u0004 \u0005[יש בו\u0006 כבר \u0005רבע]\u0006 גודלו — \u0003לית לן בה\u0004 \u0005[אין לנו בו]\u0006 צד חשש.","ועל מה ששנינו בברייתא ש\u0003כל נפש משיב נפש אמר רב פפא:\u0004 זה כולל \u0003אפילו גילדני דבי גילי\u0004 \u0005[דגים קטנים הגדלים בין הקנים],\u0006 שאפילו יצור קטן ביותר מועיל אם כבר הגיע לגמר גידולו.","ועל מה ששנינו בברייתא ש\u0003כל הקרוב לנפש משיב את הנפש אמר רב אחא בר יעקב:\u0004 המדובר הוא ב\u0003עונקא\u0004 \u0005[צוואר]\u0006 הקרוב למרכזי החיים של הבהמה. וכן מסופר ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003כי מייתית\u0004 \u0005[כאשר אתה מביא]\u0006 \u0003לי אומצא דבשרא\u0004 \u0005[אמוצת בשר],\u0006 \u0003טרח ואייתי\u0004 \u0005[והבא]\u0006 \u0003לי מהיכא דמקרב לבי \"ברוך\"\u0004 \u0005[ממקום הקרוב לבית הברכה],\u0006 מקום השחיטה, שמברכים עליה.","עוד שנינו בברייתא ש\u0003כרוב\u0004 טוב \u0003למזון ותרדין לרפואה.\u0004 ושואלים: והאם \u0003כרוב למזון אין\u0004 \u0005[כן]\u0006 יפה, \u0003ו\u0004אולם \u0003לרפואה לא? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ששה דברים מרפאין את החולה מחליו ורפואתן רפואה, ואלו הן: כרוב ותרדין ומי סיסין דבש וקיבה והרת ויותרת הכבד!\u0004 והרי שהכרוב אף יפה לרפואה! ומשיבים: יש לומר \u0003\"כרוב אף למזון\"\u0004 וכל שכן לרפואה, מה שאין כן בתרד.","עוד שנינו בברייתא ש\u0003אוי לו לבית שהלפת עוברת בתוכו\u0004 לפי שהלפת מזיקה ביותר, ועל כך מקשים: \u0003איני\u0004 \u0005[וכן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003כי חזית ליפתא בשוקא\u0004 \u0005[כאשר רואה אתה לפת בשוק]\u0006 \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 \u0003לי \"במאי כרכת ריפתא\"\u0004 \u0005[במה אוכל אני היום את הלחם],\u0006 אלא קנה והבא את הלפת לסעודה. הרי שהלפת היא מאכל ראוי וחשוב!","\u0003אמר אביי:\u0004 מה שאמרו בגנותה של הלפת, הרי זה דווקא כשאוכלים אותה \u0003מבלי בשר. ורבא אמר: מבלי יין. איתמר\u0004 \u0005[נאמר]\u0006 ש\u0003רב אמר\u0004 שהלפת מזיקה כשהיא נאכלת \u0003מבלי בשר. ושמואל אמר: מבלי עצים,\u0004 כלומר, כאשר אינה מבושלת כראוי. \u0003ור' יוחנן אמר: מבלי יין.\u0004","ומעין זה מסופר, ש\u0003אמר ליה רבא לרב פפא: סודני, אנן תברינן לה בבשרא וחמרא, אתון דלא נפיש לכו חמרא במאי תבריתו לה\u0004 \u0005[חקלאי,\u0006 (גאונים) \u0005אנחנו שוברים אותה,\u0006 את נזקה של הלפת, \u0005בבשר ויין, אתם שאין היין מרובה לכם במה אתם שוברים אותה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא: \u0003בציבי\u0004 \u0005[בעצים]\u0006 \u0003כי הא דביתהו\u0004 \u0005[כמו זה שאשתו]\u0006 של \u0003רב פפא בתר דמבשלא לה תברא לה בתמנן אופי פרסייתא\u0004 \u0005[אחרי שהיתה מבשלת אותה,\u0006 את הלפת, \u0005היתה שוברת אותה בשמונים חתיכות עץ דקל].\u0006","ובקשר לדיון בענייני המאכלים מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003דג קטן מליח\u0004 \u0005[מלוח]\u0006 \u0003פעמים שהוא ממית,\u0004 והוא \u0003בשבעה\u0004 ימים לאחר שנמלח, \u0003בשבעה עשר, ובעשרים ושבעה. ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003בעשרים ושלושה. ולא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא במטוי ולא מטוי\u0004 \u0005[בצלוי ואינו צלוי],\u0006 \u0003אבל\u0004 כאשר הוא \u0003מטוי שפיר\u0004 \u0005[צלוי יפה\u0006 היטב\u0005]\u0006 \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 כל חשש. \u0003ודלא מטוי שפיר\u0004 \u0005[ושאינו צלוי היטב],\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא\u0004 כש\u0003לא שתה בתריה שכרא\u0004 \u0005[אחריו שיכר],\u0006 \u0003אבל\u0004 כאשר \u0003שתה בתריה שכרא\u0004 \u0005[אחריו שיכר]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש.","שנינו במשנה שנחלקו התנאים בדבר \u0003השותה מים לצמאו,\u0004 ושואלים: הדגשה זו \"לצמאו\" \u0003לאפוקי מאי\u0004 \u0005[להוציא\u0006 את \u0005מה]\u0006 ומה באה היא להדגיש? \u0003אמר רב אידי בר אבין: לאפוקי למאן\u0004 \u0005[להוציא את מי]\u0006"],["\u0003דחנקתיה אומצא\u0004 \u0005[שחנקה אותו אומצת בשר]\u0006 ושתה מים לזרז הבליעה שאז אינו צריך לברך.","שנינו במשנה ש\u0003ר' טרפון אומר\u0004 שיש לברך על המים \u0003\"בורא נפשות רבות וחסרונן\". אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר רב חנן לאביי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003לרב יוסף: הלכתא מאי\u0004 \u0005[מה ההלכה],\u0006 במחלוקת זו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פוק חזי מאי עמא דבר\u0004 \u0005[צא וראה מה נוהג העם],\u0006 וכך תעשה.","\u0003הדרן עלך כיצד מברכין\u0004","במשנה זו נקבעים עיקרי ההלכות השייכות לזימון. \u0003שלשה\u0004 אנשים \u0003שאכלו כאחת\u0004 (יחד), הריהם \u0003חייבין\u0004 מעתה \u0003לזמן,\u0004 לאמר, להשתתף בברכת המזון משותפת. ואף אם יש בין האוכלים מי ש\u0003אכל דמאי\u0004 (דבר מאכל שאין זה ברור אם הוא מעושר), \u0003ו\u0004כן אם אכל דבר מאכל שהינו \u0003מעשר ראשון שנטלה\u0004 כבר \u0003תרומתו.\u0004 וכן אם אכל \u0003מעשר שני, ו\u0004כן \u0003הקדש שנפדו,\u0004 ומותרים הם מעתה לאכילה. \u0003ו\u0004אף \u0003השמש\u0004 (המלצר) המגיש את האוכל למסובים \u0003שאכל\u0004 לפחות \u0003כ\u0004שיעור \u0003זית\u0004 מן הסעודה, \u0003ו\u0004כן \u0003הכותי\u0004 (שומרוני) שאכל עם שניים נוספים בסעודה אחת — \u0003מזמנין עליו,\u0004 על כל אחד מאלה, שמצטרפים הם לחייב בזימון את האוכלים אתם.","אך אם \u0003אכל טבל\u0004 (תבואה שלא הופרש ממנה מעשר), \u0003ו\u0004כן מי שאכל \u0003מעשר ראשון שלא נטלה\u0004 ממנו \u0003תרומתו, ו\u0004כן מי שאכל \u0003מעשר שני והקדש שלא נפדו, ו\u0004כן \u0003השמש שאכל פחות מכזית, ו\u0004כן \u0003הגוי\u0004 שסעד עם שניים מישראל — \u0003אין מזמנין עליו.\u0004 ועוד מהלכות צירוף לחיוב זימון: \u0003נשים ועבדים וקטנים\u0004 — \u0003אין מזמנין עליהן.\u0004 לענין שיעור האכילה \u0003עד כמה\u0004 קטן הוא, ועדיין \u0003מזמנין\u0004 (מתחייבים עליו בזימון)? — נחלקו הדעות: \u0003עד כזית,\u0004 שדי בכך כדי לחייבו. \u0003ר' יהודה אומר: עד כביצה,\u0004 שהוא שיעור האכילה הקטן ביותר המחייב בזימון.","שנינו במשנתנו מהלכות הזימון, ועל עצם מצוות הזימון שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 מנין אנו יודעים שיש לזמן לאחר הסעודה, ובשלושה אוכלים? \u0003אמר רב אסי,\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"גדלו לה' אתי ונרוממה שמו יחדו\"\u0004 (תהלים לד, ד), כלומר, שהמברך פונה לפחות לשנים אחרים להלל יחד את שם ה'. \u0003ר' אבהו אמר: מהכא\u0004 \u0005[מכאן]\u0006 ממקרא זה יש להביא מקור למצוות הזימון, שכן נאמר: \u0003\"כי שם ה' אקרא הבו גדל לאלהינו\"\u0004 (דברים לב, ג). עם הזכרתם של פסוקים אלה מביאים דברים שנאמרו בקשר להם.","\u0003אמר רב חנן בר אבא: מנין\u0004 מקור במקרא \u0003לעונה \"אמן\"\u0004 אחר ברכת חבירו \u0003שלא יגביה קולו\u0004 בעניית ה\"אמן\" \u0003יותר מן המברך\u0004 — ממה \u0003שנאמר: \"גדלו לה' אתי ונרוממה שמו יחדו\",\u0004 ולא שירים העונה קולו יותר מן המברך, ולא יהיו עוד שניהם יחדיו.","מעין זה \u0003אמר ר' שמעון בן פזי: מנין שאין המתרגם\u0004 שהיה מתרגם לארמית את הדברים שקראו בתורה בציבור \u0003רשאי להגביה קולו יותר מן הקורא\u0004 בתורה, \u0003ש\u0004כן \u0003נאמר: \"משה ידבר והאלהים יעננו בקול\"\u0004 (שמות יט, יט), ויש לדון בכתוב זה, \u0003ש\u0004הרי \u0003אין תלמוד לומר \"בקול\",\u0004 כלומר, שהמלה \"בקול\" אינה מגלה באיזה קול, \u0003ומה תלמוד לומר \"בקול\"\u0004 — \u0003בקולו של משה,\u0004 כלומר, בקול שאינו גבוה יותר. והרי זו הוראה לדורות הבאים, ובדומה לקדוש ברוך הוא האומר את הדברים, ומשה משמש כמתורגמן, היו קולותיהם שווים בגובהם, כן ינהגו הקוראים בתורה והמתרגמים שיהיו קולותיהם שווים.","ומעין זה \u0003תניא נמי הכי\u0004 \u0005[שנינו\u0006 בברייתא \u0005גם כן כך]:\u0006 \u0003אין המתרגם רשאי להגביה קולו יותר מן הקורא. ו\u0004לחילופין, אף הקורא \u0003אם\u0004 רואה ש\u0003אי אפשר למתרגם להגביה קולו כנגד הקורא\u0004 — צריך ש\u0003ימעך\u0004 (ינמיך) \u0003הקורא קולו ויקרא.\u0004","במשנה נפסק כי שלושה שאכלו יחד חייבים לזמן. ודנים עוד בהלכה זו, \u0003אתמר\u0004 \u0005[נאמר]:\u0006 \u0003שנים שאכלו כאחת,\u0004 ואף שאין הם חייבים בזימון, הריהם רוצים בכך, האם רשאים הם לעשות כן. \u0003פליגי\u0004 \u0005[נחלקו]\u0006 בשאלה זו \u0003רב ור' יוחנן. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: אם רצו לזמן\u0004 — \u0003מזמנין, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 אף \u0003אם רצו לזמן\u0004 — \u0003אין מזמנין.\u0004","ושואלים: \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנתנו: \u0003שלשה שאכלו כאחת חייבין לזמן.\u0004 ויש מכאן מקום לדקדק: \u0003שלשה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מזמנים, ואילו \u0003שנים\u0004 — \u0003לא\u0004 מזמנים! והרי זו ראיה שלא כדעת הסובר ששנים הרוצים לזמן, רשאים לעשות כן.","ומשיבים: אין להביא ממשנתנו ראיה, כי \u0003התם\u0004 \u0005[שם],\u0006 במשנתנו\u0005, מדובר בזימון שהוא\u0006 \u0003חובה,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן],\u0006 במחלוקת זו של חכמים \u0005מדובר בזימון שהוא\u0006 \u0003רשות,\u0004 משום שהאוכלים רוצים בכך.","ואומרים עוד, \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה אחרת בעניין זה, ממה ששנינו: \u0003שלשה שאכלו כאחת\u0004 — \u0003חייבין לזמן, ואין רשאין ליחלק\u0004 ולברך בנפרד. מכאן יש לדקדק: \u0003שלשה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מזמנים, ואילו \u0003שנים\u0004 — \u0003לא\u0004 מזמנים! והרי זו ראיה שרק בשלושה שייך זימון, אבל בשנים — לא. שאם לא כן, גם אם נחלקה חבורת השלושה ונשארו שנים, עדיין יוכלו לזמן.","הוכחה זו דוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 משום ש\u0003קבעו להו\u0004 \u0005[להם]\u0006 את הדבר כ\u0003חובה מעיקרא\u0004 \u0005[מתחילה],\u0006 ואינם רשאים עתה להיחלק, ושיהא הזימון לגביהם רשות ולא חובה.","ועוד מביאים ראיה, \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003השמש שהיה משמש על השנים\u0004 — \u0003הרי זה אוכל עמהם, אף על פי שלא נתנו לו\u0004 במפורש \u0003רשות\u0004 לאכול אתם, שהרי נוח להם הדבר, שכן בכך יוכל להצטרף אתם לזימון. ואם \u0003היה משמש על השלשה\u0004 — \u0003הרי זה אינו אוכל עמהם, אלא אם כן נתנו לו רשות\u0004 מפורשת. הרי ששנים אינם יכולים לזמן לעצמם!","משיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006"],["\u0003דניחא להו דמקבע להו\u0004 \u0005[שנוח להם שיקבע להם]\u0006 הדבר כ\u0003חובה מעיקרא\u0004 \u0005[מתחילה],\u0006 ולא רשות בלבד, כשהם שנים.","ומביאים ראיה אחרת לדבר, \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 מה ששנינו: \u0003נשים מזמנות לעצמן, ועבדים מזמנים לעצמן,\u0004 ואולם \u0003נשים ועבדים וקטנים אם רצו לזמן\u0004 — \u0003אין מזמנין. והא\u0004 \u0005[והרי]\u0006 \u0003מאה נשי\u0004 \u0005[נשים]\u0006 הריהן \u0003כתרי גברי דמיין\u0004 \u0005[כשני גברים\u0006 הן \u0005נחשבות],\u0006 שאין מספרן מצרפן להיות חלק ממנין בתפילה, \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנינו]\u0006 ש\u0003נשים מזמנות לעצמן ועבדים מזמנין לעצמן\u0004, ואם כן אפשר להסיק שגם שני גברים יוכלו לזמן לעצמם!","ודוחים: \u0003שאני התם דאיכא\u0004 \u0005[שונה שם שיש]\u0006 \u0003דעות,\u0004 כלומר, אף שאין הנשים מצטרפות למנין של תפילה, בכל זאת מאחר שיש כאן שלוש דעות, כלומר, שלוש אישויות נפרדות לכן נחשבות כאן שלוש נשים יותר משני גברים.","על כך מקשים: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כן, אמור\u0006 את \u0005הסוף]\u0006 ששנינו בו: \u0003נשים ועבדים אם רצו לזמן\u0004 — \u0003אין מזמנין,\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יזמנו, \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003דעות!\u0004 שהרי גם שם יש לפחות שלושה אישויות נפרדות.","ומשיבים, כי מטעם זה אכן לא היה מקום לאסור זימון נשים ועבדים, \u0003ושאני התם\u0004 \u0005[ושונה שם]\u0006 שנאסר הדבר \u0003משום פריצותא\u0004 \u0005[פריצות],\u0006 שחששו לצרף הנשים ועבדים.","במחלוקת זו לא היה ברור מיהו החכם שאמר כל אחת מן הדעות, ומנסים לברר זאת ולומר: \u0003תסתיים\u0004 \u0005[תוברר,\u0006 יוגדר שם האומר\u0005],\u0006 ש\u0003רב\u0004 הוא זה ש\u0003אמר\u0004 ש\u0003אם\u0004 שנים \u0003רצו לזמן\u0004 — \u0003אין\u0004 הם \u0003מזמנין.\u0004 שכן \u0003אמר רב דימי בר יוסף\u0004 שכך \u0003אמר רב: שלשה שאכלו כאחת ויצא אחד מהם לשוק\u0004 — \u0003קוראין לו ומזמנין עליו. טעמא\u0004 \u0005[טעם,\u0006 הדבר דווקא] ש\u0003קוראין לו, הא\u0004 \u0005[הרי ]\u0006 מכאן שאם \u0003לא קוראין לו\u0004 — \u0003לא\u0004 מזמנים! ומכאן ששנים אינם יכולים לזמן.","הוכחה זו נדחית: \u0003שאני התם דאיקבעו להו\u0004 \u0005[שונה שם שנקבעו להם]\u0006 כבר \u0003בחובה מעיקרא\u0004 \u0005[מתחילה],\u0006 ולכן אם קראו לו, מזמנים עליו. אבל אם לא קראו לו, אין מזמנים עליו כלל, שכן זימון בשנים אינו אלא רשות.","ומעתה מנסים להוכיח להיפך, \u0003אלא תסתיים\u0004 \u0005[תוברר,\u0006 יוגדר שם האומר\u0005],\u0006 ש\u0003ר' יוחנן הוא\u0004 זה ש\u0003אמר אם רצו לזמן\u0004 — \u0003אין מזמנין,\u0004 שכן \u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: שנים שאכלו כאחת\u0004 — \u0003אחד מהן יוצא בברכת חבירו. ו\u0004על כך","\u0003הווינן\u0004 \u0005[עסקנו]\u0006 \u0003בה,\u0004 בררנו את ההלכה הזו: \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו]\u0006 בכך, והרי \u0003תנינא\u0004 \u0005[שנינו\u0006 כבר\u0005]\u0006 הלכה זו במפורש: \u0003שמע\u0004 ברכה \u0003ו\u0004אף ש\u0003לא ענה\u0004 — \u0003יצא\u0004 ידי חובה! \u0003ואמר ר' זירא\u0004 בהסבירו את דברי ר' יוחנן שפסקו בא \u0003לומר שאין ברכת הזימון ביניהם.\u0004 ואם כן \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 שר' יוחנן הוא שסבר כי שנים אינם מזמנים.","על כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר רב הונא לרב הונא\u0004 אביו בשאלה: \u0003והא רבנן דאתו ממערבא אמרי\u0004 \u0005[הרי חכמים שבאו מארץ ישראל אומרים]\u0006 שבשנים, \u0003אם רצו לזמן\u0004 — \u0003מזמנין, מאי לאו דשמיע להו\u0004 \u0005[האם לא ששמעו הם]\u0006 את ההלכה הזו \u0003מר' יוחנן\u0004 שמארץ ישראל הוא? על כך ענה לו אביו: \u0003לא,\u0004 אין זו ראיה, שיתכן \u0003דשמיע להו\u0004 \u0005[ששמעו הם]\u0006 את ההלכה הזו \u0003מרב, מקמי דנחית\u0004 \u0005[לפני שירד]\u0006 \u0003לבבל.\u0004","את דברי רב שהוזכרו קודם מבררים עתה ל\u0003גופא\u0004 \u0005[גוף]\u0006 עניינם. \u0003אמר רב דימי בר יוסף אמר רב: שלשה שאכלו כאחת, ויצא אחד מהם לשוק\u0004 — \u0003קוראין לו\u0004 השנים, \u0003ומזמנין עליו\u0004 אפילו אם אינו לידם. ועל כך הוסיף ו\u0003אמר אביי: והוא דקרו ליה ועני\u0004 \u0005[שקוראים לו ועונה],\u0006 אבל אם היה רחוק מדי — אין לצרפו.","ו\u0003אמר מר זוטרא: ולא אמרן\u0004 \u0005[אמרנו]\u0006 שדי במה שהוא שומע ויכול לענות, \u0003אלא\u0004 כשהם \u0003שלשה, אבל\u0004 כשהם \u0003עשרה\u0004 אין מזמנים \u0003עד דנייתי\u0004 \u0005[שיבוא]\u0006 האיש שהלך וישב עמם.","\u0003מתקיף\u0004 \u0005[הקשה]\u0006 \u0003לה רב אשי\u0004 על כך: \u0003אדרבא איפכא מסתברא\u0004 \u0005[ההיפך מסתבר יותר]\u0006 כי \u0003תשעה נראין כעשרה\u0004 וגם אם חסר אחד — המנין אינו נראה פגום, ואילו \u0003שנים אין נראים כשלושה\u0004 והיה ראוי שדווקא בשנים יצטרכו לחכות שיבוא השלישי וישלים.","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כמר זוטרא. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003כיון דבעי לאדכורי\u0004 \u0005[שצריך להזכיר]\u0006 \u0003שם שמים\u0004 — \u0003בציר\u0004 \u0005[פחות]\u0006 \u0003מעשרה לאו אורח ארעא\u0004 \u0005[איננו דרך ארץ],\u0006 ומאחר שמזמנים בעשרה בהזכרת ה' יש לדאוג לכך שכל העשרה יהיו מצויים במקום.","בהלכות זימון \u0003אמר אביי: נקיטינן\u0004 \u0005[מוחזקים אנו,\u0006 בכלל זה\u0005]\u0006 \u0003שנים שאכלו כאחת\u0004 — \u0003מצוה ליחלק\u0004 ושכל אחד מהם יברך לעצמו. ואכן \u0003תניא נמי הכי\u0004 \u0005[שנויה גם כן כך\u0006 בברייתא\u0005]:\u0006 \u0003שנים שאכלו כאחת\u0004 — \u0003מצוה ליחלק,\u0004 ואולם בברייתא מוסיפים: \u0003במה דברים אמורים,\u0004 שדין זה הוא דווקא \u0003כששניהם סופרים,\u0004 כלומר, יודעים לברך ולהתפלל, \u0003אבל\u0004 אם היה \u0003אחד\u0004 מהם \u0003סופר ואחד בור\u0004 — \u0003סופר מברך, ובור יוצא\u0004 ידי חובתו בברכת הסופר.","\u0003אמר רבא: הא מילתא אמריתא אנא, ואיתמרה משמיה\u0004 \u0005[דבר זה אמרתיו אני ונאמר משמו]\u0006 של \u0003ר' זירא כוותי\u0004 \u0005[כמותי]:\u0006 \u0003שלשה שאכלו כאחת\u0004 ולא סיימו סעודתם בבת אחת, דרך ארץ היא כי \u0003אחד מפסיק\u0004 מסעודתו כדי לאפשר \u0003לשנים\u0004 לזמן, \u0003ואין\u0004 ה\u0003שנים מפסיקין לאחד.\u0004","על כך מקשים: \u0003ולא,\u0004 וכי אין השנים מפסיקים לאחד? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב פפא אפסיק ליה\u0004 \u0005[הפסיק לו]\u0006 \u0003לאבא מר בריה איהו וחד\u0004 \u0005[בנו, הוא ו\u0006עוד \u0005אחד]!\u0006 ועונים: \u0003שאני\u0004 \u0005[שונה]\u0006 הוא רב פפא, שדבר זה שעשה, \u0003לפנים משורת הדין הוא דעבד\u0004 \u0005[שעשה],\u0006 זאת, ולא כחובה.","מסופר כי שלושת החכמים, \u0003יהודה בר מרימר ומר בר רב אשי ורב אחא מדיפתי כרכי ריפתא בהדי הדדי\u0004 \u0005[אכלו לחם יחד],\u0006 \u0003לא הוה בהו חד דהוה\u0004 \u0005[היה בהם אחד שהיה]\u0006 \u0003מופלג מחבריה\u0004 \u0005[מחבריו]\u0006 בחכמה או בזקנה \u0003לברוכי להו\u0004 \u0005[לברך להם].\u0006 \u0003יתבי וקא מיבעיא להו\u0004 \u0005[ישבו\u0006 לדון בדבר, \u0005והיתה קשה להם\u0006 שאלה זו\u0005] :\u0006 \u0003הא דתנן\u0004 \u0005[זה ששנינו\u0006 במשנתנו\u0005]\u0006 כי \u0003שלשה שאכלו כאחת חייבין לזמן,\u0004 האם \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 אמורים דווקא \u0003היכא\u0004 \u0005[היכן,\u0006 כאשר\u0005]\u0006 \u0003דאיכא\u0004 \u0005[שיש]\u0006 שם \u0003אדם גדול\u0004 ביניהם, \u0003אבל היכא דכי הדדי נינהו\u0004 \u0005[היכן ששווים הם]\u0006 — \u0003חלוק ברכות\u0004 שכל אחד מברך לעצמו \u0003עדיף.\u0004","ואכן כך נהגו, \u0003בריך איניש לנפשיה\u0004 \u0005[ברך\u0006 כל \u0005אדם לעצמו].\u0006 אחר כך כאשר \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003מרימר\u0004 לשאול אם יפה עשו. \u0003אמר להו\u0004 \u0005[להם]:\u0006 אמנם \u0003ידי ברכה\u0004 על המזון \u0003יצאתם,\u0004 אך \u0003ידי זימון לא יצאתם. וכי תימרו: נהדר ונזמן\u0004 \u0005[ואם תאמרו: נחזור ונזמן],\u0006 הרי \u0003אין זימון למפרע\u0004 שאין לזמן על סעודה שכבר ברכו עליה.","דנים בבעיה אחרת מה אומר אדם ש\u0003בא ומצאן\u0004 לחבורת אנשים \u0003כשהן מברכים, מהו אומר אחריהם? רב זביד אמר:\u0004 אומר \u0003\"ברוך ומבורך\". רב פפא אמר: עונה \"אמן\".\u0004","ומסבירים את השיטות: \u0003ולא פליגי\u0004 \u0005[חולקים]\u0006 הם בדבר, כי, \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דאשכחינהו דקא אמרי\u0004 \u0005[שמצאם שהם אומרים]\u0006 \u0003\"נברך\", והא\u0004 \u0005[וזה]\u0006 — \u0003דאשכחינהו דקא אמרי\u0004 \u0005[שמצאם שהם אומרים]\u0006 \u0003\"ברוך\".\u0004 ומפרטים: \u0003אשכחינהו דקא אמרי\u0004 \u0005[מצאם שהם אומרים]\u0006 \u0003\"נברך\"\u0004 — \u0003אומר \"ברוך ומבורך\", אשכחינהו דקא אמרי\u0004 \u0005[מצאם שהם אומרים]\u0006 \u0003\"ברוך\"\u0004 — \u0003עונה \"אמן\".\u0004","ומעין דרך הסבר זו מביאים בנושא קרוב, \u0003תני חדא\u0004 \u0005[שנויה\u0006 בברייתא \u0005אחת]:\u0006 \u0003העונה \"אמן\" אחר ברכותיו\u0004 שהוא עצמו אומר — \u0003הרי זה משובח. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003הרי זה מגונה.\u0004","ומתרצים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003ב\"בונה ירושלים\"\u0004 שנאה לו לומר \"אמן\" אחר ברכה זו. ו\u0003הא\u0004 \u0005[זה]\u0006 שאמרו שמגונה הדבר — \u0003בשאר ברכות.\u0004","מסופר כי \u0003אביי עני ליה בקלא, כי היכי דלישמעו\u0004 \u0005[היה עונה אותו,\u0006 את ה\"אמן\" אחר \"בונה ירושלים\", \u0005בקול, כדי שישמעו]\u0006 ה\u0003פועלים וליקומו\u0004 \u0005[ויעמדו]\u0006 לעבודתם, שכן ברכת \u0003\"הטוב והמטיב\"\u0004 שבאה אחר כך \u0003לאו דאורייתא\u0004 \u0005[אינה מן התורה],\u0006 והפועלים העובדים אצל בעל הבית יכולים לוותר עליה. ואילו \u0003רב אשי עני ליה בלחישא, כי היכי\u0004 \u0005[היה עונה אותו בלחישה, כדי]\u0006 ש\u0003לא נזלזלו\u0004 \u0005[יזלזלו]\u0006 \u0003ב\u0004ברכת \u0003\"הטוב והמטיב\".\u0004"],["מסופר: \u0003ר' זירא חלש\u0004 \u0005[חלה],\u0006 \u0003על לגביה\u0004 \u0005[נכנס אצלו]\u0006 \u0003ר' אבהו, קביל עליה\u0004 \u0005[קיבל עליו]\u0006 ר' אבהו ואמר: \u0003אי מתפח קטינא חריך שקי\u0004 \u0005[אם יבריא הגוץ חרוך השוקיים,\u0006 כינוי לר' זירא\u0005]\u0006 — \u0003עבידנא יומא טבא לרבנן\u0004 \u0005[עושה אני יום טוב,\u0006 סעודה, \u0005לחכמים].\u0006 \u0003אתפח, עבד סעודתא לכולהו רבנן\u0004 \u0005[הבריא\u0006 ר' זירא, ו\u0005עשה\u0006 ר' אבהו \u0005סעודה לכל החכמים].\u0006 \u0003כי מטא למשרי\u0004 \u0005[כאשר באה\u0006 העת \u0005לבצוע\u0006 את הפת בסעודה\u0005]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו \u0003לר' זירא: לישרי לן מר\u0004 \u0005[יבצע לנו אדוני]\u0006 את הפת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: \u0003לא סבר לה מר להא\u0004 \u0005[האם אין אדוני סבור\u0006 מקבל \u0005את\u0006 הלכה \u0005זו]\u0006 של \u0003ר' יוחנן\u0004 ש\u0003אמר: בעל הבית בוצע?\u0004 ואכן \u0003שרא להו\u0004 \u0005[בצע להם\u0006 לסועדים\u0005]\u0006 ר' אבהו.","\u0003כי מטא לברוכי\u0004 \u0005[כאשר באה\u0006 העת \u0005לברך]\u0006 ברכת המזון שלאחר הסעודה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו לר' זירא: \u0003נבריך לן מר\u0004 \u0005[יברך לנו אדוני]\u0006 את ברכת המזון. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: \u0003לא סבר לה מר להא\u0004 \u0005[האם אין אדוני סבור\u0006 מקבל \u0005את\u0006 הלכה \u0005זו]\u0006 של \u0003רב הונא\u0004 ש\u0003מן בבל\u0004 ש\u0003אמר:\u0004 ה\u0003בוצע מברך?\u0004","על כך שואלים: \u0003ואיהו\u0004 \u0005[והוא,\u0006 ר' אבהו\u0005]\u0006 שהציע לר' זירא לברך, אף שלא בצע על הפת, \u0003כמאן סבירא ליה\u0004 \u0005[כמי סבור הוא]?\u0006","ומשיבים: \u0003כי הא\u0004 \u0005[כמו\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחי: בעל הבית בוצע, ואורח מברך.\u0004 וטעם הדבר: \u0003בעל הבית\u0004 בוצע — \u0003כדי שיבצע בעין יפה,\u0004 ואילו האורח עשוי להתבייש לבצוע פרוסות גדולות לעצמו. \u0003ואורח מברך\u0004 — \u0003כדי שיברך\u0004 האורח את \u0003בעל הבית.\u0004","ומסבירים: \u0003מאי\u0004 \u0005[מה]\u0006 נוסח הברכה ש\u0003מברך\u0004 האורח את בעל הבית בתוך ברכת המזון — \u0003\"יהי רצון שלא יבוש בעל הבית בעולם הזה, ולא יכלם לעולם הבא\".\u0004","\u0003ורבי מוסיף בה\u0004 בברכה \u0003דברים\u0004 הנוגעים להצלחה בנכסיו: \u0003\"ויצלח מאד בכל נכסיו, ויהיו נכסיו ונכסינו מוצלחים וקרובים לעיר, ואל ישלוט שטן לא במעשי ידיו ולא במעשי ידינו, ואל יזדקר\u0004 (יופיע, יעמוד מנגד) \u0003לא לפניו ולא לפנינו שום דבר הרהור חטא ועבירה ועון מעתה ועד עולם\".\u0004","נשאלה השאלה \u0003עד היכן\u0004 היא \u0003ברכת הזמון\u0004 שבה דובר, ובכך נחלקו הדעות.","\u0003רב נחמן אמר שהברכה עד \"נברך\", ורב ששת אמר\u0004 שברכת הזימון נגמרת רק עם סוף הברכה הראשונה של ברכת המזון, לאמר \u0003עד \"הזן\".\u0004","ומציעים: מחלוקת זו שנחלקו בה אמוראים, \u0003נימא כתנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שהריהי \u0005כ\u0006מחלוקת שחלקו בה כבר \u0005תנאים],\u0006 \u0003דתני חדא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003ברכת המזון\u0004 היא \u0003שנים ושלשה\u0004 ברכות, \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 ברכת המזון \u0003שלשה וארבעה. סברוה\u0004 \u0005[סברו,\u0006 הניחו חכמים\u0005]\u0006 בהבנת שתי ברייתות אלו, כי \u0003דכולי עלמא\u0004 \u0005[\u0006לדעת \u0005הכל]\u0006 ברכת \u0003\"הטוב והמטיב\" לאו דאורייתא\u0004 \u0005[לא מן התורה]\u0006 \u0003היא,\u0004 ואם כן, \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה הם חלוקים]:\u0006 \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 בברייתא \u0003שתים ושלש קסבר\u0004 \u0005[סבור הוא]\u0006 שברכת הזימון היא \u0003עד \"הזן\",\u0004 כלומר, שאם מזמנים מברכים הם שלוש ברכות, ואם לאו — מברכים רק שתי ברכות, ואין אומרים את ברכת \"הזן\" השייכת לזימון. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003שלש וארבע קסבר\u0004 \u0005[סבור הוא]\u0006 שברכת הזימון היא \u0003עד \"נברך\",\u0004 כלומר, עד התחלת ברכת המזון, ולכן המזמנים יברכו ארבע ברכות, ובלא זימון — שלוש בלבד.","את ההסבר הזה להבדל שבין הברייתות דוחים שני האמוראים: \u0003לא\u0004 כך הוא, והסבר אחר יש להבדל שבין הברייתות, \u0003רב נחמן מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003ורב ששת מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ובאופן זה:","\u0003רב נחמן מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שלדעתו \u0003דכולי עלמא\u0004 \u0005[הכל\u0006 סבורים\u0005]\u0006 שברכת הזימון היא \u0003עד \"נברך\",\u0004 ואולם בזאת נחלקו הברייתות, \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003שלש וארבע\u0004 — \u0003שפיר\u0004 \u0005[יפה,\u0006 מתאים\u0005]\u0006 הדבר לשיטתו, \u0003ו\u0004אילו \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 בברייתא \u0003שתים ושלש\u0004 — \u0003אמר\u0004 \u0005[\u0006יכול \u0005לומר,\u0006 להסביר\u0005]\u0006 \u0003לך\u0004 כי \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בברכת הפועלים עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שהרי \u0003אמר מר\u0004 \u0005[החכם]\u0006 שהפועל בשעת מלאכתו יכול לקצר בברכת המזון, והרי הוא \u0003פותח ב\"הזן\" וכולל\u0004 את הברכה השלישית \u0003\"בונה ירושלים\" בברכת הארץ,\u0004 הברכה השניה.","ואף \u0003רב ששת מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שלדעתו \u0003דכולי עלמא\u0004 \u0005[הכל\u0006 סבורים\u0005]\u0006 שברכת הזימון היא \u0003עד \"הזן\",\u0004 ואולם בזאת נחלקו הברייתות, \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 בברייתא \u0003שתים ושלש\u0004 — \u0003שפיר\u0004 \u0005[יפה,\u0006 מתאים\u0005]\u0006 הדבר לשיטתו, \u0003ו\u0004אילו \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 בברייתא \u0003שלש וארבע קסבר\u0004 \u0005[סבור הוא]\u0006 שברכת \u0003\"הטוב והמטיב\" דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא.\u0004","בשאלה בדבר \"הטוב והמטיב\", \u0003אמר רב יוסף: תדע\u0004 ראיה לדבר שברכת \u0003\"הטוב והמטיב\"\u0004 היא \u0003לאו דאורייתא\u0004 \u0005[לא מן התורה]\u0006 היא — \u0003שהרי פועלים\u0004 המברכים ברכת המזון בשעת עבודתם \u0003עוקרים אותה,\u0004 ומתוך שיכולים הם שלא לומר אותה, ודאי שאין החיוב לאומרה מן התורה.","ראיה אחרת לכך \u0003אמר רב יצחק בר שמואל בר מרתא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: תדע\u0004 שברכת \u0003\"הטוב והמטיב\"\u0004 היא \u0003לאו דאורייתא\u0004 \u0005[לא מן התורה]\u0006 שהרי המברך ברכה זו \u0003פותח בה ב\"ברוך\" ואין חותם בה ב\"ברוך\"\u0004 שלא כשאר הברכות, \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל הברכות כולן פותח בהן ב\"ברוך\" וחותם בהן ב\"ברוך\", חוץ מברכת הפירות וברכת המצוות, וברכה הסמוכה לחברתה, וברכה אחרונה שבקריאת שמע\u0004 שאינן פותחות וחותמות ב\"ברוך\", אלא \u0003יש מהן שפותח בהן ב\"ברוך\" ואין חותם ב\"ברוך\",\u0004"],["\u0003ויש מהן שחותם בהן ב\"ברוך\" ואין פותח ב\"ברוך\". ו\"הטוב והמטיב\" פותח ב\"ברוך\" ואין חותם ב\"ברוך\". מכלל\u0004 \u0005[מכאן]\u0006 ש\u0003ברכה בפני עצמה היא. ו\u0004עוד הוכחה שברכת \"הטוב והמטיב\" איננה מן התורה","\u0003אמר רב נחמן בר יצחק: תדע\u0004 ש\u0003\"הטוב והמטיב\"\u0004 היא \u0003לאו דאורייתא\u0004 \u0005[לא מן התורה]\u0006 — \u0003שהרי עוקרין אותה בבית האבל. כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מה הם אומרים בבית האבל?\u0004 — \u0003\"ברוך הטוב והמטיב\". ר' עקיבא אומר: \"ברוך דיין האמת\".\u0004","ומקשים לדעה הראשונה שבברייתא: \u0003\"הטוב והמטיב\"\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 אומרים בבית האבל, ואילו \u0003\"דיין האמת\"\u0004 — \u0003לא\u0004 אומרים?! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 שכוונת הדברים היא שאומרים \u0003אף \"הטוב והמטיב\".\u0004","ומסופר: \u0003מר זוטרא איקלע לבי\u0004 \u0005[נקלע,\u0006 הזדמן \u0005לבית]\u0006 \u0003רב אשי, איתרע ביה מילתא\u0004 \u0005[אירע בו\u0006 ברב אשי, \u0005דבר\u0006 אבילות\u0005],\u0006 \u0003פתח ובריך\u0004 \u0005[וברך]\u0006 ברכה משולבת, וכך אמר: \u0003\"הטוב והמטיב, אל אמת, דיין אמת, שופט בצדק, לוקח במשפט, ושליט בעולמו לעשות בו כרצונו, כי כל דרכיו משפט, שהכל שלו ואנחנו עמו ועבדיו, ובכל אנחנו חייבים להודות לו ולברכו, גודר פרצות בישראל הוא יגדור את הפרצה הזאת בישראל לחיים\",\u0004 וכלל אם כן בדבריו גם \"הטוב והמטיב\" וגם הזכרת האבל וצידוק הדין. ומעתה שבים אל הנושא הראשון.","אמרנו שאדם אחד מפסיק מן האוכל ומצטרף אל שני חבריו הרוצים לזמן, ונשאלה השאלה \u0003להיכן הוא חוזר?\u0004 כאשר הוא בא לברך, מהיכן צריך הוא להתחיל? ונחלקו בכך חכמים, \u0003רב זביד משמיה\u0004 \u0005[בשמו]\u0006 של \u0003אביי אמר: חוזר לראש\u0004 ומברך ככל אדם אחר מתחילת ברכת המזון, \u0003ו\u0004אילו \u0003רבנן אמרי\u0004 \u0005[חכמים אומרים]\u0006 שחוזר \u0003למקום ש\u0004בו \u0003פסק,\u0004 כלומר, מתחילת ברכה שניה.","אגב ענייני הסעודה מסופר: \u0003אמר ליה ריש גלותא\u0004 \u0005[לו ראש הגולה]\u0006 \u0003לרב ששת: אף על גב דרבנן קשישי אתון\u0004 \u0005[אף על פי שחכמים קשישים אתם],\u0006 \u0003פרסאי\u0004 \u0005[הפרסיים]\u0006 \u0003בצרכי סעודה\u0004 (בקביעת סדרים נכונים באכילה) \u0003בקיאי מינייכו\u0004 \u0005[בקיאים\u0006 יותר \u0005מכם].\u0006 שאצלם \u0003בזמן שהן שתי מטות\u0004 שהיו אנשים מסובים בהן, נוהגים שה\u0003גדול\u0004 — \u0003מסב בראש, ו\u0004זה שהוא \u0003שני לו\u0004 בחשיבות — הריהו מסב \u0003למעלה הימנו,\u0004 לצד ראשו של הגדול. \u0003ובזמן שהם שלוש\u0004 מטות, ה\u0003גדול\u0004 — \u0003מסב באמצע\u0004 במיטה אמצעית, ה\u0003שני לו\u0004 — מסב \u0003למעלה הימנו, שלישי לו\u0004 בחשיבות — מסב \u0003למטה הימנו\u0004 מן הגדול.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת לראש הגולה שעדיין יש פגם בדבר, \u0003וכי בעי אישתעויי בהדיה, מתרץ תרוצי ויתיב ומשתעי בהדיה\u0004 \u0005[ואם רוצה\u0006 הגדול לדבר עם השני הרי \u0005צריך הוא להתיישר ולשבת ולדבר אתו]?!\u0006 שמכיון שהשני יושב מעל לראשו של הגדול, כשרוצה הוא לומר לו דבר הריהו נאלץ להזדקף. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ראש הגולה: \u0003שאני פרסאי, דמחוי ליה במחוג\u0004 \u0005[שונים הם הפרסים,\u0006 שכן הוא \u0005מראה לו ברמיזה]\u0006 שנהגו הפרסים לדבר בפרט בשעת הסעודה רק על ידי תנועות שונות בידיהם, ולכן אין צורך להזדקף.","ועוד שאל רב ששת את ראש הגולה כיצד נוהגים הפרסים בענין \u0003מים ראשונים\u0004 ברחיצת ידים שלפני הסעודה \u0003מהיכן מתחילין? אמר ליה\u0004 \u0005[לו]\u0006 ראש הגולה: \u0003מן הגדול.\u0004","שאלו רב ששת: אם כך נוהגים, \u0003ישב גדול וישמור ידיו עד שנוטלין כולן\u0004 ויביאו לכל הסועדים את האוכל? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ראש הגולה: \u0003לאלתר מייתו תכא קמיה\u0004 \u0005[מיד מביאים שולחן לפניו],\u0006 שנוהגים הם שלכל אדם יש שולחן מיוחד שעליו הוא אוכל, ולגדול מביאים את שולחנו מיד, ואינו צריך להמתין לאחרים.","ועוד שאל רב ששת את ראש הגולה בענייני סעודה הנוהגים אצל הפרסיים: כיצד נוהגים הפרסים ברחיצת הידים לאחר הסעודה, \u0003מים אחרונים מהיכן מתחילין? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מן הקטן.\u0004","והקשה רב ששת: \u0003ו\u0004אם כך נוהגים הם, יוצא איפוא שה\u0003גדול יתיב\u0004 \u0005[יושב]\u0006 \u0003וידיו מזוהמות\u0004 וממתין כך \u0003עד שנוטלין כולן\u0004 את ידיהם במים אחרונים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ראש הגולה: \u0003לא מסלקי תכא מקמיה עד דנימטי מיא לגביה\u0004 \u0005[אין מסלקים\u0006 את \u0005השולחן מלפניו עד שמביאים המים אליו],\u0006 ויכול הוא להמשיך ולאכול ככל שירצה, כל עוד רוחצים האחרים בסעודה את ידיהם במים אחרונים.","\u0003אמר רב ששת: אנא מתניתא ידענא\u0004 \u0005[אני יודע משנה],\u0006 כלומר, שכך אני נוהג בעניין זה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כיצד סדר הסבה?\u0004 — \u0003בזמן שהן שתי מטות\u0004 — \u0003גדול מסב בראש, ושני לו למטה הימנו. בזמן שהן שלש מטות\u0004 — \u0003גדול מסב בראש, שני לו למעלה הימנו, שלישי לו למטה הימנו. מים הראשונים מתחילין מן הגדול. מים אחרונים, בזמן שהם חמשה\u0004 — \u0003מתחילין מן הגדול, ובזמן שהם\u0004 יותר מכך, ואפילו הם \u0003מאה\u0004 — \u0003מתחילין מן הקטן עד שמגיעים אצל חמשי,\u0004 חמישה האחרונים, \u0003ו\u0004אז \u0003חוזרין ומתחילין מן הגדול\u0004 שבהם. \u0003ולמקום שמים אחרונים חוזרין,\u0004 כלומר, לאותו אדם שנותנים לו ליטול ידיו ראשון במים האחרונים — \u0003לשם ברכה חוזרת,\u0004 שהוא מברך ברכת המזון.","\u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לרב,\u0004 שכן \u0003אמר ר' חייא בר אשי\u0004 שכך \u0003אמר רב: כל הנוטל ידיו באחרונה תחלה\u0004 — \u0003הוא מזומן לברכה.\u0004","ומעין זה מסופר: \u0003רב ור' חייא הוו יתבי בסעודתא קמיה\u0004 \u0005[היו יושבים בסעודה לפני]\u0006 \u0003רבי, אמר ליה\u0004 [לו] \u0003רבי לרב: קום, משי ידך\u0004 \u0005[עמוד, רחוץ ידיך].\u0006 \u0003חזייה דקא מרתת\u0004 \u0005[ראהו\u0006 ר' חייא לרב \u0005שהוא מפחד]\u0006 שמא לא נהג יפה באוכל, ומפני כן הריהו צריך לשטוף ידיו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בר פחתי\u0004 \u0005[בן אצילים],\u0006 \u0003\"עיין\u0004 והתבונן \u0003בברכת מזונא\"\u0004 \u0005[המזון]\u0006 \u0003קאמר\u0004 \u0005[הוא אומר]\u0006 \u0003לך,\u0004 שהרי הנוטל ידיו בתחילה במים אחרונים, הוא זה שמכבדים אותו בברכת המזון.","ועוד בענין קדימה ברחצת מים אחרונים \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אף על פי שנוהגים להקדים אדם חשוב בראש, מכל מקום \u0003אין מכבדין\u0004 אותו \u0003לא בדרכים ולא בגשרים,\u0004"],["\u0003ולא בידים מזוהמות,\u0004 כלומר, בנטילת ידים בסוף הסעודה.","מסופר: \u0003רבין ואביי הוו קא אזלי באורחא\u0004 \u0005[היו מהלכים בדרך]\u0006 כשהם רכובים על חמוריהם, \u0003קדמיה חמריה\u0004 \u0005[קדמו חמורו]\u0006 של \u0003רבין ל\u0004חמורו של \u0003אביי ולא אמר ליה\u0004 \u0005[לו]\u0006 רבין לאביי \u0003\"ניזיל מר\"\u0004 \u0005[ילך אדוני\u0006 בראש\u0005].\u0006 \u0003אמר\u0004 אביי בלבו: \u0003מדסליק האי מרבנן ממערבא, גס ליה דעתיה\u0004 \u0005[מכיון שעלה חכם זה\u0006 רבין \u0005מארץ ישראל, גסה רוחו].\u0006 \u0003כי מטא לפיתחא דבי כנישתא\u0004 \u0005[כאשר הגיע לפתח בית הכנסת]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבין לאביי: \u0003ניעל מר\u0004 \u0005[יכנס אדוני\u0006 בראש\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003ועד השתא לאו \"מר\" אנא\u0004 \u0005[עכשיו אין אני \"אדון\"]?\u0006 כלומר, משום מה מתחיל אתה לכבד אותי רק עכשיו, ולא בכל הדרך? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבין: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: אין מכבדין אלא בפתח שיש בה מזוזה,\u0004 ששם ראוי להקדים את הגדול.","על כך הקשו: אם כך נאמר, שכל פתח \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה מזוזה\u0004 — \u0003אין\u0004 \u0005כן]\u0006 מכבדים בו, וכל פתח \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה מזוזה\u0004 — \u0003לא\u0004 מכבדים בו, \u0003אלא מעתה,\u0004 בפתחי \u0003בית הכנסת ובית המדרש, דלית בהו\u0004 \u0005[ש\u0006הרי \u0005אין בהם]\u0006 \u0003מזוזה, הכי נמי\u0004 \u0005[האם כך נאמר גם כן]\u0006 ש\u0003אין מכבדין\u0004 בכניסה אליהם? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך את הכלל: אין מכבדים בכניסה אלא \u0003בפתח\u0004 חשוב \u0003הראוי למזוזה,\u0004 אבל לא בדרך או בגשר.","ועוד בענייני כיבוד בסעודה. \u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: אין המסבין רשאין לאכול כלום\u0004 (משהו) \u0003עד שיטעום הבוצע. יתיב\u0004 \u0005[ישב]\u0006 \u0003רב ספרא וקאמר\u0004 \u0005[ואמר]:\u0006 \u0003\"לטעום\" איתמר\u0004 \u0005[נאמר],\u0006 כלומר, לשון רב היתה: אין המסובים רשאים לטעום עד שיטעם הבוצע. על כך שואלים בגמרא.","\u0003למאי נפקא מינה\u0004 \u0005[ומה יוצא ממנה,\u0006 מן התיקון הזה\u0005]?\u0006 שהרי אין הבדל משמעות בין הגירסות. ומסבירים שאכן אין הבדל, ורב ספרא מדייק בכך \u0003שחייב אדם לומר בלשון רבו,\u0004 שחייב אדם לומר בלשון רבו, ולא לשנות ממנה אף בפרט קטן.","ועוד בענייני כיבוד בסעודה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שנים\u0004 האוכלים יחד \u0003ממתינין\u0004 (מחכים) \u0003זה לזה ב\u0004זמן שהם אוכלים מ\u0003קערה\u0004 אחת, אבל אם היו \u0003שלשה\u0004 — \u0003אין ממתינין,\u0004 וכל אחד אוכל כרצונו. ובדרך כלל: \u0003הבוצע\u0004 על הפת הוא \u0003פושט ידו תחלה\u0004 לקחת את הלחם, \u0003ו\u0004אולם \u0003אם בא\u0004 הבוצע \u0003לחלוק כבוד לרבו או למי שגדול הימנו\u0004 — \u0003הרשות\u0004 נתונה \u0003בידו\u0004 לעשות כן.","מסופר: \u0003רבה בר בר חנה הוה עסיק ליה לבריה\u0004 \u0005[היה עוסק לו לבנו]\u0006 בצרכי נישואיו ב\u0003בי\u0004 \u0005[בית]\u0006 \u0003רב שמואל בר רב קטינא, קדים ויתיב וקמתני ליה לבריה\u0004 \u0005[קדם וישב ושנה לו לבנו]\u0006 בהלכות סעודה: \u0003אין הבוצע רשאי לבצוע עד שיכלה \"אמן\" מפי העונים\u0004 על ברכתו. ו\u0003רב חסדא אמר\u0004 שיש לחכות רק עד שתכלה \"אמן\" \u0003מפי רוב העונים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רמי בר חמא: מאי שנא רובא\u0004 \u0005[מה שונה,\u0006 מיוחד, \u0005רוב\u0006 עונים\u0005]\u0006 שאסור לבצוע לפני שיענו \"אמן\" — משום \u0003דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003לא כליא\u0004 \u0005[כלתה]\u0006 ה\u0003ברכה, מיעוטא נמי\u0004 \u0005[מיעוט\u0006 עונים \u0005גם כן]\u0006 עדיין \u0003לא כליא\u0004 \u0005[כלתה]\u0006 ה\u0003ברכה,\u0004 ומדוע אינו מחכה להם?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003שאני אומר, כל העונה \"אמן\" יותר מדאי\u0004 באריכות — \u0003אינו אלא טועה.\u0004","ובענין זה של אמירת \"אמן\" \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין עונין לא \"אמן\" חטופה\u0004 (קצרה מדי, שאין היא מבוטאת כראוי), \u0003ולא \"אמן\" קטופה\u0004 (שאין סיומה מבוטא כראוי), \u0003ולא \"אמן\" יתומה\u0004 (הנאמרת בלי לדעת על מה היתה הברכה), \u0003ו\u0004כן \u0003לא יזרוק אדם ברכה מפיו\u0004 במהירות ובלא עיון.","ו\u0003בן עזאי אומר: כל העונה \"אמן\" יתומה\u0004 — \u0003יהיו בניו יתומים,\u0004 \"אמן\" \u0003חטופה\u0004 — \u0003יתחטפו ימיו\u0004 ולא ישלימם, \"אמן\" \u0003קטופה\u0004 — \u0003יתקטפו ימיו. וכל המאריך ב\"אמן\"\u0004 — \u0003מאריכין לו ימיו ושנותיו.\u0004 ואולם אין להאריך יותר מדי.","ושוב לענין זימון. מסופר: \u0003רב ושמואל הוו יתבי בסעודתא\u0004 \u0005[היו יושבים בסעודה].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 אחריהם לסעודה זו \u0003רב שימי בר חייא, הוה קמסרהב ואכיל\u0004 \u0005[היה ממהר ואוכל],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב: מה דעתך\u0004 שאתה ממהר כל כך באכילתך — \u0003לאיצטרופי בהדן\u0004 \u0005[להצטרף אתנו\u0006 לזימון\u0005],\u0006 ואולם \u0003אנן אכילנא לן\u0004 \u0005[אנו אכלנו לנו],\u0006 שכבר גמרנו את אכילתנו עוד לפני שבאת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל\u0004 לרב: אין לומר שכבר גמרו לאכול, משום ש\u0003אלו מייתו\u0004 \u0005[היו מביאים]\u0006 \u0003לי ארדיליא\u0004 \u0005[פטריות]\u0006 שהיו חביבות עליו, \u0003וגוזליא\u0004 \u0005[וגוזלים]\u0006 \u0003לאבא\u0004 (רב), מי \u0005[האם]\u0006 \u0003לא אכלינן\u0004 \u0005[היינו אוכלים]?\u0006 ואם כן הריהם נחשבים כעודם בתוך הסעודה, ויכול רב שימי בר חייא להצטרף אליהם לזימון.","מסופר כי \u0003תלמידי רב הוו יתבי בסעודתא\u0004 \u0005[היו יושבים בסעודה],\u0006 \u0003על\u0004 \u0005[נכנס]\u0006 לסעודה \u0003רב אחא. אמרי\u0004 \u0005[אמרו]\u0006 התלמידים: הנה \u0003אתא גברא רבא דמברך לן\u0004 \u0005[בא אדם גדול שיברך לנו].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 רב אחא: \u0003מי סבריתו\u0004 \u0005[האם אתם סבורים]\u0006 שה\u0003גדול מברך?\u0004 לא כן, אלא ה\u0003עיקר שבסעודה,\u0004 כלומר, אלה שהיו בסעודה בתחילתה הוא ה\u0003מברך.\u0004 ומסכמים, \u0003והלכתא\u0004 \u0005[וההלכה]\u0006 היא שה\u0003גדול מברך, אף על גב דאתא\u0004 \u0005[אף על פי שבא]\u0006 \u0003לבסוף.\u0004","שנינו במשנה שאם \u0003אכל\u0004 לחם העשוי מתבואת \u0003דמאי\u0004 יכול הוא לברך עליו ברכת המזון. ומקשים: \u0003הא לא חזי ליה\u0004 \u0005[הרי אין\u0006 זה \u0005ראוי לו],\u0006 שהרי אסור לאכול דמאי! על כך עונים: \u0003כיון דאי בעי, מפקר להו לנכסיה, והוי\u0004 \u0005[שאם רוצה, מפקיר אותם את נכסיו, והריהו]\u0006 מעתה \u0003עני, וחזי ליה\u0004 \u0005[ו\u0006עתה \u0005ראוי לו]\u0006 לאכול דמאי, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]:\u0006 \u0003מאכילין את העניים דמאי, ואת האכסניא\u0004 (אנשי צבא שבני העיר צריכים לפרנס אותם על חשבונם) \u0003דמאי. ואמר רב הונא: תנא\u0004 \u0005[שנה]\u0006 באופן אחר הלכה זו, \u0003בית שמאי אומרים: אין מאכילין את העניים ואת האכסניא דמאי.\u0004","שנינו במשנה כי מצרפים לזימון גם את האוכל \u0003מעשר ראשון שנטלה תרומתו.\u0004 על כך תוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הלא זה האופן הראוי, שכבר נתרמה התרומה ואין כל חשש, ומה מקום ללמדנו שהדבר מותר באכילה? ומסבירים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו להיאמר \u0003אלא\u0004 במקרה זה \u0003ש\u0004הלוי \u0003הקדימו\u0004 את הכהן בעוד החיטה \u0003בשבלים, והפריש ממנו\u0004 ללוי \u0003תרומת מעשר, ו\u0004עדיין \u0003לא הפריש ממנו\u0004 לכהן \u0003תרומה גדולה\u0004 כדרך ההפרשה הראוי. ואף שאין לעשות כך לכתחילה, לאחר מעשה — מה שעשה עשוי, והאוכל מעשר ראשון שכזה הריהו מצטרף לזימון. \u0003וכדר' אבהו,\u0004 שכן \u0003אמר ר' אבהו\u0004 שכך \u0003אמר ריש לקיש: מעשר ראשון שהקדימו\u0004 הלוי וקיבל אותו בעוד החיטה עדיין \u0003בשבלים\u0004 — \u0003פטור\u0004 מעשר זה \u0003מתרומה גדולה\u0004 (היא התרומה לכהן), \u0003שנאמר: \"והרמתם ממנו תרומת ה' מעשר מן המעשר\"\u0004 (במדבר יח, כו), וללמדנו בא הכתוב: \u0003מעשר מן המעשר\u0004 (\"תרומת מעשר\") \u0003אמרתי לך\u0004 שחייב הלוי לתת, \u0003ולא תרומה גדולה ו\u0004גם \u0003תרומת מעשר מן המעשר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו הקדימו\u0004 הלוי \u0003בכרי\u0004 כאשר גרגרי החיטה הוצאו מן השיבלים ונערמו לערימה, \u0003נמי\u0004 \u0005[גם כן]\u0006 לא יצטרך הלוי להפריש תרומה גדולה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003עליך,\u0004 כלומר, כנגד טענה כזאת \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006"],["\u0003\"מכל מעשרתיכם תרימו\u0004 כל תרומת ה'\u0003\"\u0004 (שם, שם, כט). ויש לתת את תרומת ה' — היא התרומה הגדולה — גם ממתנות הלויים. על כך שואלים \u0003ומה ראית\u0004 לפרש שהציווי להפריש גם תרומה גדולה נאמר על התבואה בכרי ולא על השיבלים? ועונה אביי: \u0003האי אידגן והאי לא אידגן\u0004 \u0005[זה נעשה דגן, וזה לא נעשה דגן]\u0006 שבכתוב נאמר כי ראשית הדגן (\"ראשית דגנך\". דברים יח,ד) לכהן, ודבר הנקרא כבר \"דגן\" חלה עליו רשות הכהן, ואי אפשר להוציאו מידו.","שנינו במשנה שהאוכל \u0003מעשר שני והקדש שנפדו\u0004 מצטרף לזימון. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שמדוע לא יברכו על דבר המותר באכילה? ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — במקרה מיוחד, שלא נפדה ההקדש בשלמות אלא \u0003כגון שנתן את הקרן —\u0004 מחירו של המעשר, \u0003ולא נתן את החומש\u0004 שצריך להוסיף אם רוצים לפדות דבר שחלה עליו כבר קדושה. \u0003והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו\u0006 המשנה\u0005]\u0006 ש\u0003אין\u0004 ה\u0003חומש מעכב.\u0004","שנינו במשנה כי \u0003השמש שאכל כזית\u0004 מצטרף ומזמנים עליו, ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הדבר, ומדוע יש לשנותו? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 יכול היית לומר שה\u0003שמש\u0004 העומד כל הזמן לשמש את הסועדים, \u0003לא קבע\u0004 סעודתו ואינו מצטרף אליהם לזימון, על כן \u0003קא משמע לן\u0004 \u0005[משמיעה לנו ]\u0006 המשנה שאף אכילת השמש נחשבת חלק מן הסעודה הקבועה.","עוד שנינו במשנה: \u0003והכותי מזמנין עליו,\u0004 שהוא מצטרף לסועדים לחיוב זימון. על כך שואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 ו\u0003לא יהא אלא עם הארץ!\u0004 כלומר, אף אם ייחשב הכותי כשייך לעם ישראל הרי ודאי אינו עדיף מעם הארץ אחר, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003אין מזמנין על עם הארץ!\u0004","לכך נתנו תשובות אחדות: \u0003אביי אמר\u0004 שכאן המדובר \u0003בכותי חבר\u0004 (תלמיד חכם), וממילא אין דיני עם הארץ חלים עליו. \u0003רבא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שדובר במשנה \u0003בכותי עם הארץ. ו\u0004אולם \u0003הכא\u0004 \u0005[כאן],\u0006 האיסור לזמן עם עם הארץ שייך \u0003ב\u0004סוג מסויים של עם הארץ — \u0003בעם הארץ דרבנן\u0004 \u0005[\u0006כדעת \u0005חכמים]\u0006 \u0003דפליגי עליה\u0004 \u0005[החולקים עליו]\u0006 על \u0003ר' מאיר עסקינן\u0004 \u0005[עוסקים אנו] ,\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003איזהו עם הארץ?\u0004 — \u0003כל שאינו אוכל חוליו,\u0004 כלומר, אפילו חולין \u0003בטהרה,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים:\u0004 עם הארץ הוא \u0003כל שאינו מעשר פירותיו כראוי. והני כותאי עשורי מעשרי כדחזי, דבמאי דכתיב באורייתא מזהר זהירי\u0004 \u0005[ואותם הכותים מעשרים כראוי, שבמה שכתוב בתורה זהירים הם].\u0006 שכן \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל מצוה שהחזיקו בה כותיים\u0004 וקבלו אותה עליהם — \u0003הרבה מדקדקים בה,\u0004 ואף \u0003יותר מישראל.\u0004","ואגב הבאת דברים בהגדרת עם הארץ, מביאים עוד מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003איזהו עם הארץ?\u0004 — \u0003כל שאינו קורא קריאת שמע ערבית ושחרית, דברי רבי אליעזר. ר' יהושע אומר: כל\u0004 מי \u0003שאינו מניח תפילין. בן עזאי אומר: כל שאין לו ציצית בבגדו. ר' נתן אומר: כל שאין מזוזה על פתחו. ר' נתן בר יוסף אומר:\u0004 עם הארץ הוא \u0003כל שיש לו בנים ואינו מגדלם לתלמוד תורה,\u0004 שאינו חפץ שילמדו. ו\u0003אחרים אומרים: אפילו קרא ושנה ולא שמש תלמידי חכמים\u0004 ולא למד מפיהם פירושם של דברים \u0003הרי זה עם הארץ. אמר רב הונא: הלכה כאחרים\u0004 שאף אדם כזה נקרא עם הארץ.","ומסופר: \u0003רמי בר חמא לא אזמין עליה\u0004 \u0005[הזמין עליו,\u0006 צירפו לזימון\u0005]\u0006 את \u0003רב מנשיא בר תחליפא דתני סיפרא וספרי והלכתא\u0004 \u0005[ששנה ספרא וספרי והלכות]\u0006 משום שלמד הכל בעצמו, בלי לשמש תלמידי חכמים. \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו\u0006 נפטר\u0005]\u0006 \u0003רמי בר חמא, אמר רבא: לא נח נפשיה\u0004 \u0005[נחה נפשו\u0006 נפטר\u0005]\u0006 \u0003רמי בר חמא אלא\u0004 משום ש\u0003לא אזמין\u0004 \u0005[צירף לזימון]\u0006 את \u0003רב מנשיא בר תחליפא.\u0004 על כך שואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שכך נפסקה ההלכה — \u0003אחרים אומרים אפילו קרא ושנה ולא שמש תלמידי חכמים הרי זה עם הארץ\u0004, ומדוע נענש רמי בר חמא? ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 הוא \u0003רב מנשיא בר תחליפא דמשמע להו לרבנן\u0004 \u0005[שהיה משמש את החכמים]\u0006 \u0003ורמי בר חמא הוא\u0004 ש\u0003לא דק אבתריה\u0004 \u0005[דייק אחריו]\u0006 לדעת מה מעשיו. או \u0003לשנא אחרינא\u0004 \u0005[בלשון אחרת]:\u0006 \u0003דשמע שמעתתא מפומייהו דרבנן וגריס להו\u0004 \u0005[\u0006כל \u0005השומע הלכות מפי החכמים ולומד אותן]\u0006 — \u0003כצורבא מרבנן דמי\u0004 \u0005[כתלמיד חכם\u0006 הוא \u0005נחשב].\u0006","שנינו במשנה שאם \u0003אכל טבל ומעשר\u0004 אין מזמנים עליו, ושואלים: דבר זה הוא \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי טבל אסור באכילה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 ההלכה הכתובה במשנה אלא \u0003ב\u0004מקרה שהיה זה \u0003טבל טבול\u0004 (שנכנס להגדרת טבל ) רק \u0003מדרבנן\u0004 ומן התורה היה מותר לאוכלו. \u0003היכי דמי\u0004 \u0005[כיצד היה הדבר בדיוק] —\u0006 כגון מפרי שצמח \u0003בעציץ שאינו נקוב\u0004 שהצומח בעציץ מנותק מן הארץ אינו נחשב כפרי הארץ. ופטור מן התורה ממעשר, ואינו טבל אלא מדברי חכמים.","עוד שנינו במשנה שהאוכל \u0003מעשר ראשון\u0004 שלא נטלה ממנו תרומתו אין מזמנים עליו. ושואלים: והרי גם זה \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 משנה זו להישנות אלא ל\u0003כגון שהקדימו\u0004 הלוי את הכהן ולקח את התבואה \u0003בכרי.\u0004 ואז \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003כדאמר ליה\u0004 \u0005[כפי שאמר לו]\u0006 \u0003רב פפא לאביי\u0004 שגם במקרה זה יהיה פטור מהפרשת תרומה, על כן \u0003קא משמע לן כדשני ליה\u0004 \u0005[השמיע לנו,\u0006 התנא במשנה, \u0005כפי שתירץ לו\u0006 אביי לרב פפא\u0005]\u0006 שיש הבדל בין המקרים.","עוד שנינו במשנה שאין מזמנים על האוכל \u0003מעשר שני\u0004 והקדש שלא נפדו. ושואלים: אף דין זה הוא \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומה חידוש יש בדבר? ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו להישנות, אלא למקרה \u0003שנפדו ו\u0004אולם \u0003לא נפדו כהלכתן, במעשר שני, כגון שפדאו על גבי אסימון,\u0004 ששילם את תמורת המעשר בחתיכות כסף שעדיין לא נטבעה עליהן צורת מטבע, \u0003ורחמנא אמר\u0004 \u0005[והתורה אמרה]:\u0006 \u0003וצרת הכסף בידך\"\u0004 (דברים יד, כה) ודרשו חכמים: \"וצרת הכסף בידך\" — \u0003כסף שיש (לו) עליו צורה\u0004 שהוא מטבע, ולא אסימון. וכן לגבי ה\u0003הקדש\u0004 — כגון \u0003שחללו על גבי קרקע,\u0004 שנתן הפודה קרקע תמורתו \u0003ולא פדאו בכסף, ורחמנא אמר\u0004 \u0005[והתורה אמרה]:\u0006 \u0003\"ונתן הכסף וקם לו\"\u0004 (ויקרא כז, כג).","עוד שנינו במשנה ש\u0003השמש שאכל פחות מכזית\u0004 אין מזמנים עליו. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הוא דין זה, ואין צורך לשנותו! ומשיבים: \u0003איידי דתנא רישא\u0004 \u0005[מתוך ששנה בראש\u0006 המשנה\u0005]\u0006 \u0003\"כזית\", תנא סיפא\u0004 \u0005[שנה בסוף]\u0006 \u0003\"פחות מכזית\",\u0004 מתוך שגרת הלשון, אף שלא היה צורך לכתוב זאת במפורש.","שנינו במשנה ש\u0003הגוי אין מזמנין עליו,\u0004 ואף כאן שואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הוא דין זה, ואין צורך לשנותו! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 לא בגוי סתם, אלא במקרה מיוחד, \u0003בגר שמל\u0004 ועדיין \u0003לא טבל.\u0004 שכן \u0003אמר ר' זירא\u0004 שכך \u0003אמר ר' יוחנן: לעולם אינו גר עד שימול ויטבול ו\u0004כל \u0003כמה\u0004 ש\u0003לא טבל גוי הוא.\u0004","עוד שנינו במשנה כי \u0003נשים ועבדים וקטנים אין מזמנין עליהן.\u0004 ובענין זה \u0003אמר ר' יוסי: קטן המוטל בעריסה מזמנין עליו,\u0004 שמצטרף הוא לזימון.","ומקשים: \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]\u0006 ש\u0003נשים ועבדים וקטנים אין מזמנין עליהן!\u0004","ומשיבים: \u0003הוא\u0004 ר' יוסי מה ש\u0003אמר\u0004 הרי זה \u0003כ\u0004שיטתו של \u0003ר' יהושע בן לוי,\u0004 שכן \u0003אמר ר' יהושע בן לוי: אף על פי שאמרו\u0004 ש\u0003קטן המוטל בעריסה אין מזמנין עליו, אבל עושין אותו סניף\u0004 לצרף אותו \u0003לעשרה\u0004 הרוצים לזמן בהזכרת השם.","\u0003ו\u0004עוד \u0003אמר ר' יהושע בן לוי\u0004 בענין זה של צירוף לזימון: \u0003תשעה\u0004 ישראלים \u0003ועבד\u0004 — \u0003מצטרפין\u0004 לזמן בעשרה. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003מעשה בר' אליעזר שנכנס לבית הכנסת ולא מצא\u0004 בו מנין \u0003עשרה, ושחרר\u0004 את \u0003עבדו והשלימו לעשרה.\u0004 ואפשר ללמוד מכאן כי רק אם \u0003שחרר\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 מצטרף הוא, אבל אם \u0003לא שחרר\u0004 — \u0003לא\u0004 מצטרף העבד. ומשיבים: באותו מקרה \u0003תרי איצטריכו\u0004 \u0005[שנים הוצרכו,\u0006 חסרו\u0005]\u0006 למנין זה, ואז \u0003שחרר חד\u0004 \u0005[אחד]\u0006 \u0003ונפיק בחד\u0004 \u0005[ויצא באחד\u0006 שלא שוחרר, על ידי צירוף.","על מעשהו של ר' אליעזר שואלים: \u0003והיכי עביד הכי\u0004 \u0005[וכיצד עשה כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה\u0004 ש\u0003כל המשחרר\u0004 את \u0003עבדו\u0004 הכנעני \u0003עובר בעשה, ש\u0004כן \u0003נאמר\u0004 בדיני העבד הכנעני: \u0003\"\u0004והתנחלתם אותם לבניכם אחריכם לרשת אחוזה \u0003לעולם בהם תעבדו\"\u0004 (ויקרא כה, מו), וכיצד אם כן שחרר ר' אליעזר את עבדו? ומשיבים: \u0003לדבר מצוה שאני\u0004 \u0005[שונה]\u0006 ומותר. ושואלים: אם כן הרי זו \u0003מצוה הבאה בעברה!\u0004 שהרי מצוה זו לא נתאפשרה אלא על ידי עשיית עבירה, והיא פגומה משום כך. ומשיבים: \u0003מצוה\u0004 של \u0003רבים שאני\u0004 \u0005[שונה],\u0006 ולשם זיכוי הרבים מותר אף לשחרר את העבד.","ובשבח מנין העשרה מביאים עוד מה ש\u0003אמר ר' יהושע בן לוי: לעולם ישכים אדם לבית הכנסת כדי שיזכה וימנה עם עשרה הראשונים\u0004 וישלים את המנין. \u0003שאפילו מאה\u0004 אנשים אחרים \u0003באים אחריו\u0004 — \u0003קבל שכר כולם,\u0004 שהכל מצטרפים למנין הראשון. ותוהים: \u0003\"שכר כולם\" סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 מדוע יטול זה מהם את שכרם? \u0003אלא אימא\u0004 \u0005[אמור,\u0006 תקן כך]: \u0003נותנין לו שכר כנגד כולם.\u0004","בדיני צירוף למנין \u0003אמר רב הונא: תשעה וארון\u0004 הקודש — \u0003מצטרפין\u0004 ונחשבים כעשרה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: ו\u0004כי \u0003ארון גברא\u0004 \u0005[איש]\u0006 \u0003הוא\u0004 שאפשר לצרפו לעשרה? \u0003אלא אמר רב הונא: תשעה נראים כעשרה\u0004 — \u0003מצטרפין.\u0004 ובכך נחלקו. היו ש\u0003אמרי לה\u0004 \u0005[אמרו אותה]\u0006 הלכה שהיא באופן זה: תשעה נראים כעשרה \u0003כי מכנפי\u0004 \u0005[כאשר\u0006 הם \u0005מכונסים].\u0006 \u0003ואמרי לה\u0004 \u0005[ויש שאומרים אותה]\u0006 הלכה בדרך זו: תשעה נראים כעשרה \u0003כי מבדרי\u0004 \u0005[כאשר\u0006 הם \u0005מפוזרים],\u0006 שנחלקו באיזו צורה מתקבל רושם של מספר גדול יותר.","מעין זה \u0003אמר רב אמי: שנים ושבת מצטרפין. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: ו\u0004כי \u0003שבת גברא\u0004 \u0005[איש]\u0006 \u0003הוא\u0004 שתצטרף?! \u0003אלא אמר ר' אמי: שני תלמידי חכמים המחדדין זה את זה בהלכה מצטרפין\u0004 ונחשבים לשלושה. ומסופר: \u0003מחוי\u0004 \u0005[היה מראה]\u0006 \u0003רב חסדא\u0004 דוגמא לשני תלמידי חכמים המחדדים זה את זה בהלכה: \u0003כגון אנא\u0004 \u0005[אני]\u0006 \u0003ורב ששת,\u0004 וכמו כן \u0003מחוי\u0004 \u0005[היה מראה]\u0006 \u0003רב ששת: כגון אנא\u0004 \u0005[אני]\u0006 \u0003ורב חסדא.\u0004","ובענין צירוף לזימון של קטן, \u0003אמר ר' יוחנן: קטן פורח,\u0004 כלומר, ילד שלפי שנותיו עדיין הוא קטן, אבל הביא כבר סימני בגרות — \u0003מזמנין עליו. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003קטן שהביא שתי שערות\u0004 הערוה, שהן סימן בגרות — \u0003מזמנין עליו, ושלא הביא שתי שערות\u0004 — \u0003אין מזמנין עליו, ואין מדקדקין בקטן.\u0004 ומעירים: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה,\u0006 ברייתא זאת, \u0005קשה],\u0006 שכן \u0003אמרת: הביא שתי שערות\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מצרפים אותו, ונדייק מכאן שאם \u0003לא הביא\u0004 שתי שערות — \u0003לא. והדר תני\u0004 \u0005[וחזר\u0006 ו\u0005שנה]\u0006 ש\u0003אין מדקדקין בקטן. לאתויי מאי\u0004 \u0005[לרבות\u0006 להוסיף \u0005מה]\u0006 בא ביטוי זה? \u0003לאו\u0004 \u0005[האם לא]\u0006"],["\u0003לאתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 \u0003קטן פורח?\u0004 וכך תפורש הברייתא: שקטן שהביא שתי שערות — מצרפים אותו לזימון, ו\"אין מדקדקים בקטן\" אם כבר הגיע לגיל הבגרות או לא.","אך מסכמים בגמרא: \u0003ולית הילכתא\u0004 \u0005[ואין הלכה]\u0006 \u0003ככל הני שמעתתא\u0004 \u0005[המאמרים הללו]\u0006 \u0003אלא כי הא\u0004 \u0005[כמו\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר רב נחמן: קטן היודע למי מברכין\u0004 — \u0003מזמנין עליו.\u0004","ומסופר: \u0003אביי ורבא הוו יתבי קמיה\u0004 \u0005[לפני]\u0006 \u0003רבה\u0004 בעודם תינוקות. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבה: למי מברכין? אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003לרחמנא\u0004 \u0005[לקדוש ברוך הוא]\u0006 שאל אותם רבה: \u0003ורחמנא היכא יתיב\u0004 \u0005[והקדוש ברוך הוא היכן יושב]?\u0006 \u0003רבא אחוי לשמי טללא\u0004 \u0005[הראה לשמי קורה,\u0006 כלפי התקרה\u0005],\u0006 \u0003אביי נפק לברא, אחוי כלפי שמיא\u0004 \u0005[יצא לחוץ, הראה על השמים]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבה: תרוייכו רבנן הויתו\u0004 \u0005[שניכם תהיו חכמים].\u0006 ו\u0003היינו דאמרי אינשי\u0004 \u0005[וזהו שאומרים אנשים]\u0006 כפתגם עממי: \u0003בוצין בוצין מקטפיה ידיע\u0004 \u0005[קישוא קישוא\u0006 עוד \u0005מפריחתו\u0006 הוא \u0005ניכר],\u0006 כלומר, אפשר להכיר אדם גדול גם בקטנותו.","\u0003אמר ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: תשעה שאכלו דגן ואחד אכל ירק\u0004 — מצטרפין כולם לזמן בעשרה. \u0003אמר ר' זירא: בעאי מיניה\u0004 \u0005[שאלתי ממנו]\u0006 \u0003מרב יהודה:\u0004 אם היו רק \u0003שמונה\u0004 שאכלו דגן ושנים נוספים אכלו ירק \u0003מהו\u0004 דינם, האם יכולים הם להצטרף? וכן אם היו רק \u0003שבעה מהו\u0004 דינם לענין זה? \u0003אמר לי: לא שנא\u0004 \u0005[אינו שונה].\u0006 \u0003ששה ודאי לא מבעיא\u0004 \u0005[נשאלה]\u0006 \u0003לי,\u0004 שהיה ברור בעיניו שששה אינם מספיקים להצריך זימון. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה: שפיר עבדת\u0004 \u0005[יפה עשית]\u0006 ש\u0003לא איבעיא\u0004 \u0005[נשאלה]\u0006 \u0003לך\u0004 שאלה זו, \u0003התם טעמא מאי\u0004 \u0005[שם,\u0006 בשמונה ושבעה, \u0005הטעם מהו]\u0006 — \u0003משום דאיכא רובא\u0004 \u0005[שיש רוב\u0006 של סועדים\u0005],\u0006 \u0003הכא נמי איכא רובא\u0004 \u0005[כאן גם כן יש רוב].\u0006 \u0003ואיהו סבר רובא דמינכר בעינן\u0004 \u0005[והוא,\u0006 ר' זירא, \u0005סבור\u0006 כי \u0005רוב הניכר צריכים אנו\u0006 שיהיה\u0005],\u0006 ולכן היה לו ברור, בניגוד לר' ירמיה, כי שישה אינם מספיקים כדי לחייב זימון.","מסופר כי \u0003ינאי מלכא ומלכתא\u0004 \u0005[המלך והמלכה]\u0006 \u0003כריכו ריפתא בהדי הדדי\u0004 \u0005[אכלו לחם יחד],\u0006 \u0003ומדקטל להו לרבנן לא הוה ליה איניש לברוכי להו\u0004 \u0005[ומכיון שהרג\u0006 ינאי \u0005את החכמים לא היה לו אדם שיברך להם].\u0006 \u0003אמר לה לדביתהו\u0004 \u0005[לאשתו]:\u0006 \u0003מאן יהיב לן גברא דמברך לן\u0004 \u0005[מי יתן לנו איש שיברך לנו]?\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אשתבע\u0004 \u0005[השבע]\u0006 \u0003לי דאי מייתינא\u0004 \u0005[שאם אביא]\u0006 \u0003לך גברא\u0004 \u0005[אדם]\u0006 שכזה ש\u0003לא מצערת ליה\u0004 \u0005[תצער אותו].\u0006 \u0003אשתבע\u0004 \u0005[נשבע ]\u0006 \u0003לה. אייתיתיה\u0004 \u0005[הביאתו]\u0006 \u0003לשמעון בן שטח אחוה\u0004 \u0005[אחיה].\u0006 \u0003אותביה\u0004 \u0005[הושיבו]\u0006 \u0003בין\u0004 הכסא \u0003דידיה לדידה\u0004 \u0005[שלו לשלה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזית\u0004 \u0005[רואה אתה]\u0006 \u0003כמה יקרא עבדינא\u0004 \u0005[כבוד עושה אני]\u0006 \u0003לך. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו את קא מוקרת לי\u0004 \u0005[לא אתה הוא המכבד אותי]\u0006 \u0003אלא אורייתא\u0004 \u0005[התורה]\u0006 \u0003היא דמוקרא לי\u0004 \u0005[שמכבדת אותי],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר ]:\u0006 \u0003\"סלסלה ותרוממך תכבדך כי תחבקנה\"\u0004 (משלי ד, ח). \u0003אמר לה\u0004 ינאי לאשתו: \u0003קא חזית\u0004 \u0005[רואה את]\u0006 שהוא \u0003לא מקבל מרות.\u0004","\u0003יהבו ליה כסא לברוכי\u0004 \u0005[נתנו לו\u0006 לשמעון בן שטח \u0005כוס\u0006 יין \u0005לברך\u0006 עליו ברכת המזון\u0005].\u0006 \u0003אמר: היכי אבריך\u0004 \u0005[איך אברך]\u0006 — \u0003\"ברוך שאכל ינאי וחביריו משלו\"?\u0004 שכן אני לא אכלתי כלל. \u0003שתייה לההוא כסא, יהבו ליה כסא אחרינא ובריך\u0004 \u0005[שתה את הכוס ההיא, נתנו לו כוס אחרת וברך],\u0006 שעל ידי שתיית הכוס הראשונה הצטרף לסועדים, ועל השניה ברך ברכת המזון.","על סיפור זה \u0003אמר ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא אמר ר' יוחנן: שמעון בן שטח דעבד\u0004 \u0005[שעשה]\u0006 כן לברך כך — \u0003לגרמיה\u0004 \u0005[לעצמו]\u0006 \u0003הוא דעבד\u0004 \u0005[שעשה]\u0006 אבל אין דעתו מקובלת להלכה, \u0003דהכי אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: לעולם\u0004 המברך \u0003אינו מוציא את הרבים ידי חובתן\u0004 בברכת הזימון אלא \u0003עד שיאכל כזית דגן.\u0004","על כך מקשים \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא, ש\u0003רבן שמעון בן גמליאל אומר:\u0004 מי ש\u0003עלה והסיב\u0004 עם האוכלים \u0003אפילו לא טבל עמהם אלא בציר\u0004 שטבל דבר אכילה בציר החריף שלפני המסובים, \u0003ולא אכל עמהם אלא גרוגרת אחת\u0004 — \u0003מצטרף.\u0004 ואם כן נראה שאינו צריך לאכול דגן דווקא!","ומשיבים: אמנם \u0003איצטרופי מצטרף\u0004 \u0005[מצטרף הוא]\u0006 \u0003אבל\u0004 אינו יכול \u0003להוציא את הרבים ידי חובתן\u0004 — \u0003עד שיאכל כזית דגן.\u0004","ומעין זה \u0003איתמר נמי\u0004 \u0005[נאמר גם כן],\u0006 שכך אמר \u0003רב חנא בר יהודה משמיה\u0004 \u0005[בשמו]\u0006 של \u0003רבא\u0004 שהלכה היא: \u0003אפילו לא.\u0004"],["\u0003טבל עמהם אלא בציר, ולא אכל עמהם אלא גרוגרת אחת\u0004 — \u0003מצטרף. ולהוציא את הרבים ידי חובתם\u0004 — \u0003אינו מוציא עד שיאכל כזית דגן. אמר רב חנא בר יהודה משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא, הלכתא\u0004 \u0005[הלכה]\u0006 היא: אם \u0003אכל עלה\u0004 של \u0003ירק ו\u0004כן אם \u0003שתה כוס של יין\u0004 — \u0003מצטרף\u0004 לזימון. ואולם \u0003להוציא\u0004 אחרים ידי חובה — \u0003אינו מוציא, עד שיאכל כזית דגן.\u0004","על ארבע הברכות בברכת המזון \u0003אמר רב נחמן: משה תקן לישראל\u0004 את הברכה הראשונה \u0003ברכת \"הזן\" בשעה שירד להם מן,\u0004 והיו צריכים להודות עליו. \u0003יהושע תקן להם\u0004 את \u0003ברכת הארץ כיון\u0004 (כאשר) \u0003שנכנסו לארץ. דוד ושלמה תקנו\u0004 את הברכה השלישית \u0003\"בונה ירושלים\",\u0004 ובאופן זה: \u0003דוד תקן \"על ישראל עמך ועל ירושלים עירך\", ושלמה תקן \"על הבית הגדול והקדוש\"\u0004 שכן הוא שבנה את הבית. ואת ברכת \u0003\"הטוב והמטיב\" ביבנה תקנוה\u0004 החכמים שתיאמר \u0003כנגד הרוגי\u0004 העיר \u0003ביתר\u0004 שמזמן בר כוכבא שהובאו לקבורה לאחר שלא נתן אדריינוס לקוברם. שכן \u0003אמר רב מתנא: אותו היום שניתנו הרוגי ביתר לקבורה, תקנו ביבנה\u0004 שתיאמר בברכת המזון אף ברכת \u0003\"הטוב והמטיב\",\u0004 ובפירוש הדברים: \u0003\"הטוב\" — שלא הסריחו\u0004 גופות המתים במשך כל אותו זמן, \u0003\"והמטיב\" — שניתנו לקבורה.\u0004","לאחר שמדובר על סדר הברכות מוסיפים עוד מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא, \u0003סדר ברכת המזון כך היא: ברכה ראשונה\u0004 — \u0003ברכת \"הזן\", שניה\u0004 — \u0003ברכת הארץ, שלישית\u0004 — \u0003\"בונה ירושלים\", רביעית\u0004 — \u0003\"הטוב והמטיב\", ובשבת\u0004 — \u0003מתחיל בנחמה ומסיים בנחמה, ואומר קדושת היום,\u0004 היא הזכרת השבת \u0003באמצע\u0004 כתוספת. \u0003ר' אליעזר אומר:\u0004 את התוספת על קדושת השבת \u0003אם רצה לאומרה בנחמה\u0004 — \u0003אומרה, בברכת הארץ\u0004 — \u0003אומרה, בברכה שתקנו חכמים ביבנה\u0004 \"הטוב והמטיב\" — \u0003אומרה. וחכמים אומרים: אינו אומרה אלא בנחמה בלבד.\u0004","ושואלים: דעת \u0003חכמים היינו תנא קמא\u0004 \u0005[זוהי\u0006 דעת \u0005התנא הראשון],\u0006 שלכאורה החכמים החולקים על ר' אליעזר אומרים כאותה דעה שנזכרה בראש המשנה שעליה חלק ר' אליעזר. ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל זה, ביחס ל\u0003דיעבד\u0004 שמסתם משנה למדים שראוי להזכיר את קדושת השבת בברכת הנחמה, אבל אם הזכיר בברכה אחרת, כנראה יצא, ואילו החכמים מדגישים שאין הזכרה זו אלא בברכת הנחמה בלבד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003מנין לברכת המזון\u0004 שהיא \u0003מן התורה?\u0004 — \u0003שנאמר:\u0004 \"ואכלת ושבעת וברכת את ה' אלהיך על הארץ הטובה אשר נתן לך\" (דברים ח, י), ומפרשים: \u0003\"ואכלת ושבעת וברכת\"\u0004 — \u0003זו ברכת \"הזן\", \"את ה' אלהיך\"\u0004 — \u0003זו ברכת הזמון\u0004 (שמוזכר בה ה'), \u0003\"על הארץ\"\u0004 — הרי \u0003זו ברכת הארץ, \"הטובה\"\u0004 — הרי \u0003זו\u0004 ברכת \u0003\"בונה ירושלים\", וכן הוא אומר \"ההר הטוב הזה והלבנון\"\u0004 (שם ג, כה), שלפי המדרש פירושו ירושלים ובית המקדש. \u0003\"אשר נתן לך\"\u0004 — \u0003זו\u0004 ברכת \u0003\"הטוב והמטיב\".\u0004 ואולם \u0003אין לי\u0004 לימוד מהכתוב \u0003אלא\u0004 על הברכה ש\u0003לאחריו,\u0004 שמכאן למדנו לברכה שאחר המזון, ואולם מקור בכתוב לחובת ברכה ש\u0003לפניו,\u0004 לפני האכילה, \u0003מנין?\u0004 — \u0003אמרת\u0004 שדבר זה יש ללמוד מ\u0003קל וחומר:\u0004 ומה \u0003כשהוא שבע\u0004 כבר — \u0003מברך\u0004 ומודה לה' על המזון, \u0003כשהוא רעב\u0004 — \u0003לא כל שכן,\u0004 ודאי שראוי לו להודות על האוכל.","\u0003רבי אומר: [אינו צריך]\u0004 לדרוש כך את הפסוק, אלא יש להבינו בדרך אחרת במקצת, ובאופן זה: מה שנאמר \u0003\"ואכלת ושבעת וברכת\"\u0004 — \u0003זו ברכת \"הזן\", אבל ברכת הזמון\u0004 מן הכתוב \u0003\"גדלו לה' אתי\u0004 ונרוממה שמו יחדיו\u0003\"\u0004 (תהלים לד, ג) \u0003נפקא\u0004 \u0005[יוצאת,\u0006 נלמדת\u0005],\u0006 והוא מפרש \u0003\"על הארץ\"\u0004 — \u0003זו ברכת הארץ, \"הטובה\"\u0004 — \u0003זו \"בונה ירושלים\", וכן הוא אומר \"ההר הטוב הזה והלבנון\",\u0004 וברכת \u0003\"הטוב והמטיב\"\u0004 אינה רמוזה בתורה, שכן \u0003ביבנה תקנוה. אין לי אלא לאחריו, לפניו מנין? תלמוד לומר\u0004 מקרא יתר: \u0003\"אשר נתן לך\"\u0004 שממנו למדים שיש לברך על המזון \u0003משנתן לך,\u0004 משעה שנתן ה' אותו, ולא רק אחרי האוכל.","\u0003ר' יצחק אומר: אינו צריך\u0004 לראיה זו לברכה ראשונה, ש\u0003הרי הוא אומר \"וברך את לחמך ואת מימיך\"\u0004 (שמות כג, כה) \u0003אל תקרי\u0004 (תקרא) \u0003\"ובירך\" אלא \"וברך\"\u0004 בלשון ציווי, \u0003ואימתי קרוי \"לחם\"\u0004 — \u0003קודם שיאכלנו.\u0004","\u0003ר' נתן אומר: אינו צריך,\u0004 בראיה זו, ש\u0003הרי הוא אומר\u0004 בכתוב במפורש שהנערות אומרות לשאול \u0003\"כבאכם העיר כן תמצאון אותו בטרם יעלה הבמתה לאכול כי לא יאכל העם עד באו כי הוא יברך הזבח אחרי כן יאכלו הקראים\u0004 ועתה עלו כי אותו כהיום תמצאון אותו\" (שמואל א' ט, יג) וכאן מפורשת הברכה שלפני האוכל.","דרך אגב שואלים: \u0003וכל כך למה\u0004 האריכו הנערות בסיפור הדברים? \u0003לפי שהנשים דברניות הן. ושמואל אמר\u0004 טעם אחר: שבכוונה האריכו \u0003כדי להסתכל ביפיו של שאול, דכתיב\u0004 \u0005[שנאמר]\u0006 בו שהיה \"בחור וטוב ואין איש מבני ישראל טוב ממנו \u0003משכמו ומעלה גבה מכל העם\"\u0004 (שם, שם א). \u0003ור' יוחנן אמר שאריכות הדברים היתה כן מלפני ה', לפי שאין מלכות נוגעת בחברתה אפילו כמלוא נימא\u0004 (שערה), והיה צורך לעכב את שאול כדי שיגיע זמן מלכותו בלי שיחסר דבר מתקופת נשיאותו של שמואל.","בהמשך הברייתא הדנה בברכת המזון, מבררים עוד, \u0003ואין לי\u0004 מפורש בתורה \u0003אלא\u0004 החובה לברך \u0003ברכת המזון,\u0004 ואולם ברכת התורה מנין? ולכך הביאו ראיות אחדות. \u0003אמר ר' ישמעאל: קל וחומר\u0004 מברכת המזון, מה אם \u0003על\u0004 המזון שהוא \u0003חיי שעה מברך, על\u0004 התורה שהיא \u0003חיי עולם לא כל שכן\u0004 שמברך. \u0003ר' חייא בר נחמני תלמידו של ר' ישמעאל אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' ישמעאל: אינו צריך\u0004 לקל וחומר זה, ואפשר ללמוד את ההלכה מאותו כתוב, שבברכת המזון \u0003הרי הוא אומר \"על הארץ הטובה אשר נתן לך\", ולהלן\u0004 (והלאה) ביחס לתורה \u0003הוא אומר: \"ואתנה לך את לוחות האבן והתורה והמצוה\u0004 אשר כתבתי להורותם\" (שמות כד, יב) והוא לומד שנתינה זו שמברכים עליה היא נתינת התורה.","מפסוק זה \u0003ר' מאיר אומר: ומנין שכשם שמברך על הטובה כך מברך על הרעה? תלמוד לומר: \"אשר נתן לך ה' אלהיך\",\u0004 ו\"אלהיך\" משמעו: \u0003דיינך,\u0004 שיש לברך \u0003בכל דין שדנך, בין מדה טובה ובין מדת פורענות.\u0004","\u0003ר' יהודה בן בתירא אומר: אינו צריך\u0004 להביא ראיה מפסוק אחר לברכת התורה, ש\u0003הרי הוא אומר:\u0004 \"על הארץ הטובה\", ויש בכלל זה \u0003\"טובה\", \"הטובה\", \"טובה\"\u0004 — \u0003זו תורה, וכן הוא אומר: \"כי לקח טוב נתתי לכם\u0004 תורתי אל תעזובו\" (משלי ד, ב) ואילו \u0003\"הטובה\"\u0004 — \u0003זו בנין ירושלים, וכן הוא אומר \"ההר הטוב הזה והלבנון\".\u0004","ועוד בנוסח ברכת המזון. \u0003תניא ר' אליעזר אומר: כל שלא אמר \"ארץ חמדה טובה ורחבה\" בברכת הארץ, ומלכות בית דוד ב\"בונה ירושלים\"\u0004 — \u0003לא יצא ידי חובתו. נחום הזקן אומר: צריך שיזכיר בה ברית\u0004 המילה. \u0003ר' יוסי אומר: צריך שיזכור בה תורה.\u0004 ו\u0003פלימו\u0004 שהוא אחד מאחרוני התנאים \u0003אומר: צריך שיקדים ברית לתורה, שזו\u0004 התורה \u0003ניתנה בשלש בריתות,\u0004"],["\u0003וזו\u0004 ברית המילה \u0003נתנה בשלש עשרה בריתות,\u0004 ששלוש עשרה פעמים מוזכרת המלה \"ברית\" בפרשת המילה שנצטווה בה אברהם (בראשית יז, א—יד).","\u0003ר' אבא אומר: צריך שיאמר בה\u0004 בברכת ההודאה שבברכת המזון \u0003הודאה תחלה וסוף. ו\u0004עוד אמרו ש\u0003הפוחת\u0004 בברכות ובהודאות \u0003לא יפחות מאחת. וכל הפוחת מאחת\u0004 — \u0003הרי זה מגונה.\u0004","וכן אמרו שאין לשנות בחתימת ברכת הארץ וברכת \"בונה ירושלים\", \u0003וכל החותם \"מנחיל ארצות\" בברכת הארץ, ו\"מושיע את ישראל\" ב\"בונה ירושלים\"\u0004 — \u0003הרי זה בור,\u0004 ששיבש את כוונת הברכה. \u0003וכל שאינו אומר ברית ותורה בברכת הארץ, ומלכות בית דוד ב\"בונה ירושלים\"\u0004 — \u0003לא יצא ידי חובתו.\u0004","ומעירים: הנאמר בברייתא הריהו \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' אילעא,\u0004 שכן \u0003אמר ר' אילעא\u0004 שכך \u0003אמר ר' יעקב בר אחא משום\u0004 \u0005[בשם]\u0006 \u0003רבינו\u0004 (רבי יהודה הנשיא): \u0003כל שלא אמר ברית ותורה בברכת הארץ ומלכות בית דוד ב\"בונה ירושלים\"\u0004 — \u0003לא יצא ידי חובתו.\u0004","\u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה אבא יוסי בן דוסתאי ורבנן\u0004 \u0005[וחכמים]\u0006 בברכת \"הטוב והמטיב\" אם צריך להזכיר בה מלכות או לא. \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: \"הטוב והמטיב\" צריכה\u0004 הזכרת ה\u0003מלכות, וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: אינה צריכה\u0004 הזכרת \u0003מלכות.\u0004 ומסבירים: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר צריכה מלכות קסבר\u0004 \u0005[הוא סבור]\u0006 שברכה זו \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 היא, ואינה נדונה כסמוכה לברכות הקודמות, ועל כן יש להזכיר בה שם ומלכות לחוד. \u0003ומאן\u0004 \u0005[ומי]\u0006 ש\u0003אמר אינה צריכה מלכות קסבר\u0004 \u0005[הוא סבור]\u0006 שאין להזכיר בה מלכות, משום שברכה זו \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 היא, והיא צמודה לברכות הקודמות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מהו\u0004 הלשון שהמברך ברכת המזון \u0003חותם ב\u0004ברכת \u0003\"בונה ירושלים\", ר' יוסי בר' יהודה אומר:\u0004 חותם בלשון \u0003\"מושיע ישראל\".\u0004 על כך תוהים: \u0003\"מושיע ישראל\"\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 חותמים, ואילו בלשון \u0003\"בנין ירושלים\"\u0004 — \u0003לא?\u0004 ומשיבים: \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך את דברי ר' יוסי בר' יהודה: המברך ברכת \"בונה ירושלים\" חותם \u0003אף \"מושיע ישראל\".\u0004","ומסופר: \u0003רבה בר רב הונא איקלע לבי ריש גלותא\u0004 \u0005[נקלע,\u0006 הזדמן, \u0005לבית ראש הגולה],\u0006 בברכת המזון, בברכת \"בונה ירושלים\" \u0003פתח בחדא\u0004 \u0005[באחת],\u0006 במילים \"רחם על ירושלים\" \u0003וסיים בתרתי\u0004 \u0005[בשתים],\u0006 שהזכיר בנין ירושלים ותשועת ישראל. על כך \u0003אמר רב חסדא: גבורתא למחתם בתרתי\u0004 \u0005[גבורה לחתום בשתים]!\u0006 כלומר, כיצד זה יכול אחד החכמים לחתום בשתים, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 כי \u0003רבי אומר: אין חותמין בשתים!\u0004 ולכל ברכה יש חתימה בנושא אחד.","ומעתה דנים בהלכה זו \u0003גופא\u0004 \u0005[גופה].\u0006 \u0003רבי אומר: אין חותמין בשתים!\u0004 על כך \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 תלמידו \u0003לוי לרבי\u0004 מתוך נוסחאות מקובלות של ברכות שונות, והרי אומרים \u0003\"על הארץ ועל המזון\"!\u0004 השיב רבי שלאמיתו של דבר זוהי חתימה בנושא אחד, שכך יש להבין את הברכה: \u0003ארץ דמפקא\u0004 \u0005[שמוציאה]\u0006 \u0003מזון.\u0004 ושוב הקשה לוי מנוסח הברכה \u0003\"על הארץ ועל הפירות\",\u0004 ותירץ לו רבי שכך היא כוונת הברכה: \u0003ארץ דמפקא\u0004 \u0005[שמוציאה]\u0006 \u0003פירות.\u0004","\u0003\"מקדש ישראל והזמנים\"!\u0004 — מקדש \u0003ישראל דקדשינהו\u0004 \u0005[שהם מקדשים]\u0006 את ה\u0003זמנים. \"מקדש ישראל וראשי חדשים\"!\u0004 — \u0003ישראל דקדשינהו\u0004 \u0005[שהם מקדשים]\u0006 את \u0003ראשי חדשים.\u0004","חזר והקשה לוי ממה שמסיימים בשבת שחלה ביום חג \u0003\"מקדש השבת וישראל והזמנים\",\u0004 על כך ענה רבי: \u0003חוץ מזו,\u0004 ושואלים:","\u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 ברכה זו מאחרות? ועונים: \u0003הכא חדא\u0004 \u0005[כאן אחת]\u0006 \u0003היא,\u0004 שזו הודאה לה' על קדושת היום הזה, מה שאין כן בחתימה כפולה בברכת \"בונה ירושלים\" ש\u0003התם תרתי\u0004 \u0005[שם שתים],\u0006 \u0003כל חדא וחדא באפי נפשה\u0004 \u0005[אחת ואחת בפני עצמה].\u0006","ושואלים: \u0003וטעמא מאי\u0004 \u0005[ומה טעם]\u0006 \u0003אין חותמין בשתים!?\u0004 ומשיבים: \u0003לפי ש\u0004כלל הוא, \u0003אין עושין מצות חבילות חבילות,\u0004 שעל כל דבר יש לברך לעצמו.","בסיכומם של דברים עדיין לא הוברר לנו אם יש לומר \"מושיע ישראל\" ב\"בונה ירושלים\", ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה,\u0006 על הלכה זו\u0005]?\u0006","ובכך נחלקו חכמים, \u0003אמר רב ששת:\u0004 אם \u0003פתח ב\"רחם על עמך ישראל\",\u0004 שהזכיר בפתיחה את תשועת ישראל — הריהו אף \u0003חותם ב\"מושיע ישראל\".\u0004 ואם \u0003פתח ב\"רחם על ירושלים\"\u0004 — \u0003חותם ב\"בונה ירושלים\". ורב נחמן אמר: אפילו פתח ב\"רחם על ישראל\"\u0004 — \u0003חותם ב\"בונה ירושלים\", משום שנאמר \"בונה ירושלים ה' נדחי ישראל יכנס\"\u0004 (תהלים קמז, ב), ופירושו: \u0003אימתי בונה ירושלים ה'\"\u0004 — \u0003בזמן ש\"נדחי ישראל יכנס\".\u0004 הרי שבנין ירושלים הוא סמל שכבר היתה גאולת ישראל.","ובענין זה מסופר, שפעם \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לרב חסדא: ניתי מר וניתני\u0004 \u0005[יבוא אדוני וישנה\u0006 משנה\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ברכת מזונא\u0004 \u0005[המזון]\u0006 עדיין \u0003לא גמירנא\u0004 \u0005[למדתי],\u0006 \u0003ותנויי מתנינא\u0004 \u0005[ואשנה משנה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי האי\u0004 \u0005[מהו זה],\u0006 מדוע אומר אתה שעדיין לא למדת ברכת המזון? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דאקלעי לבי ריש גלותא, ובריכי ברכת מזונא, וזקפיה\u0004 \u0005[שנקלעתי לבית ראש הגולה וברכתי ברכת המזון, וזקף ]\u0006 \u0003רב ששת לקועיה\u0004 \u0005[את צוארו]\u0006 \u0003עלי כחיויא\u0004 \u0005[כנחש]\u0006 כלומר, כעס עלי וטען לעומתי. שאל אותו: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 כעס עליך רב ששת? ענה לו: משום ש\u0003לא אמרי\u0004 \u0005[אמרתי]\u0006 בברכת המזון \u0003לא ברית ולא תורה ולא מלכות.\u0004 ושוב תהה ר' זירא: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 \u0003לא אמרת\u0004 דברים אלה? ענה לו שנהג \u0003כ\u0004שיטתו של \u0003רב חננאל\u0004 ש\u0003אמר\u0004 בשם \u0003רב,\u0004 שכך \u0003אמר רב חננאל אמר רב: לא אמר\u0004 בברכת המזון \u0003ברית ותורה ומלכות\u0004 — \u0003יצא\u0004 ידי חובתו, משום שדברים אלה אינם שייכים בכל ישראל: \u0003ברית\u0004 — \u0003לפי שאינה\u0004 שייכת \u0003בנשים, תורה ומלכות\u0004 — \u0003לפי שאינן\u0004 שייכות \u0003לא בנשים ולא בעבדים.\u0004 אמר לו ר' זירא: אכן צדק רב ששת, \u0003ואת שבקת\u0004 \u0005[ואתה עזבת]\u0006 את \u0003כל הני תנאי ואמוראי, ועבדת\u0004 \u0005[אלו התנאים והאמוראים, ועשית ]\u0006 \u0003כרב?!\u0004 שהרי מקודם נאמרו הדברים בשמם של תנאים ואמוראים רבים שפסקו שיש לאמרם.","\u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן:\u0004 ברכת \u0003\"הטוב והמטיב\" צריכה\u0004 הזכרת \u0003מלכות.\u0004 ושואלים \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו,\u0006 חידש לנו בזה]? אם תאמר שהשמיענו ש\u0003כל ברכה שאין בה מלכות\u0004 — \u0003לא שמה ברכה, ו\u0004אולם \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמרה ר' יוחנן\u0004 להלכה זו \u0003חדא זימנא\u0004 \u0005[פעם אחת]!\u0006 \u0003אמר ר' זירא:\u0004 היה צריך \u0003לומר\u0004 בענין \"הטוב והמטיב\" ללמדנו \u0003שצריכה שתי מלכיות\u0004 שיזכירו בה פעמיים את מלכות ה', \u0003חדא דידה וחדא\u0004 \u0005[אחת שלה,\u0006 עבור ברכה זו עצמה, \u0005ואחת]\u0006 עבור \u0003\"בונה ירושלים\".\u0004","על כך שואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שבברכת \"הטוב והמטיב\" מזכירים מלכות נוספת להשלים את הזכרת המלכות אשר לא הוזכרה ב\"בונה ירושלים\", אם כן \u0003ניבעי תלת\u0004 \u0005[שיצטרכו שלוש],\u0006 \u0003חדא דידה\u0004 \u0005[אחת שלה],\u0006 \u0003וחדא\u0004 \u0005[ואחת]\u0006 של \u0003\"בונה ירושלים\", וחדא\u0004 \u0005[ואחת]\u0006 של \u0003ברכת הארץ\u0004 שאף בה לא הוזכרה מלכות! \u0003אלא ברכת הארץ מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 צריך לומר בה מלכות? \u0003משום דהוייא לה\u0004 \u0005[שהריהי]\u0006 \u0003ברכה הסמוכה לחברתה,\u0004 ואם כן \u0003\"בונה ירושלים\" נמי\u0004 \u0005[גם כן],\u0006 \u0003לא תבעי\u0004 \u0005[צריכה]\u0006 כי \u0003הויא לה\u0004 \u0005[היא]\u0006 \u0003ברכה הסמוכה לחברתה!\u0004","ומשיבים: אכן, \u0003הוא הדין\u0004 ש\u0003אפילו \"בונה ירושלים\" נמי\u0004 \u0005[גם כן]\u0006 \u0003לא בעיא\u0004 \u0005[צריכה]\u0006 הזכרת מלכות כשלעצמה, ואולם \u0003איידי דאמר\u0004 \u0005[אגב שאומר\u0006 המברך\u0005]\u0006 \u0003מלכות בית דוד, לאו אורח ארעא\u0004 \u0005[אינו דרך ארץ]\u0006 ש\u0003לא אמר\u0004 \u0005[יאמר]\u0006 גם \u0003מלכות שמים.\u0004 ואילו \u0003רב פפא אמר: צריכה\u0004 ברכת \"הטוב והמטיב\" \u0003שתי מלכיות לבר מדידה\u0004 \u0005[חוץ ממנה],\u0006 אחת עבור \"בונה ירושלים\" ואחת עבור ברכת הארץ.","מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' זירא אחורי דרב גידל\u0004 בבית המדרש, \u0003ויתיב\u0004 \u0005[וישב]\u0006 \u0003רב גידל קמיה\u0004 \u0005[לפני]\u0006 \u0003רב הונא, ויתיב וקאמר\u0004 \u0005[וישב ואמר]:\u0006 \u0003טעה ולא הזכיר\u0004 בברכת המזון את הנוסח \u0003של שבת, אומר\u0004 במקומה נוסח מקוצר: \u0003\"ברוך שנתן שבתות למנוחה לעמו ישראל באהבה לאות ולברית, ברוך מקדש השבת\". אמר ליה\u0004 \u0005[ לו] :\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 \u0003אמרה\u0004 את ההלכה הזאת? ענה לו: \u0003רב.\u0004","\u0003הדר יתיב וקאמר\u0004 \u0005[חזר\u0006 אחר כך, \u0005ישב ואמר]\u0006 הלכה זו: \u0003טעה ולא הזכיר\u0004 בברכת המזון את הנוסח \u0003של יום טוב, אומר: \"ברוך שנתן ימים טובים לעמו ישראל לשמחה ולזכרון, ברוך מקדש ישראל והזמנים\". אמר ליה\u0004 \u0005[ לו] :\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 \u0003אמרה\u0004 את ההלכה הזאת? ענה לו: \u0003רב.\u0004","\u0003הדר יתיב וקאמר\u0004 \u0005[חזר\u0006 שוב, \u0005ישב ואמר]\u0006 הלכה זו: \u0003טעה ולא הזכיר של ראש חודש אומר \"ברוך שנתן ראשי חדשים לעמו ישראל לזכרון\"\u0004 ועל כך מעיר ר' זירא, שסיפר סיפור זה: \u0003ולא ידענא\u0004 \u0005[ואיני יודע,\u0006 איני זוכר\u0005]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר בה\u0004 לשון \u0003\"שמחה\", אי\u0004 \u0005[אם]\u0006 \u0003לא אמר בה\u0004 לשון \u0003\"שמחה\",\u0004 וכן \u0003אי חתים\u0004 \u0005[אם חתם]\u0006 \u0003בה\u0004 בתוספת זו בהזכרת שם ומלכות, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא חתים\u0004 \u0005[חתם]\u0006 \u0003בה, אי דידיה אי דרביה\u0004 \u0005[אם שלו\u0006 היא הלכה זו \u0005או של רבו,\u0006 רב\u0005].\u0006","מסופר: \u0003גידל בר מניומי הווא קאי קמיה\u0004 \u0005[היה עומד לפני]\u0006 \u0003רב נחמן, טעה רב נחמן\u0004 ולא הזכיר את הנוסח של שבת בברכת המזון,"],["\u0003והדר לרישא\u0004 \u0005[וחזר לראש\u0006 הברכה\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 גידל בר מניומי לרב נחמן: \u0003מאי טעמא עביד מר הכי\u0004 \u0005[מה טעם עושה אדוני כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 שכן \u0003אמר ר' שילא\u0004 שכך \u0003אמר רב: טעה\u0004 — \u0003חוזר לראש.\u0004","הקשה לו: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב הונא\u0004 שכך \u0003אמר רב: טעה\u0004 — \u0003אומר \"ברוך שנתן\"! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו איתמר עלה\u0004 \u0005[האם לא נאמר עליה]\u0006 תוספת, שכן \u0003אמר רב מנשיא בר תחליפא\u0004 שכך \u0003אמר רב: לא שנו\u0004 שיכול לומר את הברכה הקצרה \u0003אלא שלא פתח\u0004 עדיין \u0003ב\u0004ברכת \u0003\"הטוב והמטיב\", אבל אם כבר פתח ב\"הטוב והמטיב\"\u0004 — \u0003חוזר לראש\u0004 הברכה.","\u0003אמר רב אידי בר אבין\u0004 שכך \u0003אמר רב עמרם\u0004 שכך \u0003אמר רב נחמן\u0004 שכך \u0003אמר שמואל: טעה ולא הזכיר\u0004 את הנוסח \u0003של ראש חדש בתפלה\u0004 — \u0003מחזירין אותו,\u0004 והטועה \u0003ב\u0004הזכרת ראש החודש \u0003בברכת המזון\u0004 — \u0003אין מחזירין אותו.\u0004","על כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אבין לרב עמרם: מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003תפלה ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003ברכת המזון? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אף לדידי קשיא\u0004 \u0005[לי עצמי היה קשה]\u0006 \u0003לי ושאילתיה\u0004 \u0005[ושאלתיו]\u0006 \u0003לרב נחמן, ואמר לי: מיניה\u0004 \u0005[ממנו]\u0006 מ\u0003מר שמואל\u0004 עצמו \u0003לא שמיע לי\u0004 \u0005[שמעתי],\u0006 \u0003אלא נחזי אנן\u0004 \u0005[נראה אנחנו]\u0006 ונעיין בכוחות עצמנו בענין זה, שההבדל הוא זה: \u0003תפלה\u0004 ש\u0003חובה היא\u0004 — \u0003מחזירין אותו.\u0004 ואילו \u0003ברכת מזונא\u0004 \u0005[המזון],\u0006 \u0003דאי בעי אכיל ואי בעי לא אכיל\u0004 \u0005[שאם הוא רוצה אוכל ואם אינו רוצה אינו אוכל]\u0006 — \u0003אין מחזירין אותו,\u0004 שכיון שברכת המזון אינה חובה גמורה אלא תלויה באכילה שהיא רשות — אין להקפיד בה כל כך.","על כך שאלו: \u0003אלא מעתה שבתות וימים טובים,\u0004 ש\u0003לא סגי\u0004 \u0005[יכול]\u0006 ש\u0003לא אכיל\u0004 \u0005[לאכול]\u0006 שכן יש מצות אכילה בימים אלה — האם \u0003הכי נמי דאי טעי הדר\u0004 \u0005[כך גם כן\u0006 נאמר \u0005שאם טעה\u0006 ולא הזכיר מעין היום בברכת המזון \u0005שיחזור]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 שכן \u0003אמר ר' שילא\u0004 שכך \u0003אמר רב: טעה\u0004 — \u0003חוזר לראש\u0004 הברכה. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב הונא אמר רב: טעה\u0004 — \u0003אומר \"ברוך שנתן\"!\u0004 ודוחים: \u0003לאו איתמר עלה\u0004 \u0005[האם לא נאמר עליה]:\u0006 \u0003לא שנו\u0004 כן \u0003אלא\u0004 כ\u0003ש\u0004עדיין \u0003לא פתח ב\"הטוב והמטיב\", אבל\u0004 אם כבר \u0003פתח ב\"הטוב והמטיב\"\u0004 — \u0003חוזר לראש.\u0004","במשנה הובאה מחלוקת בדבר השיעור הקטן ביותר של אכילה שמזמנים עליו. \u0003עד כמה מזמנין?\u0004 — עד כזית. ר' יהודה אומר: עד כביצה.","הרי שנחלקו בדבר ר' מאיר (שהוא לפי המסורת, התנא שבסתם במשנתנו, החכם שהובאו דבריו ללא ציון שמו) ור' יהודה, ועל כך שואלים: \u0003למימרא\u0004 \u0005[האם נאמר]\u0006 ש\u0003ר' מאיר חשיב ליה\u0004 \u0005[חשוב בעיניו]\u0006 שיעור \u0003כזית, ור' יהודה חשיב ליה\u0004 \u0005[חשוב בעיניו]\u0006 שיעור \u0003כביצה? והא\u0004 \u0005[והרי]\u0006 במקום אחר \u0003איפכא שמעינן להו\u0004 \u0005[ההיפך שמענו אותם\u0006 אומרים\u0005],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]:\u0006 \u0003וכן מי שיצא מירושלים ונזכר שהיה בידו בשר קדש\u0004 האסור בהוצאה מן העיר, \u0003אם עבר\u0004 את הר ה\u0003צופים\u0004 (או מקום במרחק שווה מהר הבית) — \u0003שורפו\u0004 את בשר הקודש \u0003במקומו, ואם לאו\u0004 \u0005[לא]\u0006 עבר עדיין מרחק כזה — \u0003חוזר ושורפו לפני הבירה\u0004 (המקדש) \u0003מעצי המערכה\u0004 שהיו מספקים לצורך שריפת קדשים שנפסלו.","ונשאלה השאלה \u0003עד כמה הם חוזרים?\u0004 מהו שיעור הבשר שבגללו יש לחזור? ובכך נחלקו הדעות, ש\u0003ר' מאיר אומר: זה וזה,\u0004 גם חמץ שדובר בו באותו מקור קודם לכן, וגם בשר קודש \u0003בכביצה. ור' יהודה אומר: זה וזה בכזית,\u0004 היפך דבריהם כאן.","\u0003אמר ר' יוחנן\u0004 ביישוב סתירה זאת: \u0003מוחלפת השיטה,\u0004 כלומר, שבאחד המקורות הוחלפו השיטות, ויש לחזור ולתקן. \u0003אביי אמר: לעולם לא תיפוך\u0004 \u0005[תהפוך],\u0006 אלא \u0003הכא בקראי פליגי\u0004 \u0005[כאן במקראות\u0006 הם \u0005חולקים]\u0006 שבסיס מחלוקתם הוא בפירוש המקרא, ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]\u0006 ש\u0003\"ואכלת\"\u0004 — \u0003זו אכילה, \"ושבעת\"\u0004 — \u0003זו שתיה\u0004 שלאחר האכילה. ויש לנהוג על פי הכלל ההלכתי הידוע ששיעור \u0003אכילה\u0004 הוא \u0003כזית. ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003\"ואכלת ושבעת\"\u0004 — \u0003אכילה שיש בה שביעה, ואיזו זו\u0004 ומהו שיעורה הנמוך ביותר של אכילה כזאת, \u0003כביצה.\u0004","ואילו \u0003התם בסברא פליגי\u0004 \u0005[שם\u0006 בענין חמץ וקודשים, \u0005בסברה\u0006 הם \u0005חולקים],\u0006 ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]\u0006 ש\u0003חזרתו,\u0004 החיוב לחזור ולשרוף את האיסור, הריהי \u0003כ\u0004שיעור \u0003טומאתו. מה טומאתו\u0004 שיעורה \u0003בכביצה, אף חזרתו\u0004 שיעורה \u0003בכביצה. ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003חזרתו כאיסורו,\u0004 שיש לקבוע על פי שיעור האיסור, \u0003מה איסורו בכזית, אף חזרתו בכזית.\u0004","המשנה מפרטת חלוקה מורכבת בדיני ברכת הזימון, בהתאם למספר האנשים. \u0003כיצד מזמנין? ב\u0004זמן שהיו \u0003שלשה\u0004 מסובים — \u0003אומר\u0004 המזמן: \u0003\"נברך שאכלנו משלו\". ב\u0004זמן שהיו \u0003שלשה והוא\u0004 (כלומר, מלבדו) — \u0003אומר \"ברכו\u0004 שאכלנו משלו\", שהרי גם בלעדיו יש שיעור ברכה.","\u0003בעשרה\u0004 — \u0003אומר \"נברך לאלהינו\", בעשרה והוא\u0004 — \u0003אומר \"ברכו\".\u0004 שככל שגדל מספר המשתתפים, יש ברכה מיוחדת ומורכבת יותר. \u0003אחד עשרה ואחד עשרה רבוא,\u0004 ובכל אחת מהן, אם היה אחד יותר אומר \"ברכו\", ובאופן זה:","\u0003במאה\u0004 — \u0003הוא אומר \"נברך ה' אלהינו\", במאה והוא\u0004 — \u0003אומר \"ברכו\". ובאלף\u0004 — \u0003הוא אומר \"נברך לה' אלהינו אלהי ישראל\", באלף והוא\u0004 — \u0003אומר \"ברכו\". ברבוא\u0004 — \u0003אומר \"נברך לה' אלהינו אלהי ישראל אלהי צבאות יושב הכרובים על המזון שאכלנו\", ברבוא והוא\u0004 — \u0003אומר \"ברכו\". והכלל בדבר:\u0004","\u0003כענין שהוא מברך,\u0004 כלומר, לפי הנוסחה שאומר המברך (שהיא לפי רוב הקהל), \u0003כך עונים אחריו\u0004 המזמנים \u0003\"ברוך ה' אלהינו אלהי ישראל אלהי צבאות יושב הכרובים על המזון שאכלנו\".\u0004","ומעין זה \u0003ר' יוסי הגלילי אומר: לפי רוב הקהל הם מברכים, שנאמר\u0004 בכתוב \u0003\"במקהלות ברכו אלהים ה' ממקור ישראל\"\u0004 (תהלים סח, כז). \u0003אמר ר' עקיבא:\u0004 אין מקום לחלק בדבר, שכן \u0003מה מצינו בבית הכנסת, אחד מרובים ואחד מועטים,\u0004 מאחר שיש שם מנין עשרה \u0003אומר\u0004 תמיד בנוסח אחד \u0003\"ברכו את ה'\".\u0004 על כך \u0003ר' ישמעאל אומר\u0004 שאף בבית הכנסת יש לומר בנוסח: \u0003\"ברכו את ה' המבורך\".\u0004","\u0003אמר שמואל: לעולם אל יוציא אדם את עצמו מן הכלל.\u0004","ומקשים על כך \u0003תנן\u0004 \u0005[שנינו ]\u0006 במשנתנו: \u0003בשלשה והוא\u0004 — \u0003אומר \"ברכו\",\u0004 הרי שהמזמן מוציא את עצמו מן הכלל!","על כך עונים: \u0003אימא\u0004 \u0005[אמור]\u0006 שהנאמר במשנה משמעו:"]]};
